            ["boss.scylla"] = ("Scylla · Destroyer", "Scylla · Tàu khu trục"),
            ["boss.sea_corvette"] = ("Escort Corvette", "Tàu hộ vệ"),
            ["boss.silver_bug"] = ("Icarus · Orbital Spacecraft", "Icarus · Phi thuyền quỹ đạo"),
            ["boss.silver_bug_complete"] = ("Icarus · Orbital Spacecraft", "Icarus · Phi thuyền quỹ đạo"),
            ["boss.sky_fortress"] = ("Spectre · Gunship Aircraft", "Spectre · Máy bay pháo"),
            ["boss.supreme_command"] = ("Atlas · Super-Heavy Command Vehicle", "Atlas · Xe chỉ huy siêu nặng"),
            ["boss.typhon"] = ("Typhon · Missile Submarine", "Typhon · Tàu ngầm tên lửa"),
            ["bossfile.argus"] = ("Wolff's armoured recon airship: it sees everything and tells his jets where to go.", "Khí cầu trinh sát bọc giáp của Wolff: thấy hết mọi thứ và chỉ đường cho máy bay của hắn."),
            ["bossfile.armored_train"] = ("Kessler's armoured train: artillery wagons and armour that runs on time. It smokes itself when hit and patches itself on the move. Stop it before it reaches the docks.", "Đoàn tàu bọc thép của Kessler: toa pháo và toa giáp chạy đúng giờ. Bị bắn là nó tự thả khói, vừa chạy vừa tự vá. Phải chặn nó trước khi tới bến cảng."),
            ["bossfile.bastion_mk0"] = ("Brandt's first walking fortress, a prototype of the Bastion: fewer guns, thinner plates, the same stubborn crew.", "Pháo đài biết đi đầu tiên của Brandt, bản nguyên mẫu của Bastion: ít pháo hơn, giáp mỏng hơn, vẫn kíp lái lì lợm ấy."),
            ["bossfile.behemoth"] = ("Varga's land battleship: a main gun that kills a tank a shot, escorts that follow it into battle and a hull that shrugs off most of what the brigade fires. {@mai} says the rear plates are its weakness.", "Chiến hạm mặt đất của Varga: pháo chính mỗi phát hạ một xe tăng, đội hộ tống bám theo vào trận và lớp vỏ chịu được gần hết hỏa lực của lữ đoàn. {@mai} nói các tấm giáp phía sau là điểm yếu của nó."),
            ["bossfile.behemoth_inferno"] = ("A Behemoth rebuilt round two flame projectors and a thermobaric rocket box. It sets the ground itself on fire. Stay out of its reach and keep hitting it.", "Một chiếc Behemoth dựng lại quanh hai súng phun lửa lớn và một hộp rốc-két nhiệt áp. Nó đốt cháy cả mặt đất. Tránh xa tầm với của nó và cứ thế mà nện."),
            ["bossfile.behemoth_mk2"] = ("Varga's Behemoth rebuilt after its first defeat: heavier, heated for the winter, and angrier.", "Chiếc Behemoth của Varga dựng lại sau lần bại trận đầu tiên: nặng hơn, lắp hệ sưởi cho mùa đông, và hung hãn hơn."),
            ["bossfile.behemoth_tempest"] = ("A Behemoth built round a railgun that charges, glows and punches through everything in a line. Two coilguns and a shield. Spread out and close in.", "Một chiếc Behemoth dựng quanh khẩu súng điện từ: nạp điện, phát sáng rồi xuyên thủng mọi thứ trên một đường thẳng. Hai pháo điện từ và một tấm khiên. Dàn quân ra và áp sát."),
            ["bossfile.caspian"] = ("A ground-effect ship that skims the waves at the speed of an aircraft and lands troops on any beach.", "Một con tàu bay sát mặt sóng với tốc độ của máy bay và đổ quân lên bất cứ bãi biển nào."),
            ["bossfile.command_airship"] = ("Wolff's flying headquarters over Skyhold Airbase: radar, missiles and a hangar for drones. It directs every Hegemon aircraft on the coast.", "Sở chỉ huy bay của Wolff trên Căn Cứ Tầng Mây: radar, tên lửa và một khoang chứa drone. Nó điều khiển mọi máy bay Hegemon trên dải duyên hải."),
            ["bossfile.daedalus"] = ("The ship that brings Aurel's troops down from orbit, pod by pod, onto the orbital gate.", "Con tàu đưa quân của Aurel từ quỹ đạo xuống cửa ngõ quỹ đạo, từng khoang một."),
            ["bossfile.drone_mothership"] = ("The Hive's flying carrier: it launches drones from its belly, fires flares and raises a shield when hurt. Only what shoots at the sky can finish it.", "Tàu sân bay biết bay của Hive: phóng drone từ bụng, bắn pháo sáng mồi bẫy và dựng khiên khi bị thương. Chỉ những gì bắn được lên trời mới kết liễu được nó."),
            ["bossfile.earth_borer"] = ("Varga's old tunnelling machine, Tartarus: it grinds under walls and dams and comes up where nobody is looking. Kill it before it reaches the power station.", "Cỗ máy khoan cũ của Varga, Tartarus: nó nghiến xuyên dưới tường thành và thân đập rồi trồi lên đúng chỗ không ai canh. Phải tiêu diệt nó trước khi nó tới trạm phát điện."),
            ["bossfile.fenrir"] = ("Orlov's winter vanguard: a heavy hunter that runs ahead of his gun lines through the snow and marks targets for them.", "Xe tiên phong mùa đông của Orlov: một thợ săn hạng nặng chạy trước các trận địa pháo qua tuyết và đánh dấu mục tiêu cho chúng."),
            ["bossfile.fortress_bastion"] = ("Hegemon's first walking fortress: four autocannon turrets, a heavy mortar and a crew that patches it under fire. The one at Ashfield is an early model, slower and thinner than the ones that came after.", "Pháo đài biết đi đầu tiên của Hegemon: bốn tháp pháo tự động, một khẩu cối hạng nặng và kíp lái biết tự vá giáp dưới làn đạn. Chiếc ở Đồng Tro là mẫu đời đầu, chậm hơn và mỏng hơn những chiếc về sau."),
            ["bossfile.fortress_hive"] = ("Sen's drone fortress: no main gun, just racks that launch swarm after swarm, a SAM battery and flak. Deadly to aircraft; tanks and artillery break it.", "Pháo đài drone của Sen: không có pháo chính, chỉ có các giàn phóng hết bầy này tới bầy khác, một dàn tên lửa phòng không và pháo cao xạ. Cực nguy hiểm với máy bay; xe tăng và pháo binh mới hạ được nó."),
            ["bossfile.frost_monster"] = ("Varga's mobile factory: it builds tanks as it rolls and sends them out of its doors into battle.", "Nhà máy di động của Varga: vừa lăn bánh vừa đóng xe tăng, rồi tung chúng ra trận qua các cửa thả."),
            ["bossfile.frozen_behemoth"] = ("The Behemoth from Dunebreak, dragged north, repaired and heated for the winter. Heavier than before, and angrier.", "Chiếc Behemoth ở Đồi Cát, bị kéo lên phía bắc, sửa lại và lắp hệ sưởi cho mùa đông. Nặng hơn trước, và hung hãn hơn."),
            ["bossfile.hovercraft"] = ("A Hegemon assault hovercraft that carries a company of armour up the beach at sixty knots and covers the landing with its own guns. Hit it before it unloads.", "Tàu đệm khí đổ bộ của Hegemon, chở cả một đại đội thiết giáp lên bãi biển với tốc độ sáu mươi hải lý và tự yểm trợ cuộc đổ bộ bằng pháo của mình. Phải đánh nó trước khi nó kịp dỡ quân."),
            ["bossfile.icarus_mk0"] = ("The unfinished first Icarus, flown over Skyhold Airbase as a field test. Hurt it badly enough and it runs.", "Chiếc Icarus đầu tiên chưa hoàn thiện, bay trên Căn Cứ Tầng Mây như một cuộc thử nghiệm thực địa. Đánh nó đủ đau, nó sẽ bỏ chạy."),
            ["bossfile.ixion"] = ("A mine haul truck with wheels taller than a tank, turned into a battering ram.", "Một xe chở quặng có bánh cao hơn xe tăng, bị biến thành một khối phá thành."),
            ["bossfile.kronos"] = ("A bucket-wheel excavator the size of a building, armoured by {@lyhan} and pointed at the brigade.", "Một máy xúc bánh gầu to bằng cả tòa nhà, được {@lyhan} bọc thép và chĩa thẳng vào lữ đoàn."),
            ["bossfile.landing_craft"] = ("Leviathan's well deck carries three of them, each with two tanks for the beach.", "Khoang đổ bộ của Leviathan chở ba chiếc, mỗi chiếc hai xe tăng cho bãi biển."),
            ["bossfile.landing_hovercraft"] = ("A Hegemon assault hovercraft that carries a company of armour up the beach at sixty knots and covers the landing with its own guns. Hit it before it unloads.", "Tàu đệm khí đổ bộ của Hegemon, chở cả một đại đội thiết giáp lên bãi biển với tốc độ sáu mươi hải lý và tự yểm trợ cuộc đổ bộ bằng pháo của mình. Phải đánh nó trước khi nó kịp dỡ quân."),
            ["bossfile.leviathan"] = ("Kessler's flagship: a battleship hull with a missile cruiser's cells, two 203 mm turrets, a flight deck and a well deck for landing craft. Its sides stop tank shells; its deck does not. It never fights where it cannot leave.", "Soái hạm của Kessler: thân thiết giáp hạm mang ống phóng của tuần dương hạm tên lửa, hai tháp pháo 203 mm, sàn đáp trực thăng và khoang chở tàu đổ bộ. Hông tàu chặn được đạn xe tăng; boong thì không. Nó không bao giờ đánh ở nơi nó không rút được."),
            ["bossfile.locust"] = ("A small carrier from Sen's drone programme. Aurel kept building them after she left.", "Một tàu mang drone cỡ nhỏ trong chương trình drone của Sen. Aurel vẫn cho đóng tiếp sau khi bà bỏ đi."),
            ["bossfile.mega_gunship"] = ("Orlov's gunship, as big as a ship and as slow: rocket pods, flares and an escort of helicopters. Only anti-air and fighters reach it. Bring every launcher you have.", "Pháo hạm bay của Orlov, to như con tàu và chậm như vậy: ổ rốc-két, pháo sáng mồi bẫy và một tốp trực thăng hộ tống. Chỉ phòng không và tiêm kích với tới nó. Mang theo mọi bệ phóng có được."),
            ["bossfile.missile_boat"] = ("Fast, thin boats that dash in to the pier heads with a salvo of rockets and are gone before the smoke clears.", "Những chiếc xuồng nhanh, vỏ mỏng, lao vào đầu cầu tàu bắn một loạt rốc-két rồi biến mất trước khi khói tan."),
            ["bossfile.mobile_fortress"] = ("The anchor of Orlov's Frostpeak line: a mobile fortress with a howitzer, an escort and an EMP that stuns everything round it.", "Mỏ neo của tuyến Đỉnh Sương Giá: một pháo đài di động với lựu pháo, đội hộ tống và xung EMP làm tê liệt mọi thứ xung quanh."),
            ["bossfile.moloch"] = ("Varga's mobile factory: it builds tanks as it rolls and sends them out of its doors into battle.", "Nhà máy di động của Varga: vừa lăn bánh vừa đóng xe tăng, rồi tung chúng ra trận qua các cửa thả."),
            ["bossfile.nuke_train"] = ("A missile train crossing Metro City to its launch site. When it gets there, the countdown starts. Do not let it get there.", "Một đoàn tàu tên lửa đang băng qua Đô Thành tới bãi phóng. Tới nơi là đếm ngược bắt đầu. Đừng để nó tới nơi."),
            ["bossfile.rail_supergun"] = ("A gun too big for any road, pushed along the rails by two tractors. Kessler uses it to shell the port from forty kilometres off.", "Một khẩu pháo quá to cho mọi con đường, được hai đầu kéo đẩy dọc đường ray. Kessler dùng nó nã vào bến cảng từ cách bốn mươi cây số."),
            ["bossfile.scylla"] = ("Kessler's command destroyer: fast, well armed, and always first into the harbour.", "Tàu khu trục chỉ huy của Kessler: nhanh, nhiều vũ khí, và luôn là chiếc đầu tiên vào cảng."),
            ["bossfile.sea_corvette"] = ("Leviathan's escorts: a 76 mm gun and a CIWS that covers the flagship too. Sink them first and the flagship's sky opens.", "Tàu hộ vệ của Leviathan: pháo 76 mm và CIWS che chắn luôn cả tàu chính. Đánh chìm chúng trước thì bầu trời trên tàu chính mở ra."),
            ["bossfile.silver_bug"] = ("Aurel's orbital spacecraft: a big military shuttle with short wings, a silver hull and a huge main engine, meant to strike from orbit and put Aurel beyond anyone's reach. The first one seen runs when it is hurt badly enough. The one on the launch pad is complete.", "Phi thuyền quỹ đạo của Aurel: một tàu con thoi quân sự cỡ lớn, cánh ngắn, vỏ bạc, với động cơ chính khổng lồ, được chế tạo để tấn công từ quỹ đạo và đưa Aurel ra ngoài tầm với của mọi người. Chiếc đầu tiên xuất hiện sẽ bỏ chạy khi bị thương đủ nặng. Chiếc trên bệ phóng đã hoàn chỉnh."),
            ["bossfile.silver_bug_complete"] = ("Icarus 01, the first and only finished Icarus: a reactor that could keep it in orbit for a year, a main engine built to outrun anything that flies, and the warhead from Nemesis. It never reached orbit.", "Icarus 01, chiếc Icarus đầu tiên và duy nhất được hoàn thiện: lò phản ứng đủ sức giữ nó trên quỹ đạo suốt một năm, động cơ chính đủ sức bỏ xa mọi thứ biết bay, và đầu đạn lấy từ Nemesis. Nó chưa bao giờ tới được quỹ đạo."),
            ["bossfile.sky_fortress"] = ("A gunship that circles high over its prey with a 105 mm and two 40 mm guns down its side. It never comes low. Anti-air and fighters, or nothing.", "Pháo hạm bay vòng trên cao quanh con mồi với khẩu 105 mm và hai khẩu 40 mm dọc sườn. Nó không bao giờ hạ thấp. Hoặc phòng không và tiêm kích, hoặc chẳng gì cả."),
            ["bossfile.supreme_command"] = ("Aurel's personal command vehicle, Atlas: the heaviest armour Hegemon ever built, around a communications suite that runs the whole launch site.", "Xe chỉ huy riêng của Aurel, Atlas: lớp giáp nặng nhất Hegemon từng đúc, bao quanh hệ thống liên lạc điều hành toàn bộ bãi phóng."),
            ["bossfile.typhon"] = ("Kessler's missile submarine, now {@lyhan}'s: it surfaces, fires a salvo and dives again.", "Tàu ngầm tên lửa của Kessler, giờ trong tay {@lyhan}: nổi lên, phóng một loạt rồi lại lặn."),
            ["camp.levelLocked"] = ("Opens in the campaign: mission {mission}", "Mở trong chiến dịch: nhiệm vụ {mission}"),
            ["campaign.back"] = ("Back", "Quay lại"),
            ["campaign.chapterKicker"] = ("{act} · Chapter {chapter}", "{act} · Chương {chapter}"),
            ["campaign.comingSoon"] = ("Coming soon", "Sắp ra mắt"),
            ["campaign.comingSoonNote"] = ("This chapter comes in a later update.", "Chương này sẽ có trong bản cập nhật sau."),
            ["campaign.continue"] = ("Continue", "Tiếp tục"),
            ["campaign.deploy"] = ("Deploy", "Xuất kích"),
            ["campaign.dossier"] = ("Dossier", "Hồ sơ"),
            ["campaign.epilogue"] = ("The wreck of Icarus burned on its pad for three days. Aurel was found in the command bunker beneath it, still giving orders to a network that no longer answered. Colonel {@khai} sent the brigade home in stages, the way it had come. Engineer {@mai} kept one Behemoth, \"for the museum\", and nobody believed her. {@dieuhau} flies the coast every morning now, and the sky stays empty. The Operations room stays open, for whoever wants to fight the great battles again, at the hardest tier.", "Xác Icarus cháy trên bệ phóng suốt ba ngày. Người ta tìm thấy Aurel trong hầm chỉ huy bên dưới, vẫn đang ra lệnh cho một mạng lưới không còn ai trả lời. Đại tá {@khai} cho lữ đoàn về từng đợt, như lúc đã đến. Kỹ sư {@mai} giữ lại một chiếc Behemoth, \"để cho bảo tàng\", mà chẳng ai tin cả. Giờ sáng nào {@dieuhau} cũng bay dọc bờ biển, và bầu trời vẫn trống trơn. Phòng Chiến dịch vẫn mở cửa, cho ai muốn đánh lại những trận lớn, ở cấp độ khó nhất."),
            ["campaign.epilogue.title"] = ("Epilogue: Clear Sky", "Vĩ thanh: Bầu trời trong"),
            ["campaign.epilogueGo"] = ("To the Operations room", "Tới phòng Chiến dịch"),
