            ["campaign.rareReward"] = ("{prints|# rare blueprint|# rare blueprints}", "{prints} bản thiết kế hiếm"),
            ["campaign.rewardFirst"] = ("Reward: {coins|# coin|# coins} · {prints|# blueprint|# blueprints}", "Thưởng: {coins} xu · {prints} bản thiết kế"),
            ["campaign.rewardReplay"] = ("Replay reward: {coins|# coin|# coins} · {prints|# blueprint|# blueprints}", "Thưởng chơi lại: {coins} xu · {prints} bản thiết kế"),
            ["campaign.side"] = ("Side mission", "Nhiệm vụ phụ"),
            ["campaign.sideAfter"] = ("Opens after mission {mission}", "Mở sau nhiệm vụ {mission}"),
            ["campaign.story.prologue"] = ("Two years ago, in one night, the private military corporation Hegemon seized the Lam Hai coast it had been paid to guard. Its director, Aurel, turned the ports, the oil fields and the highlands into a laboratory for weapons no army should own. The Coastal Alliance has rebuilt one brigade strong enough to go back: the 7th Mechanised, the Machine Brigade.", "Hai năm trước, chỉ trong một đêm, tập đoàn quân sự tư nhân Hegemon đã chiếm luôn dải duyên hải Lam Hải mà nó được thuê để canh giữ. Giám đốc Aurel biến bến cảng, mỏ dầu và vùng cao nguyên thành phòng thí nghiệm cho những thứ vũ khí không quân đội nào nên có. Liên minh Duyên hải đã dựng lại được một lữ đoàn đủ mạnh để quay về: Lữ đoàn Cơ giới 7, mà lính gọi là Lữ Đoàn Máy."),
            ["campaign.story.title"] = ("Machine Brigade: The Lam Hai Front", "Lữ Đoàn Cơ Giới: Mặt Trận Lam Hải"),
            ["campaign.tbc"] = ("The war is not over. Hegemon still holds the rest of the coast, and the brigade is getting ready for what comes next. The next chapters come in a later update; until then the Operations room is open.", "Cuộc chiến chưa kết thúc. Hegemon vẫn giữ phần còn lại của dải duyên hải, và lữ đoàn đang chuẩn bị cho những gì sắp tới. Các chương tiếp theo sẽ có trong bản cập nhật sau; từ giờ tới đó, phòng Chiến dịch vẫn mở cửa."),
            ["campaign.tbc.title"] = ("To be continued", "Còn tiếp"),
            ["chapter.1.summary"] = ("Dawn over Landing Beach. The landing craft ground on the sand under Hegemon's coastal guns, and the 7th Mechanised Brigade rolls ashore to open the first front in two years. Colonel {@trankhai} has one order: get off the beach, find ground to build on, and take the Ashfield fortress before the enemy wakes up. Behind its walls waits the Bastion, an old walking fortress, still more than enough to stop a brigade that hesitates.", "Bình minh trên Bãi Đổ Bộ. Xuồng đổ bộ tì mũi lên cát dưới làn pháo bờ biển của Hegemon, và Lữ đoàn Cơ giới 7 lăn bánh lên bờ, mở mặt trận đầu tiên sau hai năm. Đại tá {@trankhai} chỉ có một mệnh lệnh: rời bãi biển, tìm chỗ đứng chân, rồi chiếm pháo đài Đồng Tro trước khi địch kịp tỉnh. Sau những bức tường ấy là Bastion, một pháo đài biết đi đã cũ, nhưng vẫn thừa sức chặn một lữ đoàn biết chùn tay."),
            ["chapter.1.title"] = ("Coast of Fire", "Bờ biển lửa"),
            ["chapter.10.summary"] = ("Project Icarus is real: Aurel's orbital spacecraft, built to hang over the coast. Between the brigade and the sky stands Kasimir Wolff, call sign Raven, Hegemon's best pilot and Hawk's old wingman. Take Skyhold Airbase, where he flies from, and the sky belongs to the Alliance.", "Dự án Icarus có thật: phi thuyền quỹ đạo của Aurel, được chế tạo để treo trên bầu trời duyên hải. Giữa lữ đoàn và bầu trời là Kasimir Wolff, biệt danh Raven, phi công giỏi nhất của Hegemon và là đồng đội bay cũ của {@dieuhau}. Chiếm Căn Cứ Tầng Mây, căn cứ nơi hắn cất cánh, là bầu trời thuộc về Liên minh."),
            ["chapter.10.title"] = ("War in the Air", "Chiến tranh trên không"),
            ["chapter.11.summary"] = ("Before Icarus can fly, Aurel needs the orbital gate: the radar stations and side pads that guide his ships up and down. Orlov guards it with Gungnir, his last and biggest gun. Above it all waits Daedalus, the ship that brings Aurel's troops down from orbit.", "Trước khi Icarus cất cánh, Aurel cần cửa ngõ quỹ đạo: các trạm radar và bệ phóng phụ dẫn đường cho tàu của hắn lên xuống. Orlov canh giữ nó bằng Gungnir, khẩu pháo cuối cùng và lớn nhất của hắn. Phía trên tất cả là Daedalus, con tàu đưa quân của Aurel từ quỹ đạo xuống."),
            ["chapter.11.title"] = ("The Orbital Gateway", "Cửa ngõ quỹ đạo"),
            ["chapter.12.summary"] = ("Everything Hegemon has left is at the launch site in the southern desert: Varga and Kessler for one last fight, Sen's drones in Aurel's hands, and Icarus itself on its pad. At the end of the road Aurel waits, ready to go to orbit and leave the war behind.", "Tất cả những gì Hegemon còn lại đều dồn về bãi phóng giữa sa mạc phía nam: Varga và Kessler cho trận cuối, bầy drone của Sen giờ trong tay Aurel, và chính Icarus trên bệ phóng. Ở cuối con đường, Aurel đang chờ, sẵn sàng bay lên quỹ đạo và bỏ lại cuộc chiến phía sau."),
            ["chapter.12.title"] = ("The Icarus Launch Site", "Bãi phóng Icarus"),
            ["chapter.2.summary"] = ("Every Hegemon engine runs on the oil of Dunebreak and Redrock Canyon. Cut it, and the machines starve. The enemy knows it too: General Varga, the man who built the Behemoth, has come south in person to guard his fuel. Ahead lie the pipelines, the wells, the refinery, and whatever monster Varga has parked inside it.", "Mọi cỗ máy của Hegemon đều chạy bằng dầu của Đồi Cát và Hẻm Đá Đỏ. Cắt nguồn dầu, lũ máy sẽ chết đói. Địch cũng biết điều đó: tướng Varga, cha đẻ của Behemoth, đích thân xuống phía nam giữ kho nhiên liệu. Phía trước là đường ống, giếng dầu, nhà máy lọc dầu, và con quái vật nào đó Varga đang giấu bên trong."),
            ["chapter.2.title"] = ("Black Gold", "Vàng đen"),
            ["chapter.3.summary"] = ("Winter comes early to the highlands. Across Frostpeak and Whiteout Pass, Colonel Orlov has built a radar line that sees every convoy, and guns that answer within a minute. His Harpy, a gunship the size of a ship, hunts anything that moves on the snow. The brigade has anti-air now. It will need every launcher to break the line and reach Jötunn behind it.", "Mùa đông về sớm trên cao nguyên. Dọc Đỉnh Sương Giá và Đèo Bão Tuyết, đại tá Orlov dựng một tuyến radar thấy được mọi đoàn xe, cùng những khẩu pháo khai hỏa chưa tới một phút sau. Harpy của hắn, một pháo hạm bay to như con tàu, săn mọi thứ nhúc nhích trên tuyết. Lữ đoàn giờ đã có phòng không. Sẽ cần đến từng bệ phóng để phá tuyến radar và tới được Jötunn phía sau."),
            ["chapter.3.title"] = ("The Long Winter", "Mùa đông dài"),
            ["chapter.4.summary"] = ("Everything Hegemon builds leaves through Ironport. Admiral Kessler runs its cranes, its rails and its armoured trains to a timetable nobody has ever seen broken. The Alliance goes over to the attack: take the Rust Yard, cut the rail lines, and seize the port itself. On the docks, {@linh}'s intercepts keep mentioning Tempest: one of Varga's Behemoths, waiting for Kessler's next ship.", "Mọi thứ Hegemon chế tạo đều đi qua Cảng Thép. Đô đốc Kessler điều hành cần cẩu, đường ray và những đoàn tàu bọc thép theo một thời gian biểu chưa ai thấy trễ bao giờ. Liên minh chuyển sang phản công: chiếm Bãi Sắt Gỉ, cắt đường ray, rồi đánh chiếm chính bến cảng. Trên cầu tàu, các bản chặn thu của {@linh} cứ nhắc mãi tới Tempest: một chiếc Behemoth của Varga đang chờ chuyến tàu tiếp theo của Kessler."),
            ["chapter.4.title"] = ("Steel Harbour", "Cảng thép"),
            ["chapter.5.summary"] = ("Under the volcanoes of Ember Ridge and the canopy of Jungle Pass, Dr Sen builds drones by the thousand. Her masterpiece, the Hive, can blacken the sky over a whole division; its mothership carries the swarm wherever Hegemon points it. Burn the drone works and the sky clears. But {@linh} has noticed something odd: Sen's own messages are getting shorter, and angrier.", "Dưới chân núi lửa Sườn Dung Nham và tán rừng Đèo Rừng Rậm, tiến sĩ Sen chế tạo drone theo từng nghìn chiếc. Kiệt tác của bà, Hive, có thể che đen bầu trời trên cả một sư đoàn; tàu mẹ của nó chở bầy drone tới bất cứ đâu Hegemon chỉ tay. Đốt xưởng drone thì bầu trời sẽ sạch. Nhưng {@linh} để ý một điều lạ: các bức điện của chính Sen cứ ngắn dần, và gay gắt dần."),
            ["chapter.5.title"] = ("Jungle Fire", "Lửa rừng"),
            ["chapter.6.summary"] = ("Hegemon strikes back. Varga throws everything left at the ground the brigade took in the first act: Ashfield, Whiteout Pass, the beach, and the Hydro Dam that lights half the coast. Engineer {@mai} has done the impossible and got a captured Behemoth running for our side. Varga has done something worse: Moloch, his factory on tracks, is heading for the dam, and General {@lyhan}'s relief army is days away.", "Hegemon phản đòn. Varga ném tất cả những gì còn lại vào những vùng đất lữ đoàn đã chiếm ở hồi đầu: Đồng Tro, Đèo Bão Tuyết, bãi biển, và Đập Thủy Điện thắp sáng nửa dải duyên hải. Kỹ sư {@mai} đã làm được điều không tưởng: cho một chiếc Behemoth bắt được chạy về phía ta. Varga làm được điều tệ hơn: Moloch, nhà máy bánh xích của hắn, đang tiến về con đập, trong khi đạo quân cứu viện của tướng {@lyhan} còn cách nhiều ngày đường."),
            ["chapter.6.title"] = ("Counterstrike", "Tổng phản công"),
            ["chapter.7.summary"] = ("The road runs through Metro City to {@lamthanh}, the capital. General {@lyhan} brings his Northern Army to join the liberation, with a base of his own and his own plans for the city. Under the streets, Nemesis, Hegemon's missile train, is moving.", "Con đường chạy qua Đô Thành tới {@lamthanh}, thủ đô. Tướng {@lyhan} kéo Tập đoàn quân Phương Bắc tới cùng giải phóng, với căn cứ riêng và những toan tính riêng cho thành phố. Dưới lòng phố, Nemesis, đoàn tàu tên lửa của Hegemon, đang lăn bánh."),
            ["chapter.7.title"] = ("The Capital", "Thủ đô"),
            ["chapter.8.summary"] = ("{@lyhan} has run north to the open-pit mines where Hegemon digs the metal for its machines. He holds the pits with his own army and the diggers Aurel left behind. Somewhere in the deepest pit, Kronos is waking up.", "{@lyhan} đã chạy lên các mỏ lộ thiên phía bắc, nơi Hegemon đào kim loại cho những cỗ máy của nó. Hắn giữ các hố mỏ bằng quân riêng và những cỗ máy đào Aurel để lại. Đâu đó dưới hố sâu nhất, Kronos đang thức giấc."),
            ["chapter.8.title"] = ("Underground", "Lòng đất"),
            ["chapter.9.summary"] = ("{@lyhan} has found what is left of Kessler's fleet and made it his own. From the harbours of the coast he means to hold the sea, with Scylla back in service and a missile submarine, Typhon, somewhere under the waves. This is where he has to be stopped.", "{@lyhan} đã tìm thấy tàn quân hạm đội của Kessler và biến nó thành của mình. Từ các bến cảng dọc bờ biển, hắn định giữ lấy biển, với Scylla trở lại hoạt động và một tàu ngầm tên lửa, Typhon, ẩn đâu đó dưới sóng. Đây là nơi phải chặn hắn lại."),
            ["chapter.9.title"] = ("Rough Seas", "Biển động"),
            ["char.aurel.bio"] = ("Aurel talks about war the way accountants talk about quarterly results. He took the coast because the contract allowed it, and he built Icarus because nobody could stop him. He commands the best of everything, and he plans to never be in range of any of it.", "Aurel nói về chiến tranh như kế toán nói về báo cáo quý. Hắn chiếm dải duyên hải vì hợp đồng cho phép, và chế tạo Icarus vì chẳng ai ngăn nổi. Hắn chỉ huy những thứ tốt nhất của mọi loại, và định sẽ không bao giờ đứng trong tầm bắn của thứ nào."),
            ["char.aurel.name"] = ("Director Lucien Aurel", "Giám đốc Lucien Aurel"),
            ["char.aurel.role"] = ("Head of Hegemon, call sign Sol; Project Icarus · boss names: Greek sky myths", "Người đứng đầu Hegemon, biệt danh Sol; Dự án Icarus · tên boss: thần thoại Hy Lạp về bầu trời"),
            ["char.brandt.bio"] = ("Brandt commands the garrison that was meant to keep the Alliance off the beach. A careful officer who trusts concrete more than men, he names his fortresses as if they were old friends: Bastion first of all.", "Brandt chỉ huy đạo quân đồn trú có nhiệm vụ chặn Liên minh ngoài bãi biển. Một sĩ quan cẩn trọng, tin bê tông hơn tin người, hắn đặt tên cho các pháo đài như gọi bạn cũ: trước hết là Bastion."),
            ["char.brandt.name"] = ("Major Brandt", "Thiếu tá Brandt"),
            ["char.brandt.role"] = ("Hegemon coastal garrison · boss names: fortresses", "Đồn trú duyên hải của Hegemon · tên boss: pháo đài"),
            ["char.dieuhau.bio"] = ("Captain {@lephong}, call sign {@dieuhau} (Hawk), flies everything the brigade owns that leaves the ground. Loud, cheerful, better than he admits. He trained at the same school as {@quaden}, and they were wingmen, once.", "Đại úy {@lephong}, tên gọi {@dieuhau}, lái mọi thứ biết cất cánh của lữ đoàn. Ồn ào, vui tính, và giỏi hơn những gì anh chịu nhận. Anh học cùng trường bay với {@quaden}, và đã từng là đồng đội bay kèm của hắn."),
            ["char.dieuhau.name"] = ("{@dieuhau}", "{@dieuhau}"),
            ["char.dieuhau.role"] = ("Pilot; leads the air wing, radio call sign Hawk", "Phi công, chỉ huy phi đội; tên gọi trên sóng: Hawk"),
            ["char.hq.name"] = ("Brigade HQ", "Sở chỉ huy Lữ đoàn"),
            ["char.hq.role"] = ("Radio", "Bộ đàm"),
            ["char.hung.bio"] = ("{@lyhan} commands the Alliance's largest army and never lets anyone forget it. Brave, generous with his men, hungry for the one thing a liberator can take: the city he frees. He fights beside the brigade in the great operations, with a base of his own.", "{@lyhan} chỉ huy đạo quân lớn nhất của Liên minh và không bao giờ để ai quên điều đó. Dũng cảm, hào phóng với lính của mình, và thèm khát đúng một thứ mà người giải phóng có thể lấy: thành phố ông giải phóng. Ông sát cánh cùng lữ đoàn trong các chiến dịch lớn, với căn cứ riêng."),
            ["char.hung.name"] = ("General {@lyhan}", "Tướng {@lyhan}"),
            ["char.hung.role"] = ("Alliance Northern Army, then traitor; call sign Titan · boss names: the Greek Titans", "Tập đoàn quân Phương Bắc của Liên minh, rồi phản bội; biệt danh Titan · tên boss: các Titan Hy Lạp"),
            ["char.kessler.bio"] = ("Kessler has never lost a shipment, a train or an argument about a timetable. He runs Hegemon's ports and rail lines, and armours both. His armies are balanced to the gram, his bases a little of everything, and he mines anything he cannot hold.", "Kessler chưa từng để thất lạc một chuyến hàng, một đoàn tàu hay thua một cuộc cãi về thời gian biểu. Hắn điều hành bến cảng và đường sắt của Hegemon, và bọc thép cả hai. Quân của hắn cân bằng đến từng gam, căn cứ của hắn thứ gì cũng có một ít, và hắn rải mìn bất cứ chỗ nào không giữ nổi."),
            ["char.kessler.name"] = ("Admiral Magnus Kessler", "Đô đốc Magnus Kessler"),
            ["char.kessler.role"] = ("Hegemon ports and trains, call sign Maelstrom · boss names: sea monsters", "Bến cảng và đường sắt Hegemon, biệt danh Maelstrom · tên boss: quái vật biển"),
            ["char.khai.bio"] = ("Fifty-two, calm, practical, never heard to raise his voice on the radio. {@khai} lost his home town on the Night of Steel and does not talk about it. He plans battles like a mechanic fixes an engine: find what is broken, fix that, move on.", "Năm mươi hai tuổi, điềm tĩnh, thực tế, chưa ai nghe ông lớn tiếng trên sóng bộ đàm. {@khai} mất quê nhà trong Đêm Thép và không bao giờ nhắc tới. Ông lên kế hoạch trận đánh như thợ máy sửa động cơ: tìm chỗ hỏng, sửa chỗ đó, rồi đi tiếp."),
            ["char.khai.name"] = ("Colonel {@trankhai}", "Đại tá {@trankhai}"),
            ["char.khai.role"] = ("Commander, 7th Mechanised Brigade; command call sign Iron", "Chỉ huy Lữ đoàn Cơ giới 7; biệt danh chỉ huy: Iron"),
            ["char.linh.bio"] = ("{@linh} reads Hegemon's mail. Intercepts, captured drives, a burnt notebook: she turns them into targets, and into the side jobs nobody else has time for. Precise, patient, and the only one who can make Colonel {@khai} laugh.", "{@linh} đọc thư của Hegemon. Bản chặn thu, ổ cứng thu được, một cuốn sổ cháy dở: cô biến tất cả thành mục tiêu, và thành những nhiệm vụ phụ không ai có thời gian làm. Chính xác, kiên nhẫn, và là người duy nhất làm được đại tá {@khai} bật cười."),
            ["char.linh.name"] = ("Lieutenant {@linh}", "Trung úy {@linh}"),
            ["char.linh.role"] = ("Intelligence officer", "Sĩ quan tình báo"),
            ["char.mai.bio"] = ("{@mai} keeps the brigade's base running and signs off every HQ upgrade. For three years she welded Behemoth hulls for Hegemon as a contract engineer, until she understood what they were for and walked out. She knows every weak seam in Varga's machines, and she has not forgiven herself for any of them.", "{@mai} giữ cho căn cứ của lữ đoàn vận hành và là người ký duyệt mọi lần nâng cấp sở chỉ huy. Suốt ba năm, cô hàn vỏ Behemoth cho Hegemon theo hợp đồng, cho đến khi hiểu chúng được làm ra để làm gì và bỏ đi. Cô biết từng đường hàn yếu trên những cỗ máy của Varga, và chưa tha thứ cho mình vì bất cứ đường nào."),
            ["char.mai.name"] = ("Engineer {@mai}", "Kỹ sư {@mai}"),
            ["char.mai.role"] = ("Chief engineer; runs the base", "Kỹ sư trưởng, phụ trách căn cứ"),
            ["char.orlov.bio"] = ("Orlov has never seen the face of a man he killed, and prefers it that way. He fights from thirty kilometres off, with radar, rockets and patience. His bases are gun lines; his armies screen his batteries and wait for the shells to do the work.", "Orlov chưa từng nhìn mặt người nào hắn giết, và hắn muốn thế. Hắn đánh từ cách xa ba mươi cây số, bằng radar, rốc-két và sự kiên nhẫn. Căn cứ của hắn là những trận địa pháo; quân của hắn che chắn cho các khẩu đội và chờ đạn pháo làm nốt phần việc."),
            ["char.orlov.name"] = ("Colonel Ilya Orlov", "Đại tá Ilya Orlov"),
            ["char.orlov.role"] = ("Hegemon artillery, call sign Winter · boss names: Norse winter myths", "Pháo binh Hegemon, biệt danh Winter · tên boss: thần thoại Bắc Âu, mùa đông"),
            ["char.quaden.bio"] = ("His name is Kasimir Wolff, call sign Raven; our side still calls him {@quaden}. He commands Hegemon's air wing from Skyhold Airbase and has more kills than the rest of it together. He flies gunships, jets and drones in one screaming wave, and his bases are ringed with missiles. He and {@dieuhau} have unfinished business.", "Tên hắn là Kasimir Wolff, biệt danh Raven; bên ta vẫn gọi hắn là {@quaden}. Hắn chỉ huy lực lượng không quân Hegemon từ Căn Cứ Tầng Mây và có số lần hạ địch nhiều hơn cả phần còn lại cộng lại. Hắn tung trực thăng, phản lực và drone thành một đợt gào thét, và căn cứ của hắn vây kín tên lửa. Giữa hắn và {@dieuhau} còn một món nợ chưa trả."),
            ["char.quaden.name"] = ("Kasimir Wolff", "Kasimir Wolff"),
            ["char.quaden.role"] = ("Hegemon air force ace, call sign Raven · boss names: mythic birds", "Át chủ bài không quân Hegemon, biệt danh Raven · tên boss: chim thần thoại"),
            ["char.sen.bio"] = ("Sen builds swarms the way other people knit. The Hive was meant to be a rescue system for disaster zones; Hegemon armed it before she finished her coffee. She fights with drones, jammers and hangars full of both, and she has begun to wonder who she is working for.", "Sen tạo ra bầy drone như người khác đan len. Hive vốn được thiết kế làm hệ thống cứu hộ cho vùng thảm họa; Hegemon vũ trang cho nó trước khi bà kịp uống xong ly cà phê. Bà đánh bằng drone, xe gây nhiễu và những nhà chứa đầy cả hai thứ, và bà bắt đầu tự hỏi mình đang làm việc cho ai."),
            ["char.sen.name"] = ("Dr Elara Sen", "Tiến sĩ Elara Sen"),
            ["char.sen.role"] = ("Hegemon drones, call sign Queen · boss names: insects and swarms", "Drone của Hegemon, biệt danh Queen · tên boss: côn trùng, bầy đàn"),
            ["char.varga.bio"] = ("Varga believes weight wins wars. He designed the Behemoth on a napkin and spent a nation's budget building it. Brave, stubborn, loyal to his machines more than to Aurel. His armies are all tanks and tank killers; his bases bristle with anti-tank guns.", "Varga tin rằng sức nặng thắng được chiến tranh. Hắn vẽ Behemoth trên một tờ giấy ăn rồi tiêu ngân sách của cả một quốc gia để chế tạo nó. Gan lì, cứng đầu, trung thành với những cỗ máy của mình hơn là với Aurel. Quân của hắn toàn xe tăng và xe diệt tăng; căn cứ của hắn dựng đầy pháo chống tăng."),
            ["char.varga.name"] = ("General Viktor Varga", "Tướng Viktor Varga"),
            ["char.varga.role"] = ("Hegemon armour, call sign Anvil · boss names: giant monsters", "Thiết giáp Hegemon, biệt danh Anvil · tên boss: quái vật khổng lồ"),
            ["choice.c10m10.fuel"] = ("Burn the fuel park", "Đốt bãi nhiên liệu"),
            ["choice.c10m10.fuel.info"] = ("Wolff earns 30% less for the rest of the battle.", "Wolff kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c10m10.tower"] = ("Destroy the control tower and radome", "Phá tháp điều khiển và vòm radar"),
            ["choice.c10m10.tower.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c11m10.depots"] = ("Blow the fuel depots", "Cho nổ kho nhiên liệu"),
            ["choice.c11m10.depots.info"] = ("Aurel's army earns 30% less for the rest of the battle.", "Quân Aurel kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c11m10.radars"] = ("Destroy the fortress radars", "Phá radar của pháo đài"),
            ["choice.c11m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c12m10.propellant"] = ("Burn the propellant tanks", "Đốt các bồn nhiên liệu đẩy"),
            ["choice.c12m10.propellant.info"] = ("Aurel earns 30% less for the rest of the battle.", "Aurel kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c12m10.radars"] = ("Destroy the west radars", "Phá radar phía tây"),
            ["choice.c12m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c1m10.dump"] = ("Blow the ammunition dumps", "Cho nổ kho đạn"),
            ["choice.c1m10.dump.info"] = ("The garrison earns 30% less for the rest of the battle.", "Quân địch kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c1m10.radar"] = ("Knock out the radar", "Phá trạm radar"),
            ["choice.c1m10.radar.info"] = ("{@dieuhau} can reach the fortress: a free airstrike about every minute.", "{@dieuhau} bay tới được pháo đài: một đợt không kích miễn phí khoảng mỗi phút."),
            ["choice.c2m10.oasis"] = ("Hold the oasis radio", "Giữ đài phát ốc đảo"),
            ["choice.c2m10.oasis.info"] = ("Hold it 90 s: {@dieuhau}'s airstrikes, free, about every minute.", "Giữ 90 giây: không kích miễn phí của {@dieuhau}, khoảng mỗi phút một lượt."),
            ["choice.c2m10.tanks"] = ("Burn the fuel tanks", "Đốt bồn nhiên liệu"),
            ["choice.c2m10.tanks.info"] = ("Varga's army earns 30% less for the rest of the battle.", "Quân Varga kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c3m10.depots"] = ("Blow the fuel depots", "Cho nổ kho nhiên liệu"),
            ["choice.c3m10.depots.info"] = ("Orlov's army earns 30% less for the rest of the battle.", "Quân Orlov kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c3m10.radars"] = ("Destroy the fortress radars", "Phá radar của pháo đài"),
            ["choice.c3m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c4m10.crane"] = ("Burn the fuel wagons", "Đốt các toa nhiên liệu"),
            ["choice.c4m10.crane.info"] = ("Kessler earns 30% less for the rest of the battle.", "Kessler kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c4m10.signal"] = ("Hold the signal box (150 s)", "Giữ trạm tín hiệu (150 giây)"),
