            ["choice.c6m10.station.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c7m10.gardens"] = ("Hold the gardens (150 s)", "Giữ khu vườn (150 giây)"),
            ["choice.c7m10.gardens.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c7m10.ministry"] = ("Burn the supply ministry", "Đốt Bộ Hậu cần"),
            ["choice.c7m10.ministry.info"] = ("Aurel's guard earns 30% less for the rest of the battle.", "Vệ binh của Aurel kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c8m10.oasis"] = ("Hold the crusher's radio", "Giữ đài phát ở nhà máy nghiền"),
            ["choice.c8m10.oasis.info"] = ("Hold it 90 s: {@dieuhau}'s airstrikes, free, about every minute.", "Giữ 90 giây: không kích miễn phí của {@dieuhau}, khoảng mỗi phút một lượt."),
            ["choice.c8m10.tanks"] = ("Burn the fuel store", "Đốt kho nhiên liệu"),
            ["choice.c8m10.tanks.info"] = ("{@lyhan}'s army earns 30% less for the rest of the battle.", "Quân {@lyhan} kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c9m10.crane"] = ("Burn the fuel wagons", "Đốt các toa nhiên liệu"),
            ["choice.c9m10.crane.info"] = ("{@lyhan} earns 30% less for the rest of the battle.", "{@lyhan} kiếm được ít hơn 30% trong suốt phần còn lại của trận."),
            ["choice.c9m10.signal"] = ("Hold the signal box (150 s)", "Giữ trạm tín hiệu (150 giây)"),
            ["choice.c9m10.signal.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["dossier.before"] = ("Before the landing", "Trước cuộc đổ bộ"),
            ["dossier.bosses"] = ("Boss files", "Hồ sơ boss"),
            ["dossier.chapterFiles"] = ("Chapter {chapter}", "Chương {chapter}"),
            ["dossier.empty"] = ("Every mission won adds a file here.", "Mỗi nhiệm vụ giành thắng lợi sẽ thêm một tư liệu vào đây."),
            ["dossier.files"] = ("Story files", "Tư liệu"),
            ["dossier.locked"] = ("Not met yet.", "Chưa gặp mặt."),
            ["dossier.lockedBoss"] = ("Beat it to open its file.", "Hạ gục nó để mở hồ sơ."),
            ["dossier.lockedChapter"] = ("Not yet written.", "Chưa được viết nên."),
            ["dossier.people"] = ("People", "Nhân vật"),
            ["dossier.timeline"] = ("Timeline", "Dòng thời gian"),
            ["goal.duel"] = ("Destroy the general's HQ", "Phá sở chỉ huy của tướng địch"),
            ["goal.evacuate"] = ("Evacuate", "Sơ tán"),
            ["goal.outpost"] = ("Set up an outpost", "Lập tiền đồn"),
            ["goal.relieve"] = ("Break the siege", "Giải vây"),
            ["mission.c10m01.brief"] = ("With Sen's files in hand, the brigade turns towards Skyhold Airbase. Wolff's air wing meets us over Frostpeak, coming from the south this time. Bring twelve of them down.", "Cầm trong tay hồ sơ của Sen, lữ đoàn quay mũi về Căn Cứ Tầng Mây. Phi đội của Wolff đón đánh ta trên Đỉnh Sương Giá, lần này từ phía nam. Bắn rơi mười hai chiếc."),
            ["mission.c10m01.fragment"] = ("Sen's files, first page: \"Project Icarus Full-scale flight article. Laser, coilguns, field shield. Target date for deployment over the capital: spring.\" It was already autumn.", "Hồ sơ của Sen, trang đầu: \"Dự án Icarus Nguyên mẫu bay cỡ thật. La-de, súng điện từ, khiên trường lực. Ngày dự kiến triển khai trên bầu trời thủ đô: mùa xuân.\" Lúc đó đã là mùa thu."),
            ["mission.c10m01.fragment.title"] = ("Sen's files", "Hồ sơ của Sen"),
            ["mission.c10m01.name"] = ("Crows over the Pass", "Bầy quạ trên đèo"),
            ["mission.c10m02.brief"] = ("Before we hit the air base, {@linh} wants to see it: the two aprons and the runway. Get a vehicle onto each, under Wolff's nose.", "Trước khi đánh căn cứ không quân, {@linh} muốn tận mắt thấy nó: hai sân đỗ và đường băng. Đưa xe tới từng nơi, ngay dưới mũi Wolff."),
            ["mission.c10m02.fragment"] = ("The recon team photographed a hangar with its doors welded shut and cooling pipes running into the ground. Sen looked at the photograph for a long time. \"That is it,\" she said.", "Tổ trinh sát chụp được một nhà chứa máy bay cửa bị hàn chết, ống làm lạnh chạy xuống lòng đất. Sen nhìn tấm ảnh rất lâu. \"Chính là nó,\" bà nói."),
            ["mission.c10m02.fragment.title"] = ("The hangar", "Nhà chứa máy bay"),
            ["mission.c10m02.name"] = ("Eyes on Skyhold Airbase", "Mắt nhìn Căn Cứ Tầng Mây"),
            ["mission.c10m03.brief"] = ("Orlov's old radar on the heights now watches the sky for us, and the village church is our aid station. Wolff wants both gone. Keep one standing for seven minutes.", "Trạm radar cũ của Orlov trên cao điểm giờ canh bầu trời cho ta, còn nhà thờ trong làng là trạm cứu thương. Wolff muốn xóa sổ cả hai. Giữ ít nhất một công trình đứng vững bảy phút."),
            ["mission.c10m03.fragment"] = ("Orlov's radar still had his crew's coffee cups on the console. The brigade's operators kept using them. \"Orlov's cups,\" they called them, with some respect.", "Trạm radar của Orlov vẫn còn những cốc cà phê của kíp trực trên bàn điều khiển. Người của lữ đoàn cứ thế dùng tiếp. Họ gọi đó là \"cốc của Orlov\", với chút kính nể."),
            ["mission.c10m03.fragment.title"] = ("Borrowed eyes", "Đôi mắt đi mượn"),
            ["mission.c10m03.name"] = ("Our Radar Now", "Radar giờ là của ta"),
            ["mission.c10m04.brief"] = ("A night raid on the western apron of Skyhold Airbase: Wolff's strike jets are parked in a row. Burn them where they stand.", "Một trận đột kích đêm vào sân đỗ phía tây Căn Cứ Tầng Mây: máy bay cường kích của Wolff đang đỗ thành hàng. Đốt chúng ngay tại chỗ."),
            ["mission.c10m04.fragment"] = ("Wolff parked his jets wingtip to wingtip, the way they do at air shows. His ground crew had warned him. He liked the way it looked.", "Wolff cho đỗ máy bay sát cánh nhau, kiểu người ta vẫn làm ở các buổi trình diễn. Tổ kỹ thuật mặt đất đã cảnh báo hắn. Hắn thích trông nó như thế."),
            ["mission.c10m04.fragment.title"] = ("The row", "Hàng máy bay"),
            ["mission.c10m04.name"] = ("Burn the Jets", "Đốt máy bay"),
            ["mission.c10m05.brief"] = ("The welded hangar opened at dawn. Icarus is in the air over Skyhold Airbase: Aurel's orbital spacecraft, silver-hulled and short-winged, with a main engine that could outrun anything we have. It is not finished, Sen says. Hurt it badly enough, and it will run.", "Nhà chứa bị hàn cửa đã mở lúc bình minh. Icarus đang ở trên không phận Căn Cứ Tầng Mây: phi thuyền quỹ đạo của Aurel, vỏ bạc, cánh ngắn, với động cơ chính đủ sức bỏ xa bất cứ thứ gì ta có. Sen nói nó chưa hoàn thiện. Đánh nó đủ đau, nó sẽ bỏ chạy."),
            ["mission.c10m05.fragment"] = ("Icarus broke off at half strength and flew south at a speed nothing of ours can match. {@linh} tracked it until it vanished over the desert. Towards the launch site.", "Icarus tháo chạy khi còn một nửa sức mạnh và bay về phía nam với tốc độ không thứ gì của ta đuổi kịp. {@linh} theo dấu nó cho tới khi nó biến mất trên sa mạc. Về phía bãi phóng."),
            ["mission.c10m05.fragment.title"] = ("It runs", "Nó bỏ chạy"),
            ["mission.c10m05.name"] = ("Icarus Mk.0", "Icarus Mk.0"),
            ["mission.c10m06.brief"] = ("Wolff has hidden long-range SAMs in the fog to shield his air base. {@linh} has marked three launchers. Hunt them so {@dieuhau} can fly.", "Wolff giấu các dàn tên lửa phòng không tầm xa trong sương để che chắn căn cứ. {@linh} đã đánh dấu ba bệ phóng. Săn chúng để {@dieuhau} được bay."),
            ["mission.c10m06.fragment"] = ("With the missile screen gone, {@dieuhau} flew over Skyhold Airbase at noon and waggled his wings over the control tower. Wolff did not come up. That worried everyone.", "Màn tên lửa bị xóa sổ, {@dieuhau} bay qua Căn Cứ Tầng Mây giữa trưa và lắc cánh ngay trên tháp điều khiển. Wolff không cất cánh. Điều đó khiến ai cũng lo."),
            ["mission.c10m06.fragment.title"] = ("Clear air", "Bầu trời thông thoáng"),
            ["mission.c10m06.name"] = ("The Missile Screen", "Màn tên lửa"),
            ["mission.c10m07.brief"] = ("Wolff answers with everything he has: wave after wave over our positions round Skyhold Airbase. Bring down sixteen.", "Wolff đáp trả bằng tất cả những gì hắn có: từng đợt, từng đợt máy bay lao vào trận địa của ta quanh Căn Cứ Tầng Mây. Bắn rơi mười sáu chiếc."),
            ["mission.c10m07.fragment"] = ("Of the sixteen aircraft shot down that day, four were flown by pilots who had trained with {@dieuhau}. He went to see the two who survived, in the hospital.", "Trong mười sáu chiếc bị bắn rơi hôm đó, bốn chiếc do những phi công từng học cùng {@dieuhau} lái. Anh vào bệnh viện thăm hai người còn sống sót."),
            ["mission.c10m07.fragment.title"] = ("Sixteen", "Mười sáu"),
            ["mission.c10m07.name"] = ("Air Raid", "Không kích"),
            ["mission.c10m08.brief"] = ("Wolff's gunship aircraft circles high over Whiteout Pass, shelling our convoys to Skyhold Airbase. Bring Spectre down with everything that reaches the sky.", "Máy bay pháo của Wolff bay vòng trên cao quanh Đèo Bão Tuyết, nã vào các đoàn xe của ta tới Căn Cứ Tầng Mây. Bắn rơi Spectre bằng mọi thứ với tới được bầu trời."),
            ["mission.c10m08.fragment"] = ("Spectre's crew called themselves \"the Ghosts\" and never landed at the same base twice. They landed once more, in pieces, on the frozen lake.", "Kíp lái Spectre tự gọi mình là \"những Bóng Ma\" và không bao giờ hạ cánh hai lần ở cùng một căn cứ. Chúng đã hạ cánh thêm một lần nữa, thành từng mảnh, trên hồ băng."),
            ["mission.c10m08.fragment.title"] = ("The ghost", "Bóng ma"),
            ["mission.c10m08.name"] = ("Spectre", "Spectre"),
            ["mission.c10m09.brief"] = ("Wolff's own headquarters, at the east end of the base, ringed with missiles. Level it; the air base will fight on, but without its head.", "Sở chỉ huy riêng của Wolff, ở đầu đông căn cứ, vây kín tên lửa. San phẳng nó; căn cứ không quân sẽ còn kháng cự, nhưng đã mất đầu."),
            ["mission.c10m09.fragment"] = ("In Wolff's quarters: a photograph of two young pilots in front of a trainer aircraft, arms round each other. {@dieuhau} took it. He has not said what he did with it.", "Trong phòng của Wolff: một tấm ảnh hai phi công trẻ đứng trước chiếc máy bay huấn luyện, khoác vai nhau. {@dieuhau} đã lấy tấm ảnh. Anh chưa nói đã làm gì với nó."),
            ["mission.c10m09.fragment.title"] = ("The photograph", "Tấm ảnh"),
            ["mission.c10m09.name"] = ("Raven's Nest", "Tổ Wolff"),
            ["mission.c10m10.brief"] = ("The air base itself. Blind its radars, choose your second blow, bring down Wolff's command airship, shoot his last wave out of the sky, and hold the base against the garrison's last push.", "Chính căn cứ không quân. Làm mù radar, chọn đòn thứ hai, bắn rơi Roc của Wolff, quét sạch đợt máy bay cuối cùng của hắn, rồi giữ căn cứ trước đợt phản kích cuối của quân đồn trú."),
            ["mission.c10m10.fragment"] = ("{@dieuhau} shot Wolff down over the runway. He circled until he saw the parachute open, then called in the position for the medics. Wolff was gone by the time they got there.", "{@dieuhau} bắn rơi Wolff ngay trên đường băng. Anh bay vòng cho tới khi thấy dù bung, rồi báo tọa độ cho quân y. Lúc họ tới nơi, Wolff đã biến mất."),
            ["mission.c10m10.fragment.title"] = ("Wingmen", "Bay kèm"),
            ["mission.c10m10.name"] = ("Storm Skyhold Airbase", "Tấn công Căn Cứ Tầng Mây"),
            ["mission.c10s1.brief"] = ("Two trucks are carrying Icarus's spare parts off the base in the fog. Sen wants them stopped before they reach the desert. They are marked.", "Hai xe tải đang chở phụ tùng của Icarus rời căn cứ trong sương. Sen muốn chặn chúng trước khi chúng tới sa mạc. Chúng đã được đánh dấu."),
            ["mission.c10s1.fragment"] = ("The trucks carried a spare main engine casing and two point-defence laser optics. Sen turned one optic over in her hands and said, very quietly, \"They fixed my mistake.\"", "Hai xe tải chở một vỏ động cơ chính dự phòng và hai thấu kính la-de phòng thủ điểm. Sen cầm một thấu kính lật qua lật lại và nói rất khẽ: \"Chúng đã sửa lỗi của tôi.\""),
            ["mission.c10s1.fragment.title"] = ("The Engine", "Động cơ"),
            ["mission.c10s1.name"] = ("Spare Parts", "Phụ tùng"),
            ["mission.c10s2.brief"] = ("Wolff's parachute came down somewhere in the pass. {@linh} wants the radar hill, the village and the lumber camp checked before Hegemon finds him first.", "Dù của Wolff rơi xuống đâu đó trên đèo. {@linh} muốn kiểm tra đồi radar, ngôi làng và trại gỗ trước khi Hegemon tìm ra hắn."),
            ["mission.c10s2.fragment"] = ("The parachute was found at the lumber camp, folded neatly. Next to it, a note in {@dieuhau}'s old flight school code: \"Not yet.\"", "Chiếc dù được tìm thấy ở trại gỗ, gấp gọn gàng. Bên cạnh là một mẩu giấy viết bằng mật mã cũ của trường bay: \"Chưa đâu.\""),
            ["mission.c10s2.fragment.title"] = ("Gone", "Biệt tăm"),
            ["mission.c10s2.name"] = ("The Crow's Trail", "Dấu vết của Quạ"),
            ["mission.c11m01.brief"] = ("Aurel's orbital gate is fed by the rail yard. Take its crossings at night, from the far side.", "Cửa ngõ quỹ đạo của Aurel được tiếp tế qua bãi ray. Chiếm các ngả giao cắt trong đêm, từ phía bên kia."),
            ["mission.c11m01.fragment"] = ("The wagons were full of rocket fuel, stamped \"Project Icarus\".", "Các toa đầy nhiên liệu tên lửa, đóng dấu \"Dự án Icarus\"."),
            ["mission.c11m01.fragment.title"] = ("Freight", "Hàng hóa"),
            ["mission.c11m01.name"] = ("The Gate's Rail Yard", "Bãi ray của cửa ngõ"),
            ["mission.c11m02.brief"] = ("{@linh} wants to see the gate's radar stations before we strike them. Get a vehicle onto each, in the rain.", "{@linh} muốn tận mắt thấy các trạm radar của cửa ngõ trước khi ta đánh. Đưa xe tới từng trạm, trong mưa."),
            ["mission.c11m02.fragment"] = ("The radars were not watching for us. They were watching the sky, for Daedalus.", "Các radar không canh chừng ta. Chúng canh bầu trời, chờ Daedalus."),
            ["mission.c11m02.fragment.title"] = ("Guidance", "Dẫn đường"),
            ["mission.c11m02.name"] = ("Eyes on the Gate", "Mắt nhìn cửa ngõ"),
            ["mission.c11m03.brief"] = ("Destroy the radar dishes that guide Aurel's ships down from orbit.", "Phá các chảo radar dẫn đường cho tàu của Aurel từ quỹ đạo xuống."),
            ["mission.c11m03.fragment"] = ("When the dishes fell, the sky went quiet. Then the first pod came down, off course.", "Khi các chảo radar đổ, bầu trời im bặt. Rồi khoang đổ bộ đầu tiên rơi xuống, lệch hướng."),
            ["mission.c11m03.fragment.title"] = ("Silence", "Im lặng"),
            ["mission.c11m03.name"] = ("Blind the Gate", "Làm mù cửa ngõ"),
            ["mission.c11m04.brief"] = ("Aurel has side pads hidden round the gate. Find them before he fuels them.", "Aurel giấu các bệ phóng phụ quanh cửa ngõ. Tìm ra chúng trước khi hắn nạp nhiên liệu."),
            ["mission.c11m04.fragment"] = ("One pad already had a countdown clock running. {@mai} stopped it with a spanner.", "Một bệ đã có đồng hồ đếm ngược đang chạy. {@mai} dừng nó bằng một chiếc cờ lê."),
            ["mission.c11m04.fragment.title"] = ("Countdown", "Đếm ngược"),
            ["mission.c11m04.name"] = ("The Side Pads", "Bệ phóng phụ"),
            ["mission.c11m05.brief"] = ("Orlov guards the orbital gate with Gungnir, the biggest gun he ever had, on the rails of the Rust Yard. This is his last battle. Silence the gun.", "Orlov canh giữ cửa ngõ quỹ đạo bằng Gungnir, khẩu pháo lớn nhất hắn từng có, trên đường ray của Bãi Sắt Gỉ. Đây là trận cuối của hắn. Bắt khẩu pháo câm họng."),
            ["mission.c11m05.fragment"] = ("Orlov gave himself up by radio, reading out his own position like a fire mission. Then he asked for tea.", "Orlov ra hàng qua bộ đàm, đọc tọa độ của chính mình như một nhiệm vụ bắn. Rồi hắn xin một ấm trà."),
            ["mission.c11m05.fragment.title"] = ("The last coordinate", "Tọa độ cuối cùng"),
            ["mission.c11m05.name"] = ("Gungnir", "Gungnir"),
            ["mission.c11m06.brief"] = ("Aurel wants the ridge above the gate back. Hold it until the guns are in place.", "Aurel muốn lấy lại sườn núi phía trên cửa ngõ. Giữ nó cho tới khi pháo vào vị trí."),
            ["mission.c11m06.fragment"] = ("From the ridge the brigade could see the launch site's lights on the horizon, far to the south.", "Từ sườn núi, lữ đoàn nhìn thấy ánh đèn của bãi phóng trên đường chân trời, tít phía nam."),
            ["mission.c11m06.fragment.title"] = ("High ground", "Điểm cao"),
            ["mission.c11m06.name"] = ("Hold the Ridge", "Giữ sườn núi"),
            ["mission.c11m07.brief"] = ("A Locust drone carrier covers the west pad. Burn the rocket's fuel tanks and bring the carrier down.", "Một tàu mang drone Locust che chắn bệ phóng phía tây. Đốt các bồn nhiên liệu của tên lửa và bắn hạ tàu mang drone."),
            ["mission.c11m07.fragment"] = ("Sen recognised the carrier from its sound. \"Version four,\" she said. \"I never finished version four.\"", "Sen nhận ra tàu mang drone qua tiếng động cơ. \"Phiên bản bốn,\" bà nói. \"Tôi chưa bao giờ làm xong phiên bản bốn.\""),
            ["mission.c11m07.fragment.title"] = ("Sen's work", "Công trình của Sen"),
            ["mission.c11m07.name"] = ("Locust over the Gate", "Locust trên cửa ngõ"),
            ["mission.c11m08.brief"] = ("Aviation fuel for {@dieuhau}'s squadron, by road through the pass at night, to the lumber camp airstrip. Three of five tankers must get there.", "Nhiên liệu máy bay cho phi đội của {@dieuhau}, theo đường bộ qua đèo trong đêm, tới đường băng dã chiến ở trại gỗ. Năm xe bồn phải tới được ba."),
            ["mission.c11m08.fragment"] = ("The lumber camp airstrip is 700 metres of packed snow. {@dieuhau} says it is the best runway on the coast. He also says that about every runway he has landed on.", "Đường băng ở trại gỗ dài 700 mét tuyết nén. {@dieuhau} bảo đó là đường băng tốt nhất dải duyên hải. Anh cũng nói thế về mọi đường băng anh từng hạ cánh."),
            ["mission.c11m08.fragment.title"] = ("Airstrip", "Đường băng dã chiến"),
            ["mission.c11m08.name"] = ("Fuel for the Hawks", "Nhiên liệu cho {@dieuhau}"),
            ["mission.c11m09.brief"] = ("Aurel's gate commander has dug in on the far side of the pass. Level the HQ.", "Viên chỉ huy cửa ngõ của Aurel cố thủ ở phía bên kia đèo. San phẳng sở chỉ huy."),
            ["mission.c11m09.fragment"] = ("The commander's last order from Aurel: \"Hold until the launch. Then you are free to go.\"", "Mệnh lệnh cuối Aurel gửi viên chỉ huy: \"Giữ cho tới khi phóng. Sau đó anh được tự do.\""),
            ["mission.c11m09.fragment.title"] = ("Orders", "Mệnh lệnh"),
            ["mission.c11m09.name"] = ("The Gatekeeper", "Người gác cổng"),
            ["mission.c11m10.brief"] = ("The operation for the gate: blind its radars, choose what to hit, break the defences, then bring down Daedalus as it lands Aurel's troops from orbit.", "Chiến dịch giành cửa ngõ: làm mù radar, chọn mục tiêu, phá tuyến phòng thủ, rồi hạ Daedalus khi nó đổ quân của Aurel từ quỹ đạo xuống."),
            ["mission.c11m10.fragment"] = ("Daedalus came down on the gate it was built to use. Only the launch site was left.", "Daedalus rơi xuống chính cửa ngõ nó được làm ra để dùng. Chỉ còn lại bãi phóng."),
            ["mission.c11m10.fragment.title"] = ("Falling", "Rơi"),
            ["mission.c11m10.name"] = ("The Orbital Gateway", "Cửa ngõ quỹ đạo"),
            ["mission.c11s1.brief"] = ("Aurel's fuel trucks are running to the pads at night. Hunt the marked ones.", "Các xe nhiên liệu của Aurel đang chạy tới bệ phóng trong đêm. Săn những chiếc đã đánh dấu."),
            ["mission.c11s1.fragment"] = ("Every truck stopped was an hour more before Icarus could fly.", "Mỗi xe bị chặn là thêm một giờ trước khi Icarus cất cánh được."),
            ["mission.c11s1.fragment.title"] = ("Fuel", "Nhiên liệu"),
            ["mission.c11s1.name"] = ("Fuel Trucks", "Xe nhiên liệu"),
            ["mission.c11s2.brief"] = ("{@mai}'s engineers need to reach the gate's wreckage before Aurel's men clear it. Take them through in the fog.", "Công binh của {@mai} cần tới đống đổ nát của cửa ngõ trước khi người của Aurel dọn sạch. Đưa họ qua trong sương."),
            ["mission.c11s2.fragment"] = ("From the wreckage {@mai} took one thing: a guidance computer. \"For the museum,\" she said.", "Từ đống đổ nát {@mai} lấy đúng một thứ: một máy tính dẫn đường. \"Cho bảo tàng,\" cô nói."),
            ["mission.c11s2.fragment.title"] = ("Salvage", "Thu hồi"),
            ["mission.c11s2.name"] = ("The Engineers' Convoy", "Đoàn xe công binh"),
            ["mission.c12m01.brief"] = ("The road to the launch site runs through Dunebreak again, from the south this time. Varga's last armour holds the refinery. Take the oasis, the refinery and the oil field.", "Con đường tới bãi phóng lại đi qua Đồi Cát, lần này từ phía nam. Toán thiết giáp cuối cùng của Varga giữ nhà máy lọc dầu. Chiếm ốc đảo, nhà máy và mỏ dầu."),
            ["mission.c12m01.fragment"] = ("The refinery the brigade burned in chapter two was running again. Hegemon had rebuilt it in four months. The workers had rebuilt it, {@mai} corrected. Hegemon had watched.", "Nhà máy lọc dầu lữ đoàn đốt ở chương hai đã chạy lại. Hegemon dựng lại nó trong bốn tháng. {@mai} sửa lại: công nhân dựng lại nó. Hegemon chỉ đứng nhìn."),
            ["mission.c12m01.fragment.title"] = ("The refinery again", "Lại nhà máy lọc dầu"),
            ["mission.c12m01.name"] = ("Back to Dunebreak", "Trở lại Đồi Cát"),
            ["mission.c12m02.brief"] = ("Kessler runs the launch site's rail lines and supply dumps from a base at its northern gate, mined to the teeth. Level his HQ.", "Kessler điều hành đường ray và kho tiếp tế của bãi phóng từ một căn cứ ở cổng bắc, rải mìn dày đặc. San phẳng sở chỉ huy của hắn."),
            ["mission.c12m02.fragment"] = ("Kessler surrendered at 16:00 exactly, on the minute, with his logbook under his arm. His last entry: \"Enemy arrived on schedule.\"", "Kessler đầu hàng đúng 16 giờ, không sai một phút, kẹp cuốn sổ nhật ký dưới nách. Dòng cuối: \"Địch tới đúng lịch.\""),
            ["mission.c12m02.fragment.title"] = ("On time", "Đúng giờ"),
            ["mission.c12m02.name"] = ("Kessler's Last Timetable", "Thời gian biểu cuối cùng của Kessler"),
            ["mission.c12m03.brief"] = ("Varga's final camp, in the dunes where he first built the Behemoth. Every anti-tank gun he has left, and every tank. Level his HQ.", "Trại cuối cùng của Varga, giữa những đồi cát nơi hắn chế tạo chiếc Behemoth đầu tiên. Mọi khẩu pháo chống tăng còn lại, và mọi chiếc xe tăng. San phẳng sở chỉ huy của hắn."),
            ["mission.c12m03.fragment"] = ("Varga did not run this time. He walked out of his HQ, looked at the burning yard, and asked {@mai} whether she still had the rear plates of hull number one. She said yes.", "Lần này Varga không chạy. Hắn bước ra khỏi sở chỉ huy, nhìn xưởng đang cháy, rồi hỏi {@mai} cô còn giữ các tấm giáp sau của thân tàu số một không. Cô bảo còn."),
            ["mission.c12m03.fragment.title"] = ("The machines", "Những cỗ máy"),
            ["mission.c12m03.name"] = ("The Last Behemoth Yard", "Xưởng Behemoth cuối cùng"),
            ["mission.c12m04.brief"] = ("Aurel's own guard holds the northern pads of the launch site. Level their HQ.", "Đội cận vệ riêng của Aurel giữ các bệ phóng phía bắc. San phẳng sở chỉ huy của chúng."),
            ["mission.c12m04.fragment"] = ("Orlov, taken alive, was asked about the word in his notebook. \"Why?\" he said. \"Why I never came closer. Now I have. It is worse.\"", "Orlov bị bắt sống, được hỏi về chữ cuối trong sổ tay. \"Tại sao ư?\" hắn nói. \"Tại sao ta chưa bao giờ tới gần hơn. Giờ thì ta tới rồi. Còn tệ hơn.\""),
            ["mission.c12m04.fragment.title"] = ("The answer", "Câu trả lời"),
            ["mission.c12m04.name"] = ("Aurel's Guard", "Cận vệ của Aurel"),
            ["mission.c12m05.brief"] = ("Aurel took Sen's drone programme when she left, and kept building. A Locust carrier is covering the desert road to the launch site. Bring it down.", "Aurel chiếm lấy chương trình drone của Sen khi bà bỏ đi, và vẫn đóng tiếp. Một tàu Locust đang che chắn con đường sa mạc tới bãi phóng. Bắn hạ nó."),
            ["mission.c12m05.fragment"] = ("Sen looked at the wreck for a long time. \"I built the first one to find people under rubble,\" she said.", "Sen nhìn xác nó rất lâu. \"Chiếc đầu tiên tôi làm ra là để tìm người dưới đống đổ nát,\" bà nói."),
            ["mission.c12m05.fragment.title"] = ("Sen's drones", "Bầy drone của Sen"),
            ["mission.c12m05.name"] = ("Locust", "Locust"),
            ["mission.c12m06.brief"] = ("The last Hegemon airfield covers the launch pad. Wolff is gone; Aurel flies its jets himself, by remote. Level the HQ.", "Sân bay cuối cùng của Hegemon che chắn bệ phóng. Wolff đã không còn; Aurel tự điều khiển máy bay từ xa. San phẳng sở chỉ huy."),
            ["mission.c12m06.fragment"] = ("When his base fell, Wolff called {@dieuhau} on the old flight school frequency. \"Now,\" he said, and landed his helicopter in front of our lines with his hands up.", "Khi căn cứ thất thủ, Wolff gọi {@dieuhau} trên tần số cũ của trường bay. \"Giờ thì được rồi,\" hắn nói, rồi hạ trực thăng trước trận tuyến của ta, hai tay giơ cao."),
            ["mission.c12m06.fragment.title"] = ("Not yet", "Chưa đâu"),
            ["mission.c12m06.name"] = ("The Last Airfield", "Sân bay cuối cùng"),
            ["mission.c12m07.brief"] = ("Icarus's reactor fuel is travelling to the launch site in three guarded trucks. {@linh} has marked them. Stop every one.", "Nhiên liệu lò phản ứng của Icarus đang được chở tới bãi phóng trên ba xe tải có hộ tống. {@linh} đã đánh dấu chúng. Chặn từng chiếc."),
            ["mission.c12m07.fragment"] = ("Sen, on the reactor fuel: \"Without it, the complete Bug can fly for an hour. With it, for a year.\" After this afternoon, it had an hour.", "Sen nói về nhiên liệu lò phản ứng: \"Không có nó, Icarus bay được một giờ. Có nó, bay được một năm.\" Sau buổi chiều hôm đó, nó chỉ còn một giờ."),
            ["mission.c12m07.fragment.title"] = ("Reactor", "Lò phản ứng"),
            ["mission.c12m07.name"] = ("Fuel for the Bug", "Nhiên liệu cho Icarus"),
            ["mission.c12m08.brief"] = ("Four radar stations guide Icarus off its pad. In the sandstorm, destroy all four.", "Bốn trạm radar dẫn đường cho Icarus rời bệ phóng. Giữa cơn bão cát, phá hủy cả bốn."),
            ["mission.c12m08.fragment"] = ("With its radars gone, the complete Bug would have to be launched by hand. Sen knew the one man at the site who could do it: Aurel.", "Mất hết radar, chiếc Icarus sẽ phải phóng bằng tay. Sen biết người duy nhất ở bãi phóng làm được việc đó: Aurel."),
            ["mission.c12m08.fragment.title"] = ("Manual", "Điều khiển tay"),
            ["mission.c12m08.name"] = ("Blind the Icarus Launch Site", "Làm mù bãi phóng"),
            ["mission.c12m09.brief"] = ("While the brigade gathers for the final battle, Aurel throws his guard at the refinery, our supply depot now. Hold it for four minutes.", "Trong khi lữ đoàn tập kết cho trận cuối, Aurel tung vệ binh vào nhà máy lọc dầu, giờ là kho tiếp tế của ta. Giữ nó bốn phút."),
            ["mission.c12m09.fragment"] = ("The night before the last battle, Colonel Khai walked the lines and spoke to every crew. He said the same thing to all of them: \"Tomorrow, we go home.\"", "Đêm trước trận cuối, đại tá {@khai} đi dọc trận tuyến và nói chuyện với từng kíp xe. Ông nói với ai cũng một câu: \"Ngày mai, ta về nhà.\""),
            ["mission.c12m09.fragment.title"] = ("Eve", "Đêm trước"),
            ["mission.c12m09.name"] = ("The Refinery Rearguard", "Hậu vệ nhà máy lọc dầu"),
            ["mission.c12m10.brief"] = ("The last battle. Take the propellant farm, choose your blow, take the assembly building, destroy Aurel's command vehicle, hold the launch pad, and when Icarus lifts off for orbit in its complete form, turn it back and bring it down.", "Trận cuối cùng. Chiếm khu nhiên liệu, chọn đòn đánh, chiếm nhà lắp ráp, tiêu diệt xe chỉ huy của Aurel, giữ bệ phóng, và khi Icarus rời bệ phóng lên quỹ đạo trong hình dạng hoàn chỉnh, buộc nó quay lại và bắn hạ."),
            ["mission.c12m10.fragment"] = ("Icarus never reached orbit: it came down burning a kilometre short, out past the dunes, at 17:42. The brigade's radio log for the next minute holds no orders, only people cheering, and one voice, Colonel Khai's, saying \"Thank you.\"", "Icarus không bao giờ tới được quỹ đạo: nó rơi xuống bốc cháy cách đích chưa đầy một cây số, ngoài rặng đồi cát, lúc 17 giờ 42. Sổ ghi bộ đàm của lữ đoàn trong phút tiếp theo không có mệnh lệnh nào, chỉ có tiếng người reo hò, và một giọng nói, của đại tá {@khai}: \"Cảm ơn.\""),
            ["mission.c12m10.fragment.title"] = ("Clear sky", "Bầu trời trong"),
            ["mission.c12m10.name"] = ("Silver Sky Falls", "Bầu trời bạc sụp đổ"),
            ["mission.c12s1.brief"] = ("Sen needs to see the launch pad, the assembly building and the propellant farm before the last battle. In the sandstorm, from the north.", "Sen cần tận mắt thấy bệ phóng, nhà lắp ráp và khu nhiên liệu trước trận cuối. Giữa cơn bão cát, từ phía bắc."),
            ["mission.c12s1.fragment"] = ("Sen drew the plan of the launch site from memory on the back of a map. {@linh} checked it against the recon photographs. It was right to the metre.", "Sen vẽ sơ đồ bãi phóng theo trí nhớ lên mặt sau một tấm bản đồ. {@linh} đối chiếu với ảnh trinh sát. Nó chính xác tới từng mét."),
            ["mission.c12s1.fragment.title"] = ("Sen's plan", "Kế hoạch của Sen"),
            ["mission.c12s1.name"] = ("The Pad", "Bệ phóng"),
            ["mission.c12s2.brief"] = ("What is left of Hegemon's air force is coming over the dunes for the brigade's supply lines. Sixteen of them, down, in the sandstorm.", "Những gì còn lại của không lực Hegemon đang lao qua các đồi cát nhắm vào đường tiếp tế của lữ đoàn. Mười sáu chiếc, bắn rơi hết, giữa cơn bão cát."),
            ["mission.c12s2.fragment"] = ("After this afternoon, Hegemon had no aircraft left on the coast. {@dieuhau} flew home low over the dunes and did a barrel roll nobody had authorised.", "Sau buổi chiều hôm đó, Hegemon không còn chiếc máy bay nào trên dải duyên hải. {@dieuhau} bay về sát ngọn đồi cát và làm một cú lộn vòng chẳng ai cho phép."),
            ["mission.c12s2.fragment.title"] = ("Empty sky", "Bầu trời trống"),
            ["mission.c12s2.name"] = ("The Last Air Wing", "Phi đội cuối cùng"),
            ["mission.c1m01.brief"] = ("The landing craft are on the sand. Take the beach and the draw above it before Hegemon's garrison wakes up. Your army fights on its own: you choose where it goes, what it brings and when the guns fire.", "Xuồng đổ bộ đã chạm cát. Chiếm bãi biển và con dốc phía trên trước khi đồn Hegemon kịp tỉnh ngủ. Quân ta tự chiến đấu: bạn chọn nơi đánh, mang theo gì và lúc nào pháo khai hỏa."),
            ["mission.c1m01.fragment"] = ("Brigade log, day one: 212 vehicles ashore by 06:40. Losses light. The coastal guns fired late and badly; somebody in Hegemon did not believe we would come.", "Nhật ký lữ đoàn, ngày thứ nhất: 212 xe lên bờ trước 06:40. Thiệt hại nhẹ. Pháo bờ biển bắn muộn và bắn tồi; có kẻ nào đó bên Hegemon đã không tin chúng ta dám tới."),
            ["mission.c1m01.fragment.title"] = ("The first boot on the sand", "Dấu giày đầu tiên trên cát"),
            ["mission.c1m01.name"] = ("Landfall", "Đổ bộ"),
            ["mission.c1m02.brief"] = ("A radar on the bluffs is calling Hegemon's guns onto every landing craft still in the bay. Knock it down, and the boats behind us can come in unseen.", "Trạm radar trên vách đá đang gọi pháo Hegemon bắn vào từng chiếc xuồng còn trong vịnh. Hạ nó xuống, các đợt đổ bộ sau sẽ vào bờ mà không bị phát hiện."),
            ["mission.c1m02.fragment"] = ("Recovered from the radar's log: \"Contacts multiplying. Request confirmation from Director's office. Request confirmation. Request—\" Nobody confirmed.", "Trích từ sổ trực của trạm radar: \"Mục tiêu tăng lên liên tục. Đề nghị văn phòng Giám đốc xác nhận. Đề nghị xác nhận. Đề nghị—\" Không ai xác nhận cả."),
            ["mission.c1m02.fragment.title"] = ("A coastal radar's last report", "Bản tin cuối của trạm radar"),
            ["mission.c1m02.name"] = ("Blind the Coast", "Bịt mắt bờ biển"),
            ["mission.c1m03.brief"] = ("Greenvale's crossroads village and its two farms command every road inland. A handful of scouts hold them. Take all three and the brigade has room to breathe.", "Làng ngã tư ở Lũng Xanh cùng hai trang trại kiểm soát mọi con đường vào nội địa. Chỉ vài xe trinh sát canh giữ. Chiếm cả ba, lữ đoàn sẽ có đất mà thở."),
            ["mission.c1m03.fragment"] = ("The farmers of Greenvale kept planting for two years under the Protectorate. When our tanks came up the road, an old man offered Colonel {@khai} a bag of rice and asked if we were staying.", "Nông dân Lũng Xanh vẫn cày cấy suốt hai năm dưới thời \"Bảo hộ\". Khi xe tăng ta lên đường làng, một cụ già đưa đại tá {@khai} một bao gạo và hỏi quân mình có ở lại không."),
            ["mission.c1m03.fragment.title"] = ("Greenvale's farmers", "Nông dân Lũng Xanh"),
            ["mission.c1m03.name"] = ("The Crossroads", "Ngã tư Lũng Xanh"),
            ["mission.c1m04.brief"] = ("{@mai} wants the crossroads for a base. Take it, set up an outpost there, and keep it standing while her crews fly the towers in. Once it holds, the brigade has its first HQ on the coast.", "{@mai} muốn lấy ngã tư làm căn cứ. Chiếm nó, lập tiền đồn ở đó và giữ vững trong lúc đội của cô thả tháp xuống. Trụ được rồi, lữ đoàn sẽ có sở chỉ huy đầu tiên trên dải duyên hải."),
            ["mission.c1m04.fragment"] = ("Pinned to the first HQ's door: \"Generators (4). Welding rods (all of them). Coffee (more than that). Do not touch the blue crates. — M.\"", "Dán trên cửa sở chỉ huy đầu tiên: \"Máy phát điện (4). Que hàn (tất cả chỗ có). Cà phê (nhiều hơn thế). Không được đụng vào thùng màu xanh. — M.\""),
            ["mission.c1m04.fragment.title"] = ("{@mai}'s shopping list", "Danh sách mua sắm của {@mai}"),
            ["mission.c1m04.name"] = ("First Outpost", "Tiền đồn đầu tiên"),
            ["mission.c1m05.brief"] = ("Brandt has sent his prototype fortress across the Greenvale fields at night to crush our new camp. It is slow and thin-skinned. Stop it.", "Brandt tung pháo đài nguyên mẫu băng qua cánh đồng Lũng Xanh trong đêm để nghiền nát trại mới của ta. Nó chậm và giáp mỏng. Chặn nó lại."),
            ["mission.c1m05.fragment"] = ("Stencilled on the wreck: \"Bastion Mk.0, garrison use only\". Brandt had kept the real one for Ashfield.", "Trên xác nó có dòng chữ sơn: \"Bastion Mk.0, chỉ dùng cho đồn trú\". Brandt giữ chiếc thật cho Đồng Tro."),
            ["mission.c1m05.fragment.title"] = ("The prototype", "Bản nguyên mẫu"),
            ["mission.c1m05.name"] = ("Bastion Mk.0", "Bastion Mk.0"),
            ["mission.c1m06.brief"] = ("Fuel and shells for the forward units, five trucks in the rain. Get at least three to the west farm. The trucks wait for an escort; they will not drive into an ambush alone.", "Nhiên liệu và đạn cho các đơn vị tiền phương, năm xe tải dưới mưa. Đưa ít nhất ba xe tới trang trại phía tây. Xe tải sẽ chờ hộ tống; chúng không tự lao vào ổ phục kích đâu."),
            ["mission.c1m06.fragment"] = ("Driver's note found in a cab: \"Rain for three days. The mud is on our side for once: their raiders bog down before they reach us.\"", "Mẩu giấy của tài xế tìm thấy trong ca-bin: \"Mưa ba ngày rồi. Lần này bùn đứng về phía ta: bọn đột kích sa lầy trước khi tới được chỗ mình.\""),
            ["mission.c1m06.fragment.title"] = ("Rain", "Mưa"),
            ["mission.c1m06.name"] = ("Supply Line", "Đường tiếp tế"),
            ["mission.c1m07.brief"] = ("Hegemon wants the grain silos and the water tower at Greenvale's south end burned, so the valley starves and blames us. Keep at least one standing through the storm.", "Hegemon muốn đốt các kho lúa và tháp nước ở phía nam Lũng Xanh, để thung lũng đói và đổ lỗi cho ta. Giữ ít nhất một công trình đứng vững qua cơn bão."),
            ["mission.c1m07.fragment"] = ("Hegemon field order: \"Deny the valley's food to the enemy.\" {@linh} underlined \"the enemy\" twice. The valley's food feeds the valley.", "Lệnh dã chiến của Hegemon: \"Không để lương thực của thung lũng rơi vào tay địch.\" {@linh} gạch chân chữ \"địch\" hai lần. Lương thực của thung lũng là để nuôi chính thung lũng."),
            ["mission.c1m07.fragment.title"] = ("Scorched earth", "Tiêu thổ"),
            ["mission.c1m07.name"] = ("Harvest Guard", "Giữ mùa gặt"),
            ["mission.c1m08.brief"] = ("Ashfield's town and its two fuel depots lie in front of the fortress. Take all three, and the fortress is cut off from the road.", "Thị trấn Đồng Tro cùng hai kho nhiên liệu nằm ngay trước pháo đài. Chiếm cả ba, pháo đài sẽ bị cắt khỏi đường cái."),
            ["mission.c1m08.fragment"] = ("Before the Night of Steel, Ashfield made bricks. The fortress on the hill was a brickworks; Hegemon kept the kilns and put guns in them.", "Trước Đêm Thép, Đồng Tro làm gạch. Pháo đài trên đồi vốn là lò gạch; Hegemon giữ lại các lò nung rồi đặt pháo vào trong đó."),
            ["mission.c1m08.fragment.title"] = ("Ashfield", "Đồng Tro"),
            ["mission.c1m08.name"] = ("Ashfield Road", "Đường vào Đồng Tro"),
            ["mission.c1m09.brief"] = ("The guns for the fortress need shells. Bring the ammunition trucks round the east road into Ashfield town; three of five must get there.", "Pháo đánh pháo đài cần đạn. Đưa đoàn xe chở đạn vòng đường phía đông vào thị trấn Đồng Tro; năm xe phải tới được ba."),
            ["mission.c1m09.fragment"] = ("Artillery officer's estimate for the fortress: \"Four thousand rounds, or one engineer who knows where the kilns are weakest.\" {@mai} volunteered. Khai ordered the rounds.", "Ước tính của sĩ quan pháo binh cho pháo đài: \"Bốn nghìn quả đạn, hoặc một kỹ sư biết lò nung nào yếu nhất.\" {@mai} xung phong. {@khai} vẫn cho chở đạn."),
            ["mission.c1m09.fragment.title"] = ("Shell count", "Đếm đạn"),
            ["mission.c1m09.name"] = ("Ammunition for the Siege", "Đạn cho trận vây thành"),
            ["mission.c1m10.brief"] = ("The old brickworks on the hill is Hegemon's strongest point on the coast, and the Bastion walks its yard. Burn the fuel depot outside, choose how to soften the walls, bring the Bastion down and level the command HQ.", "Lò gạch cũ trên đồi là điểm mạnh nhất của Hegemon trên dải duyên hải, và Bastion đi tuần trong sân của nó. Đốt kho nhiên liệu bên ngoài, chọn cách làm yếu tường thành, hạ gục Bastion và san phẳng sở chỉ huy."),
            ["mission.c1m10.fragment"] = ("Taken from the Bastion's crew after the fall: all eleven were contract engineers, not soldiers. The oldest had helped {@mai} weld her first Behemoth hull.", "Khai thác từ kíp lái Bastion sau khi pháo đài thất thủ: cả mười một người đều là kỹ sư hợp đồng, không phải lính. Người lớn tuổi nhất từng giúp {@mai} hàn vỏ chiếc Behemoth đầu tiên của cô."),
            ["mission.c1m10.fragment.title"] = ("The Bastion's crew", "Kíp lái Bastion"),
            ["mission.c1m10.name"] = ("The Ashfield Fortress", "Pháo đài Đồng Tro"),
            ["mission.c1s1.brief"] = ("{@linh} has heard engines in the fog round Greenvale's farms. Get a vehicle onto each of the three objectives and look before whatever is out there digs in.", "{@linh} nghe thấy tiếng động cơ trong sương quanh các trang trại Lũng Xanh. Đưa một xe tới từng cứ điểm trong ba cứ điểm để xem trước khi thứ gì ngoài đó kịp cố thủ."),
            ["mission.c1s1.fragment"] = ("\"Engines: three types. Diesel, heavy. Not Hegemon standard. Suggest someone else is selling them tanks.\" The note was filed, and forgotten, until chapter eight.", "\"Tiếng động cơ: ba loại. Máy dầu, hạng nặng. Không phải loại tiêu chuẩn của Hegemon. Đề nghị điều tra ai đang bán xe tăng cho chúng.\" Báo cáo được lưu lại, rồi bị quên, cho tới chương tám."),
            ["mission.c1s1.fragment.title"] = ("{@linh}'s first report", "Báo cáo đầu tiên của {@linh}"),
            ["mission.c1s1.name"] = ("Tracks in the Fog", "Dấu xích trong sương"),
            ["mission.c1s2.brief"] = ("Mortar teams on the bluffs are shelling the beach every night. {@linh} has marked three of them. Hunt them down in the rain.", "Các khẩu đội cối trên vách đá đêm nào cũng nã vào bãi biển. {@linh} đã đánh dấu ba khẩu. Săn lùng chúng dưới mưa."),
            ["mission.c1s2.fragment"] = ("The mortar crews kept a tally on a door: 41 shells on the first night, 12 on the fifth. They were running out, and so was their nerve.", "Kíp cối ghi số đạn lên một cánh cửa: 41 quả đêm đầu, 12 quả đêm thứ năm. Chúng đang cạn đạn, và cạn cả gan."),
            ["mission.c1s2.fragment.title"] = ("The mortar crews", "Kíp cối"),
            ["mission.c1s2.name"] = ("Mortars on the Bluffs", "Cối trên vách đá"),
            ["mission.c2m01.brief"] = ("The brigade has reached Dunebreak's oil field. Hegemon wants it back before we can blow the wells. Hold out at the field for five minutes.", "Lữ đoàn đã tới mỏ dầu Đồi Cát. Hegemon muốn giành lại trước khi ta kịp phá giếng. Trụ vững ở mỏ dầu trong năm phút."),
            ["mission.c2m01.fragment"] = ("Hegemon's machines burn 40,000 barrels a day. Dunebreak and Redrock Canyon pump 38,000. Varga has been complaining about the other two thousand for a year.", "Máy móc của Hegemon đốt 40.000 thùng dầu mỗi ngày. Đồi Cát và Hẻm Đá Đỏ bơm được 38.000. Varga đã cằn nhằn về hai nghìn thùng còn thiếu suốt một năm nay."),
            ["mission.c2m01.fragment.title"] = ("Black gold", "Vàng đen"),
            ["mission.c2m01.name"] = ("Oil and Sand", "Dầu và cát"),
            ["mission.c2m02.brief"] = ("Redrock Canyon's wellhead, oasis and caravan stop feed the pipeline to Dunebreak. Varga's tanks hold the oasis. Take all three.", "Đầu giếng, ốc đảo và trạm dừng đoàn lạc đà ở Hẻm Đá Đỏ cấp dầu cho đường ống tới Đồi Cát. Xe tăng của Varga giữ ốc đảo. Chiếm cả ba."),
            ["mission.c2m02.fragment"] = ("Memo from General Varga to Director Aurel: \"I need the Redrock Canyon wells, two more Behemoths and nobody from accounting in my headquarters.\" Aurel approved one of the three.", "Ghi nhớ của tướng Varga gửi giám đốc Aurel: \"Tôi cần giếng dầu Hẻm Đá Đỏ, thêm hai chiếc Behemoth và không có ai của phòng kế toán trong sở chỉ huy của tôi.\" Aurel duyệt một trong ba đề nghị."),
            ["mission.c2m02.fragment.title"] = ("Varga's memo", "Bản ghi nhớ của Varga"),
            ["mission.c2m02.name"] = ("The Wells of Redrock Canyon", "Giếng dầu Hẻm Đá Đỏ"),
            ["mission.c2m03.brief"] = ("Fuel trucks for the brigade, through the canyon at night, past the oasis to the wellhead. Three of five must get through.", "Xe bồn nhiên liệu cho lữ đoàn, băng qua hẻm núi trong đêm, qua ốc đảo tới đầu giếng. Năm xe phải qua được ba."),
            ["mission.c2m03.fragment"] = ("The canyon road was a caravan route for five hundred years. The drivers still leave a stone at the oasis for luck. Ours did too.", "Con đường qua hẻm núi là tuyến đoàn lạc đà suốt năm trăm năm. Cánh tài xế vẫn đặt một hòn đá ở ốc đảo để cầu may. Tài xế của ta cũng thế."),
            ["mission.c2m03.fragment.title"] = ("The caravan road", "Đường đoàn lạc đà"),
            ["mission.c2m03.name"] = ("Night Caravan", "Đoàn xe đêm"),
            ["mission.c2m04.brief"] = ("Five pipeline stations carry Redrock Canyon's oil into the refinery. Blow every one of them. A raid, no base: in fast, out faster.", "Năm trạm đường ống dẫn dầu từ Hẻm Đá Đỏ vào nhà máy lọc dầu. Cho nổ tung tất cả. Một trận đột kích, không căn cứ: vào nhanh, ra nhanh hơn."),
            ["mission.c2m04.fragment"] = ("Refinery log after the raid: \"Pressure zero on all lines. General Varga informed. General Varga has broken the telephone.\"", "Sổ nhật ký nhà máy sau trận đột kích: \"Áp suất bằng không trên mọi tuyến. Đã báo tướng Varga. Tướng Varga đã đập vỡ điện thoại.\""),
            ["mission.c2m04.fragment.title"] = ("Pressure", "Áp suất"),
            ["mission.c2m04.name"] = ("Cut the Pipeline", "Cắt đường ống"),
            ["mission.c2m05.brief"] = ("Varga has sent Inferno ahead into the sandstorm: a Behemoth rebuilt round flame projectors. Keep out of its reach and burn it first.", "Varga tung Inferno đi trước vào bão cát: một chiếc Behemoth dựng lại quanh các súng phun lửa. Tránh xa tầm với của nó và hạ nó trước."),
            ["mission.c2m05.fragment"] = ("Workshop order for the Inferno: \"Two flame projectors, one thermobaric box, cooling for the crew (optional).\" The cooling was never fitted.", "Phiếu đặt hàng xưởng cho Inferno: \"Hai súng phun lửa lớn, một hộp rốc-két nhiệt áp, hệ làm mát cho kíp lái (tùy chọn).\" Hệ làm mát chưa bao giờ được lắp."),
            ["mission.c2m05.fragment.title"] = ("Cooling (optional)", "Làm mát (tùy chọn)"),
            ["mission.c2m05.name"] = ("Inferno", "Inferno"),
            ["mission.c2m06.brief"] = ("Three of Varga's rocket and missile batteries hide among the mesas, marked in red. Find them in the sandstorm and knock them out.", "Ba dàn pháo phản lực và tên lửa của Varga ẩn giữa các khối đá, đánh dấu màu đỏ. Tìm ra chúng trong bão cát và tiêu diệt."),
            ["mission.c2m06.fragment"] = ("Varga's batteries call themselves the Scorpions and paint a tail on every launcher. After this afternoon, there were no more tails to paint.", "Các khẩu đội của Varga tự gọi mình là Bọ Cạp và vẽ một cái đuôi lên mỗi bệ phóng. Sau buổi chiều hôm đó, chẳng còn cái đuôi nào để vẽ nữa."),
            ["mission.c2m06.fragment.title"] = ("Scorpions", "Bọ cạp"),
            ["mission.c2m06.name"] = ("Scorpion Hunt", "Săn bọ cạp"),
            ["mission.c2m07.brief"] = ("A company of Redrock Canyon militia has declared for the Alliance and is holding the oasis. Varga's tanks have it ringed. Break the ring before their HQ falls. The ring vehicles are marked.", "Một đại đội dân quân Hẻm Đá Đỏ đã tuyên bố đứng về phía Liên minh và đang giữ ốc đảo. Xe tăng của Varga vây kín họ. Phá vòng vây trước khi sở chỉ huy của họ thất thủ. Các xe vây được đánh dấu."),
            ["mission.c2m07.fragment"] = ("The militia captain's first words to Khai: \"We have been waiting two years. You are late.\" His second: \"Thank you.\"", "Câu đầu tiên của đại đội trưởng dân quân với {@khai}: \"Chúng tôi chờ hai năm rồi. Các anh tới muộn.\" Câu thứ hai: \"Cảm ơn.\""),
            ["mission.c2m07.fragment.title"] = ("Militia", "Dân quân"),
            ["mission.c2m07.name"] = ("The Oasis Garrison", "Đồn ốc đảo"),
            ["mission.c2m08.brief"] = ("We have a foot inside the refinery. Varga is throwing his reserve at it. Hold the refinery yard for four minutes.", "Ta đã đặt được một chân vào nhà máy lọc dầu. Varga đang tung lực lượng dự bị vào đó. Giữ sân nhà máy trong bốn phút."),
            ["mission.c2m08.fragment"] = ("The refinery's night shift hid in the cooling towers through the whole battle. In the morning they asked who was paying their wages now.", "Ca đêm của nhà máy trốn trong tháp làm mát suốt trận đánh. Sáng ra họ hỏi giờ ai sẽ trả lương cho họ."),
            ["mission.c2m08.fragment.title"] = ("Night shift", "Ca đêm"),
            ["mission.c2m08.name"] = ("Hold the Refinery", "Giữ nhà máy lọc dầu"),
            ["mission.c2m09.brief"] = ("Varga has dug his headquarters into the far end of the canyon: anti-tank guns, his favourite tanks, and his temper. Level his HQ. He will run; let him know we are coming.", "Varga đã đào sở chỉ huy vào cuối hẻm núi: pháo chống tăng, những chiếc xe tăng hắn ưng ý nhất, và cái tính nóng của hắn. San phẳng sở chỉ huy. Hắn sẽ chạy; để hắn biết ta đang tới."),
            ["mission.c2m09.fragment"] = ("Found in Varga's abandoned tent: a napkin with the first sketch of the Behemoth, dated eleven years ago. On the back, a shopping list. {@linh} framed it.", "Tìm thấy trong lều bỏ lại của Varga: một tờ giấy ăn với bản phác thảo đầu tiên của Behemoth, đề ngày mười một năm trước. Mặt sau là danh sách đồ cần mua. {@linh} đóng khung nó lại."),
            ["mission.c2m09.fragment.title"] = ("The napkin", "Tờ giấy ăn"),
            ["mission.c2m09.name"] = ("Varga's Camp", "Trại của Varga"),
            ["mission.c2m10.brief"] = ("The operation Varga fears: take the oil field and the oasis, choose what to hit next, then blow the refinery's towers and tanks. The Behemoth is parked inside it.", "Chiến dịch mà Varga sợ nhất: chiếm mỏ dầu và ốc đảo, chọn mục tiêu kế tiếp, rồi cho nổ tháp và bồn chứa của nhà máy. Behemoth đang đỗ bên trong nó."),
            ["mission.c2m10.fragment"] = ("Varga's Behemoth burned in its own refinery. {@mai} walked round the wreck twice and said nothing.", "Behemoth của Varga cháy ngay trong nhà máy lọc dầu của hắn. {@mai} đi quanh xác nó hai vòng và không nói gì."),
            ["mission.c2m10.fragment.title"] = ("The napkin's monster", "Con quái vật trên tờ giấy ăn"),
            ["mission.c2m10.name"] = ("Refinery Raid", "Đột kích nhà máy lọc dầu"),
            ["mission.c2s1.brief"] = ("{@linh} needs eyes on the oasis, the refinery and the oil field at night: Varga has been laying mines, and she wants to know where. Look, do not linger.", "{@linh} cần người tới xem ốc đảo, nhà máy và mỏ dầu trong đêm: Varga đang cho rải mìn, và cô muốn biết ở đâu. Nhìn rồi đi, đừng nấn ná."),
            ["mission.c2s1.fragment"] = ("The map {@linh} drew that night had 340 marks on it. The engineers cleared 338. Nobody found the other two, and nobody drives that way.", "Tấm bản đồ {@linh} vẽ đêm đó có 340 dấu. Công binh gỡ được 338. Không ai tìm ra hai quả còn lại, và không ai lái xe đi đường đó."),
            ["mission.c2s1.fragment.title"] = ("The mine map", "Tấm bản đồ mìn"),
            ["mission.c2s1.name"] = ("Minefield Maps", "Bản đồ bãi mìn"),
            ["mission.c2s2.brief"] = ("Varga has called in helicopters to hunt our convoys over Redrock Canyon. {@dieuhau} wants ten of them down before sunset. Bring your anti-air.", "Varga gọi trực thăng tới săn đoàn xe của ta trên Hẻm Đá Đỏ. {@dieuhau} muốn bắn rơi mười chiếc trước khi mặt trời lặn. Mang phòng không theo."),
            ["mission.c2s2.fragment"] = ("Chalked on the hangar wall: \"{@dieuhau} 10, Varga 0.\" Underneath, in smaller letters: \"Anti-air crews 9 of those.\"", "Viết phấn trên tường nhà chứa máy bay: \"{@dieuhau} 10, Varga 0.\" Bên dưới, chữ nhỏ hơn: \"Trong đó 9 chiếc là của pháo thủ phòng không.\""),
            ["mission.c2s2.fragment.title"] = ("{@dieuhau}'s score", "Bảng điểm của {@dieuhau}"),
            ["mission.c2s2.name"] = ("Varga's Gunships", "Trực thăng của Varga"),
            ["mission.c3m01.brief"] = ("The Whiteout Pass is the only road north. Orlov's outposts hold its signal post, the frozen lake and the sawmill. Take all three in the snow.", "Đèo Bão Tuyết là con đường duy nhất lên phía bắc. Tiền đồn của Orlov giữ trạm tín hiệu, hồ băng và xưởng cưa. Chiếm cả ba trong tuyết."),
            ["mission.c3m01.fragment"] = ("Orlov's personnel file: \"Excellent. Cold. Has requested that his batteries be positioned further from the front. Again.\"", "Hồ sơ nhân sự của Orlov: \"Xuất sắc. Lạnh lùng. Lại đề nghị bố trí các khẩu đội của mình xa tiền tuyến hơn nữa.\""),
            ["mission.c3m01.fragment.title"] = ("Orlov", "Orlov"),
            ["mission.c3m01.name"] = ("Into the Pass", "Vào đèo"),
            ["mission.c3m02.brief"] = ("The first station of Orlov's radar line stands on the western heights. While it sees, his guns hit anything we move. Destroy it.", "Trạm đầu tiên trên tuyến radar của Orlov đứng trên cao điểm phía tây. Chừng nào nó còn nhìn thấy, pháo của hắn còn bắn trúng mọi thứ ta di chuyển. Phá hủy nó."),
            ["mission.c3m02.fragment"] = ("Seven stations from the coast to the mountains, each seeing eighty kilometres. With one gone, Orlov's map has a hole the size of a brigade.", "Bảy trạm từ bờ biển tới núi, mỗi trạm nhìn xa tám mươi cây số. Mất một trạm, tấm bản đồ của Orlov thủng một lỗ to bằng cả lữ đoàn."),
            ["mission.c3m02.fragment.title"] = ("The radar line", "Tuyến radar"),
            ["mission.c3m02.name"] = ("Blind the Radar", "Làm mù radar"),
            ["mission.c3m03.brief"] = ("The village in the valley is the only shelter for kilometres. Orlov wants it back, and the fog hides his guns. Hold it for three and a half minutes.", "Ngôi làng dưới thung lũng là chỗ trú duy nhất trong vòng nhiều cây số. Orlov muốn lấy lại, và sương mù che pháo của hắn. Giữ làng trong ba phút rưỡi."),
            ["mission.c3m03.fragment"] = ("The village priest rang the church bell every time Orlov's guns fired, so the brigade knew when to duck. He rang it 212 times.", "Cha xứ trong làng kéo chuông nhà thờ mỗi lần pháo Orlov khai hỏa, để lữ đoàn biết mà nằm xuống. Ông kéo 212 lần."),
            ["mission.c3m03.fragment.title"] = ("The church bell", "Tiếng chuông nhà thờ"),
            ["mission.c3m03.name"] = ("Village in the Fog", "Ngôi làng trong sương"),
            ["mission.c3m04.brief"] = ("{@mai} wants a forward base on the frozen lake, in the middle of the pass. Take the lake, set up an outpost and keep it three minutes. At night. On ice.", "{@mai} muốn dựng căn cứ tiền phương trên hồ băng, giữa đèo. Chiếm hồ, lập tiền đồn và giữ nó ba phút. Ban đêm. Trên băng."),
            ["mission.c3m04.fragment"] = ("{@mai} measured the ice herself: ninety centimetres. \"Enough for a tower, not for a Behemoth,\" she wrote. \"Good. That is the point.\"", "{@mai} tự tay đo băng: chín mươi phân. \"Đủ cho một cái tháp, không đủ cho một chiếc Behemoth,\" cô ghi. \"Tốt. Chính là thế.\""),
            ["mission.c3m04.fragment.title"] = ("Ice thickness", "Độ dày của băng"),
            ["mission.c3m04.name"] = ("Base on the Ice", "Căn cứ trên băng"),
            ["mission.c3m05.brief"] = ("Orlov's Harpy has come down from the clouds over the pass: a gunship the size of a ship, with rockets, flares and an escort. This is what the anti-air was for. Bring it down.", "Harpy của Orlov đã sà xuống khỏi mây trên đèo: một pháo hạm bay to như con tàu, có rốc-két, pháo sáng mồi bẫy và đội hộ tống. Phòng không là để dành cho lúc này. Bắn rơi nó."),
            ["mission.c3m05.fragment"] = ("Harpy's crew manual, page one: \"The aircraft cannot be shot down by ground fire.\" Page two was missing. So, now, is Harpy.", "Sổ tay kíp lái Harpy, trang một: \"Máy bay không thể bị hỏa lực mặt đất bắn hạ.\" Trang hai bị mất. Giờ thì Harpy cũng mất."),
            ["mission.c3m05.fragment.title"] = ("Harpy", "Harpy"),
            ["mission.c3m05.name"] = ("Harpy", "Harpy"),
            ["mission.c3m06.brief"] = ("{@linh} has fixed three of Orlov's batteries by their muzzle flashes, marked in red. They move after every salvo. Hunt them in the dark.", "{@linh} đã định vị được ba khẩu đội của Orlov qua ánh chớp đầu nòng, đánh dấu màu đỏ. Chúng di chuyển sau mỗi loạt bắn. Săn chúng trong bóng tối."),
            ["mission.c3m06.fragment"] = ("{@linh}'s method, in her own words: \"Count the seconds from the flash to the bang. Multiply. Draw a circle. Send {@dieuhau} into the circle.\"", "Phương pháp của {@linh}, theo lời cô: \"Đếm số giây từ lúc chớp sáng tới tiếng nổ. Nhân lên. Vẽ một vòng tròn. Cho {@dieuhau} bay vào vòng tròn đó.\""),
            ["mission.c3m06.fragment.title"] = ("Muzzle flash", "Chớp đầu nòng"),
            ["mission.c3m06.name"] = ("Orlov's Guns", "Pháo của Orlov"),
            ["mission.c3m07.brief"] = ("The families of the pass have taken shelter in the cabins and the barn on the south side. Orlov is shelling everything that still has a roof. Keep at least one standing for seven minutes.", "Các gia đình trên đèo đã trú trong những căn nhà gỗ và nhà kho phía nam. Orlov đang nã pháo vào mọi thứ còn mái che. Giữ ít nhất một căn đứng vững trong bảy phút."),
            ["mission.c3m07.fragment"] = ("Fifty-one people spent the night in the barn. In the morning a girl asked {@dieuhau} if the loud planes were his. He said yes, and that they were on her side.", "Năm mươi mốt người qua đêm trong nhà kho. Sáng ra, một cô bé hỏi {@dieuhau} có phải mấy chiếc máy bay ầm ĩ kia là của chú không. Anh bảo phải, và chúng đứng về phía cháu."),
            ["mission.c3m07.fragment.title"] = ("Fifty-one", "Năm mươi mốt người"),
            ["mission.c3m07.name"] = ("Cabins in the Snow", "Những căn nhà gỗ trong tuyết"),
            ["mission.c3m08.brief"] = ("Medicine and doctors for the signal post, where the wounded from the pass are waiting. Five trucks at night; three must get there.", "Thuốc men và bác sĩ cho trạm tín hiệu, nơi thương binh trên đèo đang chờ. Năm xe trong đêm; phải tới được ba xe."),
            ["mission.c3m08.fragment"] = ("The convoy's doctor had worked for Hegemon's medical corps until the Night of Steel. Nobody asked her why she changed sides. She did not wait to be asked.", "Bác sĩ trong đoàn xe từng làm cho quân y Hegemon cho tới Đêm Thép. Không ai hỏi vì sao cô đổi phe. Cô cũng chẳng đợi ai hỏi."),
            ["mission.c3m08.fragment.title"] = ("The doctor", "Bác sĩ"),
            ["mission.c3m08.name"] = ("Medical Convoy", "Đoàn xe cứu thương"),
            ["mission.c3m09.brief"] = ("Orlov's headquarters sits behind a wall of artillery emplacements, where he can see the whole valley. Break through and level it. He will not wait for you.", "Sở chỉ huy của Orlov nằm sau một bức tường ụ pháo, nơi hắn nhìn thấy cả thung lũng. Chọc thủng và san phẳng nó. Hắn sẽ không chờ ta đâu."),
            ["mission.c3m09.fragment"] = ("Every page of Orlov's notebook is numbers: ranges, times, weights of shell. On the last page, one word, underlined: \"Why?\" Nobody knows what he was asking.", "Trang nào trong sổ tay của Orlov cũng toàn con số: tầm bắn, thời gian, trọng lượng đạn. Ở trang cuối có một chữ, gạch chân: \"Tại sao?\" Không ai biết hắn đã tự hỏi điều gì."),
            ["mission.c3m09.fragment.title"] = ("Orlov's notebook", "Sổ tay của Orlov"),
            ["mission.c3m09.name"] = ("Orlov's Gun Line", "Trận địa pháo của Orlov"),
            ["mission.c3m10.brief"] = ("The last station of the radar line, the fortress behind it, and Jötunn guarding its gate. Blind the hill radar, choose your second blow, destroy Jötunn, and hold its gate against Orlov's counterattack.", "Trạm cuối của tuyến radar, pháo đài phía sau nó, và Jötunn canh cổng. Làm mù radar trên đồi, chọn đòn thứ hai, tiêu diệt Jötunn, rồi giữ cổng trước đợt phản kích của Orlov."),
            ["mission.c3m10.fragment"] = ("The day the Frostpeak line fell, the thaw began. The engineers swear the two are not connected. The villagers do not believe the engineers.", "Ngày tuyến Đỉnh Sương Giá sụp đổ, băng bắt đầu tan. Công binh thề rằng hai chuyện chẳng liên quan gì nhau. Dân làng không tin công binh."),
            ["mission.c3m10.fragment.title"] = ("Spring", "Mùa xuân"),
            ["mission.c3m10.name"] = ("The Frostpeak Line", "Tuyến Đỉnh Sương Giá"),
            ["mission.c3s1.brief"] = ("Before the big push, {@linh} wants every gun position round Frostpeak on her map. Put a vehicle on the radar hill, the village and the lumber camp, in the fog.", "Trước trận đánh lớn, {@linh} muốn mọi trận địa pháo quanh Đỉnh Sương Giá có mặt trên bản đồ của cô. Đưa xe tới đồi radar, ngôi làng và trại gỗ, trong sương mù."),
            ["mission.c3s1.fragment"] = ("{@linh} keeps her maps on paper. \"Hegemon reads our radio,\" she says. \"Hegemon does not read my handwriting. Nobody does.\"", "{@linh} giữ bản đồ trên giấy. \"Hegemon đọc được sóng vô tuyến của ta,\" cô nói. \"Hegemon không đọc được chữ tôi. Chẳng ai đọc được.\""),
            ["mission.c3s1.fragment.title"] = ("Paper map", "Bản đồ giấy"),
            ["mission.c3s1.name"] = ("Where the Guns Are", "Pháo nằm ở đâu"),
            ["mission.c3s2.brief"] = ("{@linh} has found Orlov's winter vanguard in the Frostpeak snow: Fenrir, a heavy hunter that marks targets for his guns. Hunt it down.", "{@linh} phát hiện xe tiên phong mùa đông của Orlov trong tuyết Đỉnh Sương Giá: Fenrir, một thợ săn hạng nặng đánh dấu mục tiêu cho pháo của hắn. Săn nó."),
            ["mission.c3s2.fragment"] = ("With Fenrir gone, Orlov's batteries fired at the old coordinates for an hour. There was nobody there.", "Mất Fenrir, các khẩu đội của Orlov bắn vào tọa độ cũ suốt một giờ. Ở đó chẳng còn ai."),
            ["mission.c3s2.fragment.title"] = ("Blind guns", "Pháo mù"),
            ["mission.c3s2.name"] = ("Fenrir", "Fenrir"),
            ["mission.c4m01.brief"] = ("Kessler's marshalling yard feeds the port. Take the foundry, the yard and the scrapyard, and his trains have nowhere to be put together.", "Bãi dồn toa của Kessler nuôi cả bến cảng. Chiếm xưởng đúc, bãi dồn toa và bãi phế liệu, các đoàn tàu của hắn sẽ không còn chỗ lắp ráp."),
            ["mission.c4m01.fragment"] = ("A Rust Yard timetable, pinned in the signal box: 212 trains a week, each to the minute. Handwritten at the bottom: \"Delays will be explained to the Admiral in person.\"", "Một bảng giờ tàu ở Bãi Sắt Gỉ, ghim trong trạm tín hiệu: 212 chuyến mỗi tuần, chính xác tới từng phút. Viết tay ở dưới: \"Chuyến nào trễ sẽ phải giải trình trực tiếp với Đô đốc.\""),
            ["mission.c4m01.fragment.title"] = ("The timetable", "Thời gian biểu"),
            ["mission.c4m01.name"] = ("The Rust Yard", "Bãi Sắt Gỉ"),
            ["mission.c4m02.brief"] = ("Kessler holds the docks, the factories and the rail yard of Ironport. Take all three in the rain, and set up an outpost in the factories.", "Kessler giữ bến tàu, khu nhà máy và bãi đường sắt của Cảng Thép. Chiếm cả ba dưới mưa, và lập tiền đồn trong khu nhà máy."),
            ["mission.c4m02.fragment"] = ("Every Behemoth hull left Ironport by sea. {@mai} recognised the factory's crane from the other side: she used to sign for the plates it lifted.", "Mọi thân tàu Behemoth đều rời Cảng Thép bằng đường biển. {@mai} nhận ra cây cần cẩu của nhà máy, từ phía bên kia: cô từng ký nhận những tấm thép nó nâng."),
            ["mission.c4m02.fragment.title"] = ("Made in Ironport", "Sản xuất tại Cảng Thép"),
            ["mission.c4m02.name"] = ("Storm the Factories", "Đánh chiếm khu nhà máy"),
            ["mission.c4m03.brief"] = ("Engineers and explosives for the docks, five trucks through the fogbound port. Three must reach the quay.", "Công binh và thuốc nổ cho bến tàu, năm xe tải xuyên qua bến cảng chìm trong sương. Phải tới được cầu tàu ba xe."),
            ["mission.c4m03.fragment"] = ("The port's fog horn sounds every ninety seconds. The drivers timed their dashes between the blasts, so the enemy could not hear the engines.", "Còi sương của bến cảng rú lên mỗi chín mươi giây. Cánh tài xế canh giờ lao xe vào giữa hai tiếng còi để địch không nghe thấy tiếng máy."),
            ["mission.c4m03.fragment.title"] = ("Fog horn", "Còi sương"),
            ["mission.c4m03.name"] = ("Dockside Convoy", "Đoàn xe bến cảng"),
            ["mission.c4m04.brief"] = ("{@linh} needs to know where Juggernaut is being put together. Get a vehicle onto each of the three objectives and look, before Kessler digs in.", "{@linh} cần biết Juggernaut đang được lắp ráp ở đâu. Đưa xe tới từng cứ điểm trong ba cứ điểm để quan sát, trước khi Kessler kịp cố thủ."),
            ["mission.c4m04.fragment"] = ("{@linh} copied the numbers off every wagon in the yard. Eleven of them came up twice in Kessler's own lists: Juggernaut, hiding in plain sight.", "{@linh} chép lại số hiệu của mọi toa tàu trong bãi. Mười một số xuất hiện hai lần trong chính danh sách của Kessler: Juggernaut, trốn ngay trước mắt."),
            ["mission.c4m04.fragment.title"] = ("Wagon numbers", "Số hiệu toa"),
            ["mission.c4m04.name"] = ("Eyes on the Yard", "Mắt nhìn Bãi Sắt"),
            ["mission.c4m05.brief"] = ("Kessler's armoured train is running for the docks with a cargo {@linh} does not like the sound of. Destroy it before it arrives.", "Đoàn tàu bọc thép của Kessler đang lao về bến tàu với một chuyến hàng mà {@linh} nghe tên đã thấy không ổn. Phá hủy nó trước khi nó tới nơi."),
            ["mission.c4m05.fragment"] = ("The train's manifest, recovered from the wreck: forty tons of \"laboratory equipment\" addressed to \"Project Icarus, Skyhold Airbase\". The first time anyone read those two letters.", "Bản kê hàng của đoàn tàu, tìm thấy trong xác tàu: bốn mươi tấn \"thiết bị phòng thí nghiệm\" gửi tới \"Dự án Icarus, Căn Cứ Tầng Mây\". Lần đầu tiên có người đọc thấy hai chữ cái đó."),
            ["mission.c4m05.fragment.title"] = ("The cargo", "Chuyến hàng"),
            ["mission.c4m05.name"] = ("The Steel Train", "Juggernaut"),
            ["mission.c4m06.brief"] = ("Kessler's command destroyer, Scylla, is escorting his ships out of Lighthouse Bay in the fog. Sink it before the convoy gets away.", "Tàu khu trục chỉ huy của Kessler, Scylla, đang hộ tống tàu của hắn rời Vịnh Hải Đăng trong sương. Đánh chìm nó trước khi đoàn tàu thoát được."),
            ["mission.c4m06.fragment"] = ("The ships Scylla was guarding carried Behemoth parts from Varga's works. Kessler ships everything, for everyone.", "Những con tàu Scylla hộ tống chở linh kiện Behemoth từ xưởng của Varga. Kessler chở mọi thứ, cho mọi người."),
            ["mission.c4m06.fragment.title"] = ("Cargo", "Hàng hóa"),
            ["mission.c4m06.name"] = ("Scylla", "Scylla"),
            ["mission.c4m07.brief"] = ("We hold the factory district now, and the workers are back at their benches. Kessler is coming from the south to burn it rather than lose it. Keep at least one building standing for seven minutes.", "Giờ ta giữ khu nhà máy, và công nhân đã quay lại bàn máy. Kessler đang kéo tới từ phía nam để đốt trụi nó chứ không chịu mất. Giữ ít nhất một tòa nhà đứng vững trong bảy phút."),
            ["mission.c4m07.fragment"] = ("The factory's foreman stayed at his post through the whole attack. Asked why, he said: \"Somebody has to switch the furnaces off properly. Hegemon never did.\"", "Ông đốc công bám trụ ở vị trí suốt trận tấn công. Hỏi vì sao, ông bảo: \"Phải có người tắt lò cho đúng cách. Bọn Hegemon chẳng bao giờ làm.\""),
            ["mission.c4m07.fragment.title"] = ("The foreman", "Ông đốc công"),
            ["mission.c4m07.name"] = ("Kessler Strikes Back", "Kessler phản đòn"),
            ["mission.c4m08.brief"] = ("Every night Kessler's minelayers seed the roads to the port. {@linh} has marked three of them. Hunt them before they finish their round.", "Đêm nào các xe rải mìn của Kessler cũng gieo mìn khắp những con đường vào cảng. {@linh} đã đánh dấu ba chiếc. Săn chúng trước khi chúng xong một vòng."),
            ["mission.c4m08.fragment"] = ("Kessler's mines are numbered, dated and logged. His engineers could tell us the exact place of every one. They did, for a hot meal each.", "Mìn của Kessler được đánh số, ghi ngày và vào sổ. Công binh của hắn có thể chỉ cho ta chính xác vị trí từng quả. Và họ đã chỉ, đổi lấy mỗi người một bữa ăn nóng."),
            ["mission.c4m08.fragment.title"] = ("Kessler's mines", "Mìn của Kessler"),
            ["mission.c4m08.name"] = ("Minelayers", "Tàu rải mìn trên cạn"),
            ["mission.c4m09.brief"] = ("Kessler's headquarters stands behind the container stacks at the north end of the port, a little of every defence and mines everywhere. Break it in the storm and level his HQ.", "Sở chỉ huy của Kessler nằm sau những dãy công-te-nơ ở đầu bắc bến cảng, phòng thủ thứ gì cũng có một ít và mìn ở khắp nơi. Phá nó giữa cơn bão và san phẳng sở chỉ huy."),
            ["mission.c4m09.fragment"] = ("Kessler's logbook, last entry before the storm: \"Weather: unacceptable. Enemy: unacceptable. Morale: acceptable.\" He took the logbook with him when he ran.", "Sổ nhật ký của Kessler, dòng cuối trước cơn bão: \"Thời tiết: không chấp nhận được. Quân địch: không chấp nhận được. Tinh thần: chấp nhận được.\" Hắn mang theo cuốn sổ khi tháo chạy."),
            ["mission.c4m09.fragment.title"] = ("The logbook", "Cuốn sổ nhật ký"),
            ["mission.c4m09.name"] = ("The Admiral's Quarters", "Tổng hành dinh của Đô đốc"),
            ["mission.c4m10.brief"] = ("The whole port, in one day: the rail yard, then the factories and the docks. On the quay, {@linh}'s intercepts say, Tempest is waiting with its railgun. Take everything, destroy Tempest, and hold the quay against Kessler's last counterattack.", "Cả bến cảng, trong một ngày: bãi đường sắt, rồi khu nhà máy và bến tàu. Trên cầu tàu, theo các bản chặn thu của {@linh}, Tempest đang chờ với khẩu súng điện từ. Chiếm tất cả, tiêu diệt Tempest, rồi giữ cầu tàu trước đợt phản công cuối cùng của Kessler."),
            ["mission.c4m10.fragment"] = ("Kessler shipped Tempest to the docks so it could sail if the port fell. It never sailed. Its railgun now points at the sea, in the brigade's museum yard.", "Kessler đưa Tempest ra bến để nó kịp xuống tàu nếu cảng thất thủ. Nó chưa bao giờ xuống tàu. Giờ khẩu súng điện từ của nó chĩa ra biển, trong sân bảo tàng của lữ đoàn."),
            ["mission.c4m10.fragment.title"] = ("Tempest", "Tempest"),
            ["mission.c4m10.name"] = ("Take the Port", "Chiếm bến cảng"),
            ["mission.c4m11.brief"] = ("Ironport is ours, but Kessler got out by sea. He is aboard Leviathan, his battleship, off Lighthouse Bay, and he means to shell the coast until we give the port back. Take the lighthouse to see his fleet, man the old coastal batteries, and sink it before it runs for open sea.", "Cảng Thép đã về tay ta, nhưng Kessler thoát được bằng đường biển. Hắn đang ở trên Leviathan, chiến hạm của hắn, ngoài khơi Vịnh Hải Đăng, và định nã pháo vào bờ cho tới khi ta trả lại bến cảng. Chiếm ngọn hải đăng để thấy hạm đội của hắn, dùng các trận địa pháo bờ biển cũ, và đánh chìm nó trước khi nó chạy ra khơi."),
            ["mission.c4m11.fragment"] = ("Divers brought up Leviathan's bridge clock a month later. It had stopped at 16:42, the minute the second magazine went. Kessler's last order in the log, in his own hand: \"Record the time.\"", "Một tháng sau, thợ lặn vớt được chiếc đồng hồ trên cầu chỉ huy của Leviathan. Nó dừng ở 16 giờ 42, đúng phút kho đạn thứ hai phát nổ. Mệnh lệnh cuối cùng trong sổ, chữ của chính Kessler: \"Ghi lại thời gian.\""),
            ["mission.c4m11.fragment.title"] = ("The timetable", "Thời gian biểu"),
            ["mission.c4m11.name"] = ("Leviathan", "Leviathan"),
            ["mission.c4s1.brief"] = ("{@linh} has found where Kessler keeps the Alliance prisoners: a siding at the scrapyard. Four trucks to bring them out; three must make it.", "{@linh} đã tìm ra nơi Kessler giam giữ tù binh Liên minh: một đường tránh ở bãi phế liệu. Bốn xe tải để đưa họ ra; phải thoát được ba xe."),
            ["mission.c4s1.fragment"] = ("Eighty-four prisoners came out of the siding. {@linh} read every name over the radio that night, so their families would hear.", "Tám mươi tư tù binh được đưa ra khỏi đường tránh. Đêm đó {@linh} đọc từng cái tên trên sóng phát thanh, để gia đình họ được nghe."),
            ["mission.c4s1.fragment.title"] = ("Names", "Những cái tên"),
            ["mission.c4s1.name"] = ("The Prisoners' Train", "Chuyến tàu tù binh"),
            ["mission.c4s2.brief"] = ("Two of Kessler's harbour masters are still running the smuggling routes from command cars. {@linh} has marked them. Bring them in, the hard way.", "Hai viên cảng vụ của Kessler vẫn đang điều hành các tuyến buôn lậu từ xe chỉ huy. {@linh} đã đánh dấu họ. Bắt họ về, bằng cách khó."),
            ["mission.c4s2.fragment"] = ("The harbour masters' ledger listed every buyer of Hegemon weapons on the coast. One name had been crossed out and written again in ink: {@lyhan}.", "Sổ sách của các viên cảng vụ ghi tên mọi kẻ mua vũ khí Hegemon trên dải duyên hải. Một cái tên bị gạch đi rồi viết lại bằng mực: {@lyhan}."),
            ["mission.c4s2.fragment.title"] = ("The smugglers' ledger", "Sổ sách buôn lậu"),
            ["mission.c4s2.name"] = ("Harbour Masters", "Những viên cảng vụ"),
            ["mission.c5m01.brief"] = ("Sen's outer guard holds the temple ford and the east village of Jungle Pass. Take the whole pass in the rain.", "Lực lượng canh gác vòng ngoài của Sen giữ bến đền cổ và làng phía đông Đèo Rừng Rậm. Chiếm trọn con đèo dưới mưa."),
            ["mission.c5m01.fragment"] = ("The temple in the pass is eight hundred years old. Sen's engineers used its courtyard to test drones, and left the carvings alone. {@linh} noticed that.", "Ngôi đền trên đèo đã tám trăm năm tuổi. Kỹ sư của Sen dùng sân đền để thử drone, nhưng không đụng tới những bức chạm khắc. {@linh} để ý điều đó."),
            ["mission.c5m01.fragment.title"] = ("The temple", "Ngôi đền"),
            ["mission.c5m01.name"] = ("Temple of Ash", "Đền Tro"),
            ["mission.c5m02.brief"] = ("Three of Sen's launch trucks send drone swarms over the lava fields every night. {@linh} has marked them. Hunt them in the glow of the lava.", "Ba xe phóng của Sen đêm nào cũng tung bầy drone qua đồng dung nham. {@linh} đã đánh dấu chúng. Săn chúng dưới ánh sáng của dung nham."),
            ["mission.c5m02.fragment"] = ("Every one of Sen's drones carries a serial number and a single word stamped under the wing: \"Sorry.\" Nobody in Hegemon ever turned one over.", "Mỗi chiếc drone của Sen đều mang một số hiệu và một chữ duy nhất đóng dưới cánh: \"Xin lỗi.\" Chưa ai bên Hegemon từng lật một chiếc lên mà xem."),
            ["mission.c5m02.fragment.title"] = ("Drone serials", "Số hiệu drone"),
            ["mission.c5m02.name"] = ("Swarm Trucks", "Xe bầy đàn"),
            ["mission.c5m03.brief"] = ("Bridging gear for the engineers, up the river road through the jungle fog to the west village. Three of five trucks must arrive; Sen's drones will be looking for them.", "Thiết bị bắc cầu cho công binh, ngược đường ven sông qua sương rừng tới làng phía tây. Năm xe phải tới được ba; drone của Sen sẽ săn lùng chúng."),
            ["mission.c5m03.fragment"] = ("The engineers built four bridges over the river in two days. The villagers named the last one after the brigade. The brigade named it after the villagers.", "Công binh bắc bốn cây cầu qua sông trong hai ngày. Dân làng đặt tên cây cầu cuối theo tên lữ đoàn. Lữ đoàn lại đặt tên nó theo tên dân làng."),
            ["mission.c5m03.fragment.title"] = ("The bridges", "Những cây cầu"),
            ["mission.c5m03.name"] = ("River Road", "Đường ven sông"),
            ["mission.c5m04.brief"] = ("{@mai} wants the geothermal plant in the middle of Ember Ridge: free power for a forward base. Take it, set up an outpost, keep it three minutes.", "{@mai} muốn lấy nhà máy địa nhiệt giữa Sườn Dung Nham: điện miễn phí cho một căn cứ tiền phương. Chiếm nó, lập tiền đồn, giữ ba phút."),
            ["mission.c5m04.fragment"] = ("{@mai}'s note on the plant: \"Output 40 MW. Enough for the base, the airfield and the coffee machine. In that order. No, reverse that order.\"", "Ghi chú của {@mai} về nhà máy: \"Công suất 40 MW. Đủ cho căn cứ, sân bay và máy pha cà phê. Theo thứ tự đó. À không, đảo ngược thứ tự đó.\""),
            ["mission.c5m04.fragment.title"] = ("Free power", "Điện miễn phí"),
            ["mission.c5m04.name"] = ("The Geothermal Plant", "Nhà máy địa nhiệt"),
            ["mission.c5m05.brief"] = ("Sen's drone fortress is crawling down the pass in the storm, swarms rising from its racks. It has no main gun and fears no aircraft. Break it with tanks and artillery.", "Pháo đài drone của Sen đang bò xuống con đèo trong cơn bão, bầy drone bốc lên từ các giàn phóng. Nó không có pháo chính và chẳng sợ máy bay nào. Đập vỡ nó bằng xe tăng và pháo binh."),
            ["mission.c5m05.fragment"] = ("The Hive's original design document, found in its wreck: \"Autonomous swarm for search and rescue in disaster zones.\" The word \"rescue\" had been crossed out, by someone else.", "Tài liệu thiết kế gốc của Hive, tìm thấy trong xác nó: \"Bầy drone tự hành phục vụ tìm kiếm cứu nạn ở vùng thảm họa.\" Chữ \"cứu nạn\" đã bị gạch đi, bởi một người khác."),
            ["mission.c5m05.fragment.title"] = ("Rescue system", "Hệ thống cứu hộ"),
            ["mission.c5m05.name"] = ("The Hive", "Hive"),
            ["mission.c5m06.brief"] = ("The drone works are inside a fortress at the north end of the ridge. Break through the walls at night and level the command HQ.", "Xưởng drone nằm trong một pháo đài ở đầu bắc sườn núi. Phá tường trong đêm và san phẳng sở chỉ huy."),
            ["mission.c5m06.fragment"] = ("Inside the drone works: 4,000 drones in crates, and one office with a camp bed. Sen had not been home in eight months.", "Bên trong xưởng drone: 4.000 chiếc drone còn trong thùng, và một văn phòng kê một chiếc giường gấp. Sen đã tám tháng không về nhà."),
            ["mission.c5m06.fragment.title"] = ("The works", "Xưởng máy"),
            ["mission.c5m06.name"] = ("Molten Gate", "Cổng Dung Nham"),
            ["mission.c5m07.brief"] = ("Sen's strike drones own the sky over the pass. Bring fourteen of them down, and the jungle belongs to the brigade again.", "Drone tấn công của Sen làm chủ bầu trời trên đèo. Bắn rơi mười bốn chiếc, và rừng lại thuộc về lữ đoàn."),
            ["mission.c5m07.fragment"] = ("After the drones were gone, the birds came back to the pass within a week. {@dieuhau} claims they were waiting for him.", "Lũ drone biến mất được một tuần thì chim chóc quay về đèo. {@dieuhau} khẳng định chúng đợi anh."),
            ["mission.c5m07.fragment.title"] = ("Birds", "Chim chóc"),
            ["mission.c5m07.name"] = ("Clear the Canopy", "Quét sạch tán rừng"),
            ["mission.c5m08.brief"] = ("The geothermal plant's steam tanks power the whole brigade now. Sen's drones are coming for them from the south. Keep at least one standing for seven minutes.", "Các bồn hơi của nhà máy địa nhiệt giờ cấp điện cho cả lữ đoàn. Drone của Sen đang lao tới từ phía nam. Giữ ít nhất một bồn đứng vững trong bảy phút."),
            ["mission.c5m08.fragment"] = ("Intercepted, from Sen to Aurel: \"The plant is a civilian power source. I will not strike it.\" Aurel's reply: \"Then someone else will.\" Someone else did.", "Chặn thu được, Sen gửi Aurel: \"Nhà máy là nguồn điện dân sự. Tôi sẽ không đánh nó.\" Aurel trả lời: \"Vậy sẽ có người khác đánh.\" Và đã có người khác đánh."),
            ["mission.c5m08.fragment.title"] = ("A message", "Một bức điện"),
            ["mission.c5m08.name"] = ("Keep the Lights On", "Giữ đèn sáng"),
            ["mission.c5m09.brief"] = ("Sen's field headquarters is ringed with drone hangars and jammers. Break it at night and level her HQ. {@linh} thinks she may not fight to the end.", "Sở chỉ huy dã chiến của Sen được bao quanh bởi những nhà chứa drone và xe gây nhiễu. Phá nó trong đêm và san phẳng sở chỉ huy. {@linh} nghĩ bà ấy có thể sẽ không đánh tới cùng."),
            ["mission.c5m09.fragment"] = ("Sen's last message before her HQ fell, on an open channel: \"Colonel, if we meet, I would like to talk. Not about drones.\" Khai did not answer. He kept the recording.", "Bức điện cuối của Sen trước khi sở chỉ huy thất thủ, trên kênh mở: \"Đại tá, nếu ta gặp nhau, tôi muốn nói chuyện. Không phải về drone.\" {@khai} không trả lời. Ông giữ lại bản ghi âm."),
            ["mission.c5m09.fragment.title"] = ("An open channel", "Một kênh mở"),
            ["mission.c5m09.name"] = ("The Hangars of the Pass", "Những nhà chứa trên đèo"),
            ["mission.c5m10.brief"] = ("The Hive's mothership is over Ember Ridge, feeding swarms to every Hegemon unit in the jungle. Take the causeways, choose your next blow, survive the swarm it throws at you, then bring the mothership down.", "Tàu mẹ của Hive đang lơ lửng trên Sườn Dung Nham, tiếp bầy drone cho mọi đơn vị Hegemon trong rừng. Chiếm các đường đắp, chọn đòn kế tiếp, trụ vững trước bầy drone nó tung ra, rồi bắn rơi tàu mẹ."),
            ["mission.c5m10.fragment"] = ("Dr Sen walked out of the burning works with her hands up and a hard drive in each. \"Icarus,\" she said. \"You need to see this. Now.\"", "Tiến sĩ Sen bước ra khỏi xưởng đang cháy, hai tay giơ cao, mỗi tay cầm một ổ cứng. \"Icarus,\" bà nói. \"Các anh cần xem cái này. Ngay bây giờ.\""),
            ["mission.c5m10.fragment.title"] = ("Sen", "Sen"),
            ["mission.c5m10.name"] = ("Matriarch", "Matriarch"),
            ["mission.c5s1.brief"] = ("Somewhere in the pass Sen keeps a laboratory off Hegemon's books. {@linh} wants to find it first. Look at all three objectives.", "Đâu đó trên đèo, Sen có một phòng thí nghiệm không có trong sổ sách của Hegemon. {@linh} muốn tìm ra nó trước. Quan sát cả ba cứ điểm."),
            ["mission.c5s1.fragment"] = ("In Sen's hidden lab: rescue drones, painted orange, with medical kits in their bays. Hundreds of them, never armed. She had been building the Hive she wanted.", "Trong phòng thí nghiệm bí mật của Sen: drone cứu hộ, sơn màu cam, trong khoang chứa túi cứu thương. Hàng trăm chiếc, chưa bao giờ gắn vũ khí. Bà vẫn đang chế tạo Hive mà bà mong muốn."),
            ["mission.c5s1.fragment.title"] = ("The second lab", "Phòng thí nghiệm thứ hai"),
            ["mission.c5s1.name"] = ("Sen's Laboratory", "Phòng thí nghiệm của Sen"),
            ["mission.c5s2.brief"] = ("The charcoal burners of the ridge have held out against Hegemon for two years in a fortified camp. Now they are ringed. Break the ring; the besiegers are marked.", "Dân đốt than trên sườn núi đã cầm cự với Hegemon suốt hai năm trong một trại có rào lũy. Giờ họ bị vây kín. Phá vòng vây; quân vây được đánh dấu."),
            ["mission.c5s2.fragment"] = ("The burners paid the brigade in charcoal. {@mai} used it in the base forge for a month and said it was the best she had ever worked with.", "Dân đốt than trả công lữ đoàn bằng than củi. {@mai} dùng nó trong lò rèn của căn cứ suốt một tháng và bảo đó là loại than tốt nhất cô từng dùng."),
            ["mission.c5s2.fragment.title"] = ("Charcoal", "Than củi"),
            ["mission.c5s2.name"] = ("The Charcoal Burners", "Làng đốt than"),
            ["mission.c6m01.brief"] = ("Hegemon strikes back where we first won. Varga is throwing his armour at the Ashfield fortress, ours now, towers and all. Keep its command HQ standing for eight minutes.", "Hegemon phản đòn đúng nơi ta giành chiến thắng đầu tiên. Varga đang tung thiết giáp vào pháo đài Đồng Tro, giờ là của ta, cả tháp lẫn tường. Giữ sở chỉ huy của nó đứng vững trong tám phút."),
            ["mission.c6m01.fragment"] = ("The fortress's old kilns held again, this time for us. {@mai} had reinforced them with the Bastion's own plates. \"Recycling,\" she called it.", "Những lò nung cũ của pháo đài lại trụ vững, lần này là cho ta. {@mai} đã gia cố chúng bằng chính những tấm giáp của Bastion. Cô gọi đó là \"tái chế\"."),
            ["mission.c6m01.fragment.title"] = ("The kilns again", "Lại là lò nung"),
            ["mission.c6m01.name"] = ("Ashfield Under Fire", "Đồng Tro rực lửa"),
            ["mission.c6m02.brief"] = ("Varga's counterstrike is pouring over the pass. The villagers at the frozen lake have to get out: six trucks, one every few seconds, down the road to our camp. Hold the lake until the last one leaves, then cover the road. Four must get through.", "Đợt phản công của Varga đang tràn qua đèo. Dân làng ở hồ băng phải rời đi: sáu xe tải, cứ vài giây một chiếc, theo đường về trại của ta. Giữ hồ cho tới khi xe cuối cùng rời đi, rồi yểm trợ con đường. Phải thoát được bốn xe."),
            ["mission.c6m02.fragment"] = ("The last truck out of Whiteout Pass carried the church bell of the village in the valley. The priest would not leave without it. Nobody argued.", "Chiếc xe cuối cùng rời Đèo Bão Tuyết chở theo quả chuông nhà thờ của ngôi làng dưới thung lũng. Cha xứ không chịu đi nếu không có nó. Chẳng ai cãi."),
            ["mission.c6m02.fragment.title"] = ("The last truck", "Chiếc xe cuối cùng"),
            ["mission.c6m02.name"] = ("Evacuate Whiteout Pass", "Sơ tán Đèo Bão Tuyết"),
            ["mission.c6m03.brief"] = ("{@mai} has done it: the Behemoth from the Ashfield yard runs, and it is ours. Escort it from the fortress across Ashfield to the front. Varga will do anything to stop his own machine.", "{@mai} đã làm được: chiếc Behemoth trong sân pháo đài Đồng Tro đã chạy, và nó là của ta. Hộ tống nó từ Jötunn qua Đồng Tro ra tiền tuyến. Varga sẽ làm mọi cách để chặn chính cỗ máy của hắn."),
            ["mission.c6m03.fragment"] = ("{@mai} named the captured Behemoth \"{@bagia}\" (the Old Lady). Its crew painted a flower on the rear plates, over the weld she had never told anyone about.", "{@mai} đặt tên chiếc Behemoth bắt được là \"{@bagia}\". Kíp lái vẽ một bông hoa lên tấm giáp sau, đè lên đường hàn cô chưa từng kể với ai."),
            ["mission.c6m03.fragment.title"] = ("{@mai}'s Behemoth", "Behemoth của {@mai}"),
            ["mission.c6m03.name"] = ("Our Behemoth", "Behemoth của ta"),
            ["mission.c6m04.brief"] = ("Varga is making for the Hydro Dam that lights half the coast. Get there first: the power station, the road bridge and the ford.", "Varga đang nhắm tới Đập Thủy Điện, nơi thắp sáng nửa dải duyên hải. Tới đó trước hắn: trạm phát điện, cầu đường bộ và bến lội."),
            ["mission.c6m04.fragment"] = ("The Hydro Dam's turbines light every town from Greenvale to Ironport. When Hegemon took the coast, the dam was the only thing its engineers asked to keep running.", "Tua-bin của Đập Thủy Điện thắp sáng mọi thị trấn từ Lũng Xanh tới Cảng Thép. Khi Hegemon chiếm dải duyên hải, con đập là thứ duy nhất các kỹ sư của chúng xin được giữ cho chạy."),
            ["mission.c6m04.fragment.title"] = ("Half the coast", "Nửa dải duyên hải"),
            ["mission.c6m04.name"] = ("The Dam Valley", "Thung lũng con đập"),
            ["mission.c6m05.brief"] = ("Varga has rebuilt the Behemoth we burned at Dunebreak: heavier, heated for the snow, and coming down Whiteout Pass. Stop Behemoth Mk.II before it reaches our lines.", "Varga đã dựng lại chiếc Behemoth ta đốt ở Đồi Cát: nặng hơn, lắp hệ sưởi cho tuyết, và đang xuống Đèo Bão Tuyết. Chặn Behemoth Mk.II trước khi nó tới phòng tuyến của ta."),
            ["mission.c6m05.fragment"] = ("Varga to Orlov: \"Return it with a full tank.\" Orlov to Varga, a week later: \"Returned in several pieces. Tank empty.\"", "Varga gửi Orlov: \"Trả lại nhớ đổ đầy bình.\" Orlov gửi Varga, một tuần sau: \"Đã trả, thành nhiều mảnh. Bình rỗng.\""),
            ["mission.c6m05.fragment.title"] = ("A loan", "Khoản cho mượn"),
            ["mission.c6m05.name"] = ("Behemoth Mk.II", "Behemoth Mk.II"),
            ["mission.c6m06.brief"] = ("The road bridge below the dam is the only way across for heavy armour. Hold it in the fog for four minutes. The bridge must not fall into Varga's hands.", "Cây cầu đường bộ dưới chân đập là lối duy nhất cho thiết giáp hạng nặng vượt sông. Giữ nó trong sương mù bốn phút. Không được để cây cầu rơi vào tay Varga."),
            ["mission.c6m06.fragment"] = ("The bridge was built in 1962 and rated for thirty tons. The brigade ran sixty-ton tanks across it all day. {@mai} does not want to talk about it.", "Cây cầu xây năm 1962, thiết kế chịu tải ba mươi tấn. Lữ đoàn cho xe tăng sáu mươi tấn chạy qua cả ngày. {@mai} không muốn nhắc tới chuyện đó."),
            ["mission.c6m06.fragment.title"] = ("The bridge", "Cây cầu"),
            ["mission.c6m06.name"] = ("Hold the Bridge", "Giữ cây cầu"),
            ["mission.c6m07.brief"] = ("Varga has ringed Ashfield town, where the Alliance militia keep their HQ. Break the ring before it falls; the besiegers are marked.", "Varga đã vây kín thị trấn Đồng Tro, nơi dân quân Liên minh đặt sở chỉ huy. Phá vòng vây trước khi nó thất thủ; quân vây được đánh dấu."),
            ["mission.c6m07.fragment"] = ("The militia had rebuilt the town square with bricks from the old kilns. Varga's guns knocked half of it down. They started rebuilding before the smoke cleared.", "Dân quân đã xây lại quảng trường bằng gạch từ những lò nung cũ. Pháo của Varga bắn sập một nửa. Khói chưa tan, họ đã bắt đầu xây lại."),
            ["mission.c6m07.fragment.title"] = ("Bricks", "Gạch"),
            ["mission.c6m07.name"] = ("The Town Garrison", "Đồn thị trấn"),
            ["mission.c6m08.brief"] = ("Varga's counterstrike comes by sea: Charybdis, a landing hovercraft, is bringing a company of armour onto the beach where we landed. Sink it before it unloads.", "Đợt tổng phản công của Varga tới từ biển: Charybdis, một tàu đệm khí đổ bộ, đang chở cả một đại đội thiết giáp lên chính bãi biển ta đã đổ bộ. Đánh chìm nó trước khi nó dỡ quân."),
            ["mission.c6m08.fragment"] = ("The brigade fought on the beach where it had landed months before. Some of the old tracks were still in the sand.", "Lữ đoàn đánh trên chính bãi biển nơi mình đổ bộ mấy tháng trước. Vài vết xích cũ vẫn còn trên cát."),
            ["mission.c6m08.fragment.title"] = ("The same sand", "Cùng một bãi cát"),
            ["mission.c6m08.name"] = ("Charybdis", "Charybdis"),
            ["mission.c6m09.brief"] = ("Varga has made his winter camp in the south of the pass, in our old positions, and dug in every anti-tank gun he has. Level his HQ, and his counterstrike has no head.", "Varga dựng trại mùa đông ở phía nam đèo, ngay trên các vị trí cũ của ta, và đào sẵn mọi khẩu pháo chống tăng hắn có. San phẳng sở chỉ huy, đợt phản công của hắn sẽ mất đầu."),
            ["mission.c6m09.fragment"] = ("Varga's supply officer, captured at the camp: \"He said he would build two tanks for every one you burned. He stopped saying it in November.\"", "Sĩ quan hậu cần của Varga, bị bắt tại trại: \"Ông ấy nói cứ ta mất một chiếc là ông ấy đóng hai. Ông ấy thôi nói câu đó từ tháng Mười Một.\""),
            ["mission.c6m09.fragment.title"] = ("Two tanks for one", "Hai đổi một"),
            ["mission.c6m09.name"] = ("Varga's Winter Camp", "Trại mùa đông của Varga"),
            ["mission.c6m10.brief"] = ("Varga's last card is Moloch, a factory on tracks that builds tanks as it rolls, and it is coming for the dam. Hold the crest until {@lyhan}'s army arrives.", "Quân bài cuối của Varga là Moloch, một nhà máy bánh xích vừa lăn vừa đóng xe tăng, và nó đang tiến về con đập. Giữ đỉnh đập cho tới khi quân của {@lyhan} tới."),
            ["mission.c6m10.fragment"] = ("General {@lyhan}'s first words on arrival, broadcast to his whole army: \"The Northern Army has saved the dam.\" Colonel Khai's staff heard it too. Nobody said anything.", "Câu đầu tiên của tướng {@lyhan} khi tới nơi, phát cho toàn quân của ông: \"Tập đoàn quân Phương Bắc đã cứu con đập.\" Ban tham mưu của đại tá {@khai} cũng nghe thấy. Không ai nói gì."),
            ["mission.c6m10.fragment.title"] = ("Relief", "Cứu viện"),
            ["mission.c6m10.name"] = ("Defend the Dam", "Bảo vệ con đập"),
            ["mission.c6s1.brief"] = ("Varga's night raiders are bombing the Ashfield fortress. {@dieuhau} wants fourteen of them down before dawn.", "Máy bay đột kích đêm của Varga đang ném bom pháo đài Đồng Tro. {@dieuhau} muốn bắn rơi mười bốn chiếc trước bình minh."),
            ["mission.c6s1.fragment"] = ("At dawn {@dieuhau} counted the wrecks from the air, then landed and counted them again on foot. Fourteen, both times. He bought the anti-air crews breakfast.", "Lúc bình minh, {@dieuhau} đếm xác máy bay từ trên không, rồi hạ cánh đi bộ đếm lại. Cả hai lần đều mười bốn. Anh khao các kíp phòng không bữa sáng."),
            ["mission.c6s1.fragment.title"] = ("Dawn", "Bình minh"),
            ["mission.c6s1.name"] = ("Night Raiders", "Không kích đêm"),
            ["mission.c6s2.brief"] = ("{@mai} needs to know whether the dam will hold a siege. Get a vehicle onto the power station, the bridge and the ford, and let her engineers look.", "{@mai} cần biết con đập có chịu nổi một trận vây hãm hay không. Đưa xe tới trạm phát điện, cây cầu và bến lội để công binh của cô quan sát."),
            ["mission.c6s2.fragment"] = ("The engineers found three cracks in the dam, all old, all repaired by Hegemon's own crews. \"They cared about this dam,\" {@mai} said. \"That makes two of us.\"", "Công binh tìm thấy ba vết nứt trên thân đập, đều cũ, đều đã được chính người của Hegemon sửa. \"Họ quý con đập này,\" {@mai} nói. \"Vậy là có hai bên cùng quý nó.\""),
            ["mission.c6s2.fragment.title"] = ("Cracks", "Vết nứt"),
            ["mission.c6s2.name"] = ("Survey the Dam", "Khảo sát con đập"),
            ["mission.c7m01.brief"] = ("Metro City is the gate to the capital. Take the park, the plaza and the parking lot in the fog, street by street.", "Đô Thành là cửa ngõ vào thủ đô. Chiếm công viên, quảng trường và bãi đỗ xe trong sương mù, từng con phố một."),
            ["mission.c7m01.fragment"] = ("The city's streetlights came on the night we arrived, for the first time in two years. Hegemon had rationed the power. {@mai} had not.", "Đêm ta tới, đèn đường thành phố bật sáng lần đầu tiên sau hai năm. Hegemon đã cắt điện theo khẩu phần. {@mai} thì không."),
            ["mission.c7m01.fragment.title"] = ("Streetlights", "Đèn đường"),
            ["mission.c7m01.name"] = ("Into the City", "Vào thành phố"),
            ["mission.c7m02.brief"] = ("The capital sits on a river island. Before General {@lyhan} arrives, {@linh} wants eyes on the gardens, the palace square and the station.", "Thủ đô nằm trên một hòn đảo giữa sông. Trước khi tướng {@lyhan} tới, {@linh} muốn quan sát khu vườn, quảng trường cung điện và nhà ga."),
            ["mission.c7m02.fragment"] = ("At the station, the recon team met a patrol of General {@lyhan}'s army that was not supposed to be there for three days. Its officer would not say who had sent him.", "Ở nhà ga, tổ trinh sát gặp một toán tuần tra của tướng {@lyhan}, lẽ ra ba ngày nữa mới có mặt. Viên sĩ quan chỉ huy không chịu nói ai đã phái hắn tới."),
            ["mission.c7m02.fragment.title"] = ("{@lyhan}'s men", "Người của {@lyhan}"),
            ["mission.c7m02.name"] = ("The Bridges of {@lamthanh}", "Những cây cầu {@lamthanh}"),
            ["mission.c7m03.brief"] = ("The city has risen: the resistance holds the plaza, and Aurel's guard has it surrounded. Break the ring before their HQ falls; the besiegers are marked.", "Thành phố đã nổi dậy: quân kháng chiến giữ quảng trường, và vệ binh của Aurel đã vây kín họ. Phá vòng vây trước khi sở chỉ huy của họ thất thủ; quân vây được đánh dấu."),
            ["mission.c7m03.fragment"] = ("It rained all day. The people of the plaza held umbrellas over the wounded while the tanks fought round them. Somebody photographed it; the picture was on every wall by evening.", "Trời mưa cả ngày. Người dân ở quảng trường giương ô che cho thương binh trong khi xe tăng giao chiến quanh họ. Có người chụp lại; tới chiều tối, bức ảnh đã dán trên mọi bức tường."),
            ["mission.c7m03.fragment.title"] = ("Umbrellas", "Những chiếc ô"),
            ["mission.c7m03.name"] = ("The Plaza Uprising", "Khởi nghĩa quảng trường"),
            ["mission.c7m04.brief"] = ("Aurel has ordered the city's towers shelled rather than leave them to us: thousands of people live in them. Keep at least one standing for seven minutes.", "Aurel ra lệnh nã pháo vào các tòa tháp của thành phố chứ không chịu để lại cho ta: hàng nghìn người đang sống trong đó. Giữ ít nhất một tòa đứng vững bảy phút."),
            ["mission.c7m04.fragment"] = ("Aurel's order to his artillery, recovered: \"Deny the enemy the high ground. Civilian occupancy estimate: acceptable.\" {@linh} read it out on the radio. The gunners stopped firing.", "Lệnh của Aurel gửi pháo binh, thu được: \"Không để địch chiếm điểm cao. Ước tính số dân thường trong tòa nhà: chấp nhận được.\" {@linh} đọc nó trên sóng phát thanh. Các pháo thủ ngừng bắn."),
            ["mission.c7m04.fragment.title"] = ("Numbers", "Những con số"),
            ["mission.c7m04.name"] = ("The Towers", "Những tòa tháp"),
            ["mission.c7m05.brief"] = ("A missile train is crossing Metro City to its launch siding. When it gets there, a sixty-second countdown starts. Stop it first.", "Một đoàn tàu tên lửa đang băng qua Đô Thành tới đường nhánh phóng. Tới nơi là bắt đầu đếm ngược sáu mươi giây. Phải chặn nó trước."),
            ["mission.c7m05.fragment"] = ("Nemesis's missile carried no warhead. {@linh} found the reason in its papers: the warhead was being fitted somewhere else. On Icarus.", "Tên lửa trên Nemesis không có đầu đạn. {@linh} tìm ra lý do trong giấy tờ của nó: đầu đạn đang được lắp ở một nơi khác. Trên Icarus."),
            ["mission.c7m05.fragment.title"] = ("The warhead", "Đầu đạn"),
            ["mission.c7m05.name"] = ("Nemesis", "Đoàn tàu tận thế"),
            ["mission.c7m06.brief"] = ("A foothold in the capital: the palace square. Aurel's guard wants it back. Hold it in the fog for four minutes.", "Một chỗ đứng chân trong thủ đô: quảng trường cung điện. Vệ binh của Aurel muốn giành lại. Giữ nó trong sương mù bốn phút."),
            ["mission.c7m06.fragment"] = ("The Alliance flag went up over the palace square at 14:10. The Hegemon banner it replaced had been hanging there two years; nobody had ever seen it cleaned.", "Cờ Liên minh được kéo lên trên quảng trường cung điện lúc 14 giờ 10. Lá cờ Hegemon bị thay thế đã treo ở đó hai năm; chưa ai từng thấy nó được giặt."),
            ["mission.c7m06.fragment.title"] = ("The flag", "Lá cờ"),
            ["mission.c7m06.name"] = ("The Palace Square", "Quảng trường cung điện"),
            ["mission.c7m07.brief"] = ("Three of Aurel's commissars are holding the city garrison together from command cars, moving between districts in the storm. Hunt them down; they are marked.", "Ba chính ủy của Aurel đang giữ cho quân đồn trú thành phố khỏi tan rã, di chuyển giữa các quận bằng xe chỉ huy trong cơn bão. Săn lùng họ; họ đã được đánh dấu."),
            ["mission.c7m07.fragment"] = ("Each commissar carried a copy of the contract that gave Hegemon the coast. Clause 41: \"In the event of unrest, the contractor may take such measures as it sees fit.\" Aurel had seen fit.", "Mỗi chính ủy mang theo một bản sao hợp đồng trao dải duyên hải cho Hegemon. Điều 41: \"Trường hợp có bất ổn, nhà thầu được áp dụng mọi biện pháp mà mình thấy phù hợp.\" Aurel đã thấy phù hợp."),
            ["mission.c7m07.fragment.title"] = ("Contracts", "Những bản hợp đồng"),
            ["mission.c7m07.name"] = ("The Commissars", "Các chính ủy"),
            ["mission.c7m08.brief"] = ("The families sheltering in the palace have to get out before the final battle: six trucks across the west bridge, one every few seconds. Four must make it.", "Các gia đình đang trú trong cung điện phải ra ngoài trước trận quyết chiến: sáu xe tải qua cầu phía tây, cứ vài giây một chiếc. Phải thoát được bốn xe."),
            ["mission.c7m08.fragment"] = ("General {@lyhan} offered to take the evacuees to his own camp. Colonel Khai said the trucks would go to ours. {@lyhan} laughed, and said he understood. He did.", "Tướng {@lyhan} đề nghị đưa những người sơ tán về trại của ông. Đại tá {@khai} nói các xe sẽ về trại của ta. {@lyhan} bật cười, bảo ông hiểu. Và ông hiểu thật."),
            ["mission.c7m08.fragment.title"] = ("The west bridge", "Cầu phía tây"),
            ["mission.c7m08.name"] = ("Out of the Palace", "Rời cung điện"),
            ["mission.c7m09.brief"] = ("Aurel speaks to the whole country every night from the radar dome by the palace. Tonight he will not. Destroy it.", "Đêm nào Aurel cũng nói chuyện với cả nước từ vòm radar cạnh cung điện. Đêm nay thì không. Phá hủy nó."),
            ["mission.c7m09.fragment"] = ("Aurel's last broadcast from the capital was cut off mid-sentence: \"The Protectorate will always—\" {@linh} has the tape. She plays it when anyone needs cheering up.", "Buổi phát sóng cuối cùng của Aurel ở thủ đô bị cắt ngang giữa câu: \"Chính quyền Bảo hộ sẽ mãi mãi—\" {@linh} giữ cuộn băng. Cô bật nó mỗi khi có ai cần vui lên."),
            ["mission.c7m09.fragment.title"] = ("The last broadcast", "Buổi phát sóng cuối cùng"),
            ["mission.c7m09.name"] = ("Silence the Broadcast", "Dập tắt đài phát"),
            ["mission.c7m10.brief"] = ("{@lamthanh}, with General {@lyhan}'s army and his base beside us. Take the bridgeheads, choose your blow, storm the palace, and the capital is free. {@linh} has one more thing to say before we go: watch General {@lyhan}.", "{@lamthanh}, với đạo quân và căn cứ của tướng {@lyhan} bên cạnh. Chiếm các đầu cầu, chọn đòn đánh, đánh chiếm cung điện, và thủ đô sẽ được tự do. Trước khi xuất phát, {@linh} còn một điều muốn nói: hãy để mắt tới tướng {@lyhan}."),
            ["mission.c7m10.fragment"] = ("{@lyhan}'s price, found in Aurel's safe: the capital, the ports and the title \"Protector\". Aurel had agreed to all three. He had no intention of honouring any of them.", "Cái giá của {@lyhan}, tìm thấy trong két sắt của Aurel: thủ đô, các bến cảng và danh hiệu \"Người Bảo hộ\". Aurel đồng ý cả ba. Hắn chưa từng định giữ lời điều nào."),
            ["mission.c7m10.fragment.title"] = ("The price", "Cái giá"),
            ["mission.c7m10.name"] = ("Liberate the Capital", "Giải phóng thủ đô"),
            ["mission.c7s1.brief"] = ("{@linh} has intercepted letters between General {@lyhan} and someone in Metro City. She wants to see the three drop points for herself, quietly.", "{@linh} đã chặn được những bức thư giữa tướng {@lyhan} và một người nào đó ở Đô Thành. Cô muốn tự mình xem ba điểm trao thư, một cách lặng lẽ."),
            ["mission.c7s1.fragment"] = ("{@linh}'s report to Colonel Khai, handwritten, one copy: \"{@lyhan} is talking to Aurel. I cannot prove it yet. I am sure.\" Khai read it twice and locked it in his desk.", "Báo cáo của {@linh} gửi đại tá {@khai}, viết tay, một bản duy nhất: \"{@lyhan} đang liên lạc với Aurel. Tôi chưa chứng minh được. Nhưng tôi chắc chắn.\" {@khai} đọc hai lần rồi khóa nó vào ngăn bàn."),
            ["mission.c7s1.fragment.title"] = ("{@linh}'s report", "Báo cáo của {@linh}"),
            ["mission.c7s1.name"] = ("The Letters", "Những bức thư"),
            ["mission.c7s2.brief"] = ("Aurel's guard helicopters are hunting the resistance over the rooftops in the storm. Fourteen of them, down.", "Trực thăng vệ binh của Aurel đang săn quân kháng chiến trên các mái nhà giữa cơn bão. Mười bốn chiếc, bắn rơi hết."),
            ["mission.c7s2.fragment"] = ("The resistance lit fires on the rooftops to mark the helicopters for our gunners. {@dieuhau} said it was the prettiest city he had ever fought over.", "Quân kháng chiến đốt lửa trên các mái nhà để đánh dấu trực thăng cho pháo thủ của ta. {@dieuhau} bảo đó là thành phố đẹp nhất anh từng chiến đấu trên bầu trời của nó."),
            ["mission.c7s2.fragment.title"] = ("Rooftops", "Những mái nhà"),
            ["mission.c7s2.name"] = ("Storm over the Capital", "Bão trên thủ đô"),
            ["mission.c8m01.brief"] = ("{@lyhan}'s trail leads north into the mining country. Take the canyon crossings from the other side, at night.", "Dấu vết của {@lyhan} dẫn lên vùng mỏ phía bắc. Chiếm các ngả qua hẻm núi từ phía bên kia, trong đêm."),
            ["mission.c8m01.fragment"] = ("{@lyhan}'s staff cars left the capital in the rain. By morning their tracks were in the red canyons.", "Xe tham mưu của {@lyhan} rời thủ đô trong mưa. Tới sáng, vết bánh đã in trên các hẻm núi đỏ."),
            ["mission.c8m01.fragment.title"] = ("The trail", "Dấu vết"),
            ["mission.c8m01.name"] = ("Into the Mines", "Vào khu mỏ"),
            ["mission.c8m02.brief"] = ("We hold the ore depot on the pit's rim. {@lyhan} wants it back tonight. Keep the brigade alive until morning.", "Ta đang giữ kho quặng trên miệng hố mỏ. {@lyhan} muốn lấy lại nó ngay đêm nay. Giữ cho lữ đoàn trụ vững tới sáng."),
            ["mission.c8m02.fragment"] = ("Hegemon had paid for the depot's ore in advance, for ten years. Nobody would collect it now.", "Hegemon đã trả tiền quặng của kho trước cho mười năm. Giờ chẳng còn ai tới lấy."),
            ["mission.c8m02.fragment.title"] = ("Ore", "Quặng"),
            ["mission.c8m02.name"] = ("The Ore Depot", "Kho quặng"),
            ["mission.c8m03.brief"] = ("{@lyhan}'s rocket batteries shell the mine road from the mesas. {@linh} has marked them. Hunt them down.", "Các khẩu đội rốc-két của {@lyhan} nã vào đường mỏ từ trên các khối đá. {@linh} đã đánh dấu chúng. Săn chúng."),
            ["mission.c8m03.fragment"] = ("{@lyhan}'s gunners had trained with ours. They still used our old call signs.", "Pháo thủ của {@lyhan} từng huấn luyện cùng người của ta. Họ vẫn dùng mật danh cũ của ta."),
            ["mission.c8m03.fragment.title"] = ("Old habits", "Thói quen cũ"),
            ["mission.c8m03.name"] = ("Battery Hunt", "Săn khẩu đội"),
            ["mission.c8m04.brief"] = ("The miners of the canyon town have risen against {@lyhan}, and his tanks have them ringed. Break the ring in the sandstorm.", "Thợ mỏ ở thị trấn hẻm núi đã nổi dậy chống {@lyhan}, và xe tăng của hắn vây kín họ. Phá vòng vây trong bão cát."),
            ["mission.c8m04.fragment"] = ("The miners paid the brigade in spare parts. Half of them fitted the Behemoth {@mai} keeps \"for the museum\".", "Thợ mỏ trả ơn lữ đoàn bằng phụ tùng. Một nửa lắp vừa chiếc Behemoth {@mai} giữ lại \"cho bảo tàng\"."),
            ["mission.c8m04.fragment.title"] = ("Spare parts", "Phụ tùng"),
            ["mission.c8m04.name"] = ("The Mine Town", "Thị trấn mỏ"),
            ["mission.c8m05.brief"] = ("{@lyhan} has sent Tartarus, Varga's old tunnelling machine, under the Hydro Dam towards the power station. Stop it before it gets there.", "{@lyhan} đã tung Tartarus, cỗ máy khoan cũ của Varga, luồn dưới Đập Thủy Điện về phía trạm phát điện. Chặn nó trước khi nó tới nơi."),
            ["mission.c8m05.fragment"] = ("Tartarus was built to dig mines. Varga fitted it with guns and a battering head. Its original crew, miners from Redrock Canyon, refused to drive it. He found another crew.", "Tartarus được chế tạo để đào mỏ. Varga gắn thêm pháo và một đầu húc. Kíp lái cũ, thợ mỏ ở Hẻm Đá Đỏ, từ chối lái nó. Hắn tìm kíp khác."),
            ["mission.c8m05.fragment.title"] = ("The earthworm", "Con giun đất"),
            ["mission.c8m05.name"] = ("Tartarus", "Tartarus"),
            ["mission.c8m06.brief"] = ("The mine tunnels come out under the dam. Hold the crossing at night while {@lyhan} tries to break through.", "Các đường hầm mỏ thông ra dưới con đập. Giữ ngả qua trong đêm khi {@lyhan} tìm cách chọc thủng."),
            ["mission.c8m06.fragment"] = ("All night the tunnels echoed with engines. Nobody could tell whose.", "Suốt đêm các đường hầm vọng tiếng động cơ. Không ai phân biệt được là của ai."),
            ["mission.c8m06.fragment.title"] = ("Echoes", "Tiếng vọng"),
            ["mission.c8m06.name"] = ("The Tunnel Mouth", "Miệng hầm"),
            ["mission.c8m07.brief"] = ("A haul truck with wheels taller than a tank is coming down the haul road at full speed: Ixion. Stop it before it rams our columns.", "Một xe chở quặng có bánh cao hơn xe tăng đang lao xuống đường vận chuyển hết tốc lực: Ixion. Chặn nó trước khi nó húc vào đội hình của ta."),
            ["mission.c8m07.fragment"] = ("One of Ixion's wheels rolled on alone for two kilometres after the truck died.", "Một bánh của Ixion còn tự lăn thêm hai cây số sau khi chiếc xe đã chết máy."),
            ["mission.c8m07.fragment.title"] = ("Wheels", "Bánh xe"),
            ["mission.c8m07.name"] = ("Ixion", "Ixion"),
            ["mission.c8m08.brief"] = ("Before we go into the deepest pit, {@linh} wants to see it. Get a vehicle onto each marked spot in the storm.", "Trước khi vào hố mỏ sâu nhất, {@linh} muốn tận mắt thấy nó. Đưa xe tới từng điểm đánh dấu trong cơn bão."),
            ["mission.c8m08.fragment"] = ("The photographs showed a machine the size of a building at the bottom of the pit. Its bucket wheel was turning.", "Các tấm ảnh cho thấy một cỗ máy to bằng tòa nhà dưới đáy hố. Bánh gầu của nó đang quay."),
            ["mission.c8m08.fragment.title"] = ("The pit", "Hố mỏ"),
            ["mission.c8m08.name"] = ("Eyes on the Pit", "Mắt nhìn hố mỏ"),
            ["mission.c8m09.brief"] = ("{@lyhan} has dug his headquarters into the end of the canyon. Level it. He will run again; make him run faster.", "{@lyhan} đã đào sở chỉ huy vào cuối hẻm núi. San phẳng nó. Hắn sẽ lại chạy; bắt hắn chạy nhanh hơn."),
            ["mission.c8m09.fragment"] = ("In the abandoned camp: {@lyhan}'s medals from the liberation war, in a box, polished.", "Trong trại bỏ hoang: những tấm huân chương thời chiến tranh giải phóng của {@lyhan}, trong một chiếc hộp, được đánh bóng."),
            ["mission.c8m09.fragment.title"] = ("Medals", "Huân chương"),
            ["mission.c8m09.name"] = ("{@lyhan}'s Camp", "Trại của {@lyhan}"),
            ["mission.c8m10.brief"] = ("The operation into {@lyhan}'s mine: take the pit's rim, choose what to hit next, blow the works, then face what waits at the bottom: Kronos.", "Chiến dịch vào khu mỏ của {@lyhan}: chiếm miệng hố, chọn mục tiêu kế tiếp, phá các xưởng, rồi đối mặt với thứ đang chờ dưới đáy: Kronos."),
            ["mission.c8m10.fragment"] = ("Kronos went down into its own pit. {@lyhan} was already on a boat.", "Kronos sụp xuống chính hố mỏ của nó. {@lyhan} thì đã ở trên một con tàu."),
            ["mission.c8m10.fragment.title"] = ("Buried", "Chôn vùi"),
            ["mission.c8m10.name"] = ("The Deepest Pit", "Hố sâu nhất"),
            ["mission.c8s1.brief"] = ("{@linh} wants the mine's survey maps from three buildings on the dunes. Look, do not linger.", "{@linh} muốn lấy bản đồ khảo sát của khu mỏ từ ba tòa nhà trên đồi cát. Nhìn thôi, đừng nán lại."),
            ["mission.c8s1.fragment"] = ("The maps showed every tunnel {@lyhan} could use. {@linh} drew the rest.", "Bản đồ cho thấy mọi đường hầm {@lyhan} có thể dùng. {@linh} vẽ nốt phần còn lại."),
            ["mission.c8s1.fragment.title"] = ("Surveys", "Khảo sát"),
            ["mission.c8s1.name"] = ("Survey Maps", "Bản đồ khảo sát"),
            ["mission.c8s2.brief"] = ("{@lyhan} is flying his gold out of the mines at night. Shoot down his transports.", "{@lyhan} đang chở vàng ra khỏi khu mỏ trong đêm. Bắn hạ các máy bay vận tải của hắn."),
            ["mission.c8s2.fragment"] = ("The crates were not gold. They were Hegemon contracts, signed.", "Các thùng hàng không phải vàng. Đó là những bản hợp đồng Hegemon, đã ký."),
            ["mission.c8s2.fragment.title"] = ("Gold", "Vàng"),
            ["mission.c8s2.name"] = ("Night Flights", "Chuyến bay đêm"),
            ["mission.c9m01.brief"] = ("{@lyhan} has taken Ironport with what is left of Kessler's men. Take the docks back in the storm.", "{@lyhan} đã chiếm Cảng Thép cùng tàn quân của Kessler. Chiếm lại cầu tàu trong cơn bão."),
            ["mission.c9m01.fragment"] = ("Kessler's sailors still wore his badges, with {@lyhan}'s ribbon pinned over them.", "Thủy thủ của Kessler vẫn đeo phù hiệu của hắn, với dải băng của {@lyhan} ghim đè lên."),
            ["mission.c9m01.fragment.title"] = ("Old uniforms", "Quân phục cũ"),
            ["mission.c9m01.name"] = ("The Harbour Again", "Lại bến cảng"),
            ["mission.c9m02.brief"] = ("{@lyhan} is landing troops on the beach where our war began. Take the beach from the other side, in the rain.", "{@lyhan} đang đổ quân lên chính bãi biển nơi cuộc chiến của ta bắt đầu. Chiếm bãi biển từ phía bên kia, trong mưa."),
            ["mission.c9m02.fragment"] = ("The same dunes, the same rain. This time the brigade came from inland.", "Cùng những đụn cát, cùng cơn mưa. Lần này lữ đoàn tiến từ đất liền ra."),
            ["mission.c9m02.fragment.title"] = ("Full circle", "Một vòng tròn"),
            ["mission.c9m02.name"] = ("Back to the Beach", "Trở lại bãi biển"),
            ["mission.c9m03.brief"] = ("Take the supply convoy through the harbour roads at night. {@lyhan}'s patrols are waiting.", "Đưa đoàn xe tiếp tế qua các con đường bến cảng trong đêm. Lính tuần của {@lyhan} đang chờ."),
            ["mission.c9m03.fragment"] = ("The drivers went through the harbour with their lights off. One of them sang all the way.", "Các tài xế đi qua bến cảng với đèn tắt. Một người hát suốt dọc đường."),
            ["mission.c9m03.fragment.title"] = ("Lights off", "Tắt đèn"),
            ["mission.c9m03.name"] = ("Night Convoy", "Đoàn xe đêm"),
            ["mission.c9m04.brief"] = ("{@lyhan} has put guns back on the beach. Destroy them before his ships come in.", "{@lyhan} đã đặt lại pháo trên bãi biển. Phá chúng trước khi tàu của hắn cập bờ."),
            ["mission.c9m04.fragment"] = ("Some of the guns were the ones we silenced on the first day, repaired.", "Vài khẩu pháo chính là những khẩu ta bắt câm họng ngày đầu tiên, đã được sửa lại."),
            ["mission.c9m04.fragment.title"] = ("Rust", "Gỉ sét"),
            ["mission.c9m04.name"] = ("The Coastal Guns", "Pháo bờ biển"),
            ["mission.c9m05.brief"] = ("Out of the fog comes Caspian, a ground-effect ship that skims the waves and lands troops. Bring it down before it reaches the beach.", "Từ trong sương lao ra Caspian, một con tàu bay sát mặt sóng và đổ quân. Hạ nó trước khi nó tới bãi biển."),
            ["mission.c9m05.fragment"] = ("Caspian's wing floated for a week. Children from the village swam out to sit on it.", "Cánh của Caspian nổi trên mặt nước suốt một tuần. Trẻ con trong làng bơi ra ngồi lên nó."),
            ["mission.c9m05.fragment.title"] = ("Wings", "Cánh"),
            ["mission.c9m05.name"] = ("Caspian", "Caspian"),
            ["mission.c9m06.brief"] = ("{@lyhan} has set up his headquarters on the far docks. Level it and cut him off from the sea.", "{@lyhan} đặt sở chỉ huy ở cầu tàu phía xa. San phẳng nó và cắt đường ra biển của hắn."),
            ["mission.c9m06.fragment"] = ("{@lyhan}'s charts showed one route out: past the lighthouse, where the submarine waited.", "Hải đồ của {@lyhan} chỉ một đường thoát: qua ngọn hải đăng, nơi tàu ngầm đang chờ."),
            ["mission.c9m06.fragment.title"] = ("Charts", "Hải đồ"),
            ["mission.c9m06.name"] = ("{@lyhan}'s Harbour HQ", "Sở chỉ huy bến cảng"),
            ["mission.c9m07.brief"] = ("Our spotters in the port buildings guide our guns. Keep one of them standing through {@lyhan}'s night attack.", "Các trạm quan sát của ta trong khu bến cảng dẫn đường cho pháo. Giữ ít nhất một trạm đứng vững qua trận tấn công đêm của {@lyhan}."),
            ["mission.c9m07.fragment"] = ("The spotters kept one lamp lit all night, on purpose. It drew the fire away from the rest.", "Các trạm quan sát cố ý để một ngọn đèn sáng suốt đêm. Nó hút hỏa lực khỏi những trạm còn lại."),
            ["mission.c9m07.fragment.title"] = ("Lamps", "Ngọn đèn"),
            ["mission.c9m07.name"] = ("The Lighthouse Keepers", "Người giữ hải đăng"),
            ["mission.c9m08.brief"] = ("Scylla is back in service under {@lyhan}'s flag, guarding the bay in the rain. Sink it for good this time.", "Scylla trở lại hoạt động dưới cờ của {@lyhan}, canh vịnh trong mưa. Lần này đánh chìm hẳn nó."),
            ["mission.c9m08.fragment"] = ("Scylla's new plates were welded over the old holes. Some of the welds were ours.", "Các tấm giáp mới của Scylla được hàn đè lên những lỗ thủng cũ. Vài đường hàn là của người bên ta."),
            ["mission.c9m08.fragment.title"] = ("Patched", "Vá víu"),
            ["mission.c9m08.name"] = ("Scylla Again", "Lại là Scylla"),
            ["mission.c9m09.brief"] = ("{@lyhan}'s mortar teams are shelling the beach road. Hunt the marked ones.", "Các tổ súng cối của {@lyhan} đang nã vào đường bờ biển. Săn những tổ đã đánh dấu."),
            ["mission.c9m09.fragment"] = ("One of the mortar crews surrendered with their tea still hot. They offered it round.", "Một tổ súng cối ra hàng khi ấm trà vẫn còn nóng. Họ mời mọi người cùng uống."),
            ["mission.c9m09.fragment.title"] = ("Tea", "Trà"),
            ["mission.c9m09.name"] = ("Beach Hunt", "Săn trên bãi biển"),
            ["mission.c9m10.brief"] = ("The operation for the coast: take the harbour, choose what to hit, clear the works, then stop Typhon, the missile submarine that is {@lyhan}'s last card.", "Chiến dịch giành bờ biển: chiếm bến cảng, chọn mục tiêu, dọn sạch các xưởng, rồi chặn Typhon, chiếc tàu ngầm tên lửa là quân bài cuối của {@lyhan}."),
            ["mission.c9m10.fragment"] = ("{@lyhan} was taken on the bridge of his flagship, in full uniform. He asked to see {@khai}. {@khai} did not go.", "{@lyhan} bị bắt trên đài chỉ huy soái hạm, quân phục chỉnh tề. Hắn xin gặp {@khai}. {@khai} không tới."),
            ["mission.c9m10.fragment.title"] = ("The general", "Viên tướng"),
            ["mission.c9m10.name"] = ("Rough Seas", "Biển động"),
            ["mission.c9s1.brief"] = ("Kessler's old minelayers are working for {@lyhan} now. Hunt the marked ones before they close the harbour.", "Những xe rải mìn cũ của Kessler giờ làm việc cho {@lyhan}. Săn những chiếc đã đánh dấu trước khi chúng phong tỏa bến cảng."),
            ["mission.c9s1.fragment"] = ("The minelayers still worked to Kessler's timetable. That made them easy to find.", "Các xe rải mìn vẫn chạy theo thời gian biểu của Kessler. Nhờ thế mà dễ tìm."),
            ["mission.c9s1.fragment.title"] = ("Timetables", "Thời gian biểu"),
            ["mission.c9s1.name"] = ("The Last Minelayers", "Những tàu rải mìn cuối cùng"),
            ["mission.c9s2.brief"] = ("{@lyhan}'s radio posts on the beach talk to his ships. Take them in the fog.", "Các trạm vô tuyến của {@lyhan} trên bãi biển liên lạc với tàu của hắn. Chiếm chúng trong sương."),
            ["mission.c9s2.fragment"] = ("{@linh} kept the posts' codebook. It opened every door of the next battle.", "{@linh} giữ lại cuốn mật mã của các trạm. Nó mở mọi cánh cửa cho trận đánh sau."),
            ["mission.c9s2.fragment.title"] = ("Frequencies", "Tần số"),
            ["mission.c9s2.name"] = ("The Radio Hut", "Trạm vô tuyến"),
            ["radio.alliedStrikes"] = ("Hawk here: the air corridor is open. Strikes on call, every minute.", "Hawk đây: hành lang bay đã mở. Không kích theo yêu cầu, mỗi phút một lượt."),
            ["radio.aurel.c10m05.2"] = ("A field test, Colonel. Thank you for volunteering.", "Một cuộc thử nghiệm thực địa thôi, đại tá. Cảm ơn ông đã tình nguyện."),
            ["radio.aurel.c11m09.1"] = ("The gate is closed, Colonel. Permanently.", "Cửa ngõ đã đóng, đại tá. Vĩnh viễn."),
            ["radio.aurel.c11m10.s4"] = ("Daedalus, bring them down on the gate.", "Daedalus, thả chúng xuống cửa ngõ."),
            ["radio.aurel.c12m04.p1"] = ("My guard costs more than your brigade, Colonel.", "Đội cận vệ của tôi đắt hơn cả lữ đoàn của ông, đại tá."),
            ["radio.aurel.c12m05.2"] = ("Icarus is not a weapon, Colonel. It is a contract nobody can refuse.", "Icarus không phải vũ khí, đại tá. Nó là một bản hợp đồng không ai từ chối nổi."),
            ["radio.aurel.c12m06.p1"] = ("Pilots are an expense. Drones are an investment.", "Phi công là chi phí. Drone là khoản đầu tư."),
            ["radio.aurel.c12m10.s4"] = ("You are standing on my balance sheet, Colonel.", "Ông đang đứng trên bảng cân đối của tôi đấy, đại tá."),
            ["radio.aurel.c12m10.s6"] = ("Launch. Manually, since you insist. Try to follow me to orbit, Colonel.", "Phóng. Bằng tay, vì ông cứ nhất định như thế. Cứ thử theo tôi lên quỹ đạo mà xem, đại tá."),
            ["radio.aurel.c7m01.1"] = ("Welcome to my city, Colonel. Please do not scratch the paintwork.", "Chào mừng tới thành phố của tôi, đại tá. Làm ơn đừng làm xước lớp sơn."),
            ["radio.aurel.c7m09.1"] = ("Everyone has a price, Colonel.", "Ai cũng có giá, đại tá."),
            ["radio.aurel.defeat"] = ("This was not in the forecast.", "Chuyện này không có trong dự báo."),
            ["radio.aurel.taunt.1"] = ("Your brigade is a rounding error on my balance sheet.", "Lữ đoàn của ông chỉ là sai số làm tròn trên bảng cân đối của tôi."),
            ["radio.aurel.taunt.2"] = ("Everyone has a price, Colonel. General {@lyhan} had his.", "Ai cũng có giá, đại tá. Tướng {@lyhan} cũng có giá của ông ta."),
            ["radio.aurel.taunt.3"] = ("Icarus is not a weapon. It is a contract nobody can refuse.", "Icarus không phải vũ khí. Nó là một bản hợp đồng không ai từ chối nổi."),
            ["radio.bossFled"] = ("It is breaking off! Let it go, we have what we came for.", "Nó đang tháo chạy! Để nó đi, ta đạt được mục tiêu rồi."),
            ["radio.dieuhau.c10m01.2"] = ("Still faster than you, Crow.", "Vẫn nhanh hơn mày, Quạ ạ."),
            ["radio.dieuhau.c10m04.1"] = ("They are parked in a line. He always did like to show off.", "Chúng đỗ thành một hàng. Hắn lúc nào cũng thích khoe mẽ."),
            ["radio.dieuhau.c10m06.1"] = ("Get those launchers and I buy the beer.", "Diệt được mấy bệ phóng đó thì tôi khao bia."),
            ["radio.dieuhau.c10m08.1"] = ("It flies above my ceiling at night. The SAMs will have to do this one.", "Ban đêm nó bay cao hơn trần bay của tôi. Lần này phải nhờ tên lửa phòng không rồi."),
            ["radio.dieuhau.c10m08.2"] = ("The ghost is down. Sleep well tonight, everyone.", "Bóng ma rơi rồi. Đêm nay mọi người ngủ ngon nhé."),
            ["radio.dieuhau.c10m08.p1"] = ("Spectre is up there. Keep the launchers busy.", "Spectre đang ở trên đó. Cho các bệ phóng làm việc liên tục."),
            ["radio.dieuhau.c10m10.s4"] = ("That's him in the lead jet. He's mine, everyone. Keep the others off me.", "Hắn ở chiếc dẫn đầu. Hắn là của tôi, mọi người. Giữ mấy chiếc kia khỏi bám tôi."),
            ["radio.dieuhau.c10s2.p1"] = ("Argus, {@quaden}'s recon airship. It is watching us.", "Argus, khí cầu trinh sát của {@quaden}. Nó đang theo dõi ta."),
            ["radio.dieuhau.c11m08.1"] = ("No fuel, no air cover. Bring me my fuel.", "Không có nhiên liệu thì không có yểm trợ trên không. Mang nhiên liệu cho tôi."),
            ["radio.dieuhau.c12m06.2"] = ("For the old days, Crow.", "Vì ngày xưa, Quạ ạ."),
            ["radio.dieuhau.c12s2.1"] = ("The last of them. Let's make it quick.", "Tốp cuối cùng rồi. Làm nhanh gọn thôi."),
            ["radio.dieuhau.c1m01.2"] = ("{@dieuhau} overhead. Beach exit is ours, I can see the whole bay from here!", "{@dieuhau} trên đầu các anh đây. Cửa ra bãi biển là của ta rồi, từ đây tôi thấy cả vịnh!"),
            ["radio.dieuhau.c2s2.1"] = ("Helicopters, low and slow. My favourite kind.", "Trực thăng, bay thấp và chậm. Loại tôi khoái nhất."),
            ["radio.dieuhau.c3m05.1"] = ("Big bird, big target. Keep the launchers moving under it.", "Chim to, bia to. Cho các bệ phóng di chuyển liên tục dưới nó."),
            ["radio.dieuhau.c3m05.3"] = ("Harpy is down! Somebody owes me a drink.", "Harpy rơi rồi! Có ai đó nợ tôi một chầu đấy."),
            ["radio.dieuhau.c5m07.1"] = ("Drones, lots of them. Keep the anti-air moving under the trees.", "Drone, nhiều lắm. Cho phòng không di chuyển liên tục dưới tán cây."),
            ["radio.dieuhau.c6m08.1"] = ("Something big on the water, Colonel. Bigger than a boat, faster than a tank.", "Có thứ gì to lắm trên mặt nước, đại tá. To hơn xuồng, nhanh hơn xe tăng."),
            ["radio.dieuhau.c6s1.1"] = ("They come in low from the north. Let them.", "Chúng bay thấp tới từ phía bắc. Cứ để chúng tới."),
            ["radio.dieuhau.c7s2.1"] = ("Watch the fires on the roofs. Each one is a helicopter.", "Nhìn những đốm lửa trên mái nhà. Mỗi đốm là một chiếc trực thăng."),
            ["radio.dieuhau.c8s2.1"] = ("Night hunting. My favourite.", "Săn đêm. Món tôi thích nhất."),
            ["radio.enemyWeakened"] = ("Their supply is burning. They will feel that for the rest of the day.", "Kho tiếp tế của chúng đang cháy. Cả ngày hôm nay chúng sẽ thấm đòn."),
            ["radio.hung.c6m10.s4"] = ("{@khai}! {@lyhan} here, the Northern Army is on the road. Hold on, we are coming.", "{@khai}! {@lyhan} đây, Tập đoàn quân Phương Bắc đang trên đường. Cố lên, chúng tôi đang tới."),
            ["radio.hung.c7m10.atlas"] = ("Atlas, cover me. We are leaving the city.", "Atlas, yểm trợ ta. Ta rời thành phố."),
            ["radio.hung.c7m10.s1"] = ("The Northern Army takes the left. {@khai}, take the right, and we meet at the palace.", "Tập đoàn quân Phương Bắc đánh cánh trái. {@khai}, cánh phải, ta gặp nhau ở cung điện."),
            ["radio.hung.c7m10.s4"] = ("I am sorry, {@khai}. The coast needs a protector. It was never going to be you.", "Tôi xin lỗi, {@khai}. Dải duyên hải cần một người bảo hộ. Người đó chưa bao giờ là anh."),
            ["radio.hung.c8m05.p1"] = ("You will not see it coming, {@khai}.", "Các người sẽ không thấy nó tới đâu, {@khai}."),
            ["radio.hung.c8m06.1"] = ("The mountain is mine, {@khai}. Every tunnel.", "Ngọn núi là của ta, {@khai}. Mọi đường hầm."),
            ["radio.hung.c8m09.1"] = ("I earned this country before you were a colonel.", "Ta đã giành lấy đất nước này khi ngươi còn chưa là đại tá."),
            ["radio.hung.c8m10.s5"] = ("Wake up, Kronos. Dig them a grave.", "Thức dậy đi, Kronos. Đào cho chúng một nấm mồ."),
            ["radio.hung.c9m06.1"] = ("The sea does not belong to you, {@khai}.", "Biển không thuộc về ngươi, {@khai}."),
            ["radio.hung.c9m08.1"] = ("Kessler's ship. My sailors.", "Tàu của Kessler. Thủy thủ của ta."),
            ["radio.hung.c9m10.2"] = ("Enough. Tell {@khai} I surrender.", "Đủ rồi. Nói với {@khai} ta đầu hàng."),
            ["radio.hung.c9m10.s4"] = ("Typhon, surface. Fire everything.", "Typhon, nổi lên. Bắn tất cả."),
            ["radio.hung.defeat"] = ("Enough. Tell {@khai}… tell him I surrender.", "Đủ rồi. Nói với {@khai}… nói rằng ta đầu hàng."),
            ["radio.hung.taunt.1"] = ("I liberated this country once. I can take it back from you.", "Ta đã giải phóng đất nước này một lần. Ta lấy lại nó từ tay các người được."),
            ["radio.hung.taunt.2"] = ("Titans do not kneel, Colonel.", "Titan không biết quỳ, đại tá ạ."),
            ["radio.hung.taunt.3"] = ("Aurel paid well. You only ever gave orders.", "Aurel trả hậu hĩnh. Còn các người chỉ biết ra lệnh."),
            ["radio.kessler.c12m02.1"] = ("The next train leaves on time. With or without you under it.", "Chuyến tàu sau sẽ chạy đúng giờ. Dù có ngươi nằm dưới bánh hay không."),
            ["radio.kessler.c12m02.2"] = ("Cancel the timetable. All of it.", "Hủy lịch trình. Toàn bộ."),
            ["radio.kessler.c12m02.p1"] = ("Tempest, on schedule. As always.", "Tempest, đúng lịch. Như mọi khi."),
            ["radio.kessler.c4m01.1"] = ("You are four minutes behind schedule, Colonel.", "Ngươi đang trễ bốn phút so với lịch, đại tá."),
            ["radio.kessler.c4m05.1"] = ("The train leaves on time, Colonel. It always does.", "Tàu chạy đúng giờ, đại tá. Xưa nay vẫn thế."),
            ["radio.kessler.c4m05.3"] = ("Cancel the timetable.", "Hủy lịch trình."),
            ["radio.kessler.c4m06.1"] = ("Scylla leaves on time, Colonel.", "Scylla rời bến đúng giờ, đại tá."),
            ["radio.kessler.c4m09.1"] = ("Every road here is mined. I checked.", "Mọi con đường ở đây đều có mìn. Ta đã kiểm tra rồi."),
            ["radio.kessler.c4m09.2"] = ("Evacuate the quarters. By sea.", "Sơ tán tổng hành dinh. Bằng đường biển."),
            ["radio.kessler.c4m10.s4"] = ("Tempest, clear the docks. On schedule.", "Tempest, dọn sạch bến tàu. Đúng lịch."),
            ["radio.kessler.defeat"] = ("Cancel the timetable. Evacuate the port by sea.", "Hủy lịch trình. Sơ tán bến cảng bằng đường biển."),
            ["radio.kessler.taunt.1"] = ("You are four minutes behind schedule, Colonel.", "Ngươi đang trễ bốn phút so với lịch, đại tá."),
            ["radio.kessler.taunt.2"] = ("Every road here is mined. I checked.", "Mọi con đường ở đây đều có mìn. Ta đã kiểm tra rồi."),
            ["radio.kessler.taunt.3"] = ("The next train leaves on time. With or without you under it.", "Chuyến tàu sau sẽ chạy đúng giờ. Dù có ngươi nằm dưới bánh hay không."),
            ["radio.khai.c10m03.1"] = ("The radar is our eyes. Keep them open.", "Radar là mắt của ta. Giữ cho mắt mở."),
            ["radio.khai.c10m05.3"] = ("It ran. Next time, it will not get the chance.", "Nó chạy rồi. Lần sau, nó sẽ không có cơ hội đó."),
            ["radio.khai.c10m10.1"] = ("The last air base on the coast. Take it and the sky is ours.", "Căn cứ không quân cuối cùng trên dải duyên hải. Chiếm nó là bầu trời thuộc về ta."),
            ["radio.khai.c10m10.2"] = ("Skyhold Airbase has fallen. The sky belongs to the Alliance.", "Căn Cứ Tầng Mây đã thất thủ. Bầu trời thuộc về Liên minh."),
            ["radio.khai.c10m10.s1"] = ("The radars first. Blind, he cannot direct his wing.", "Radar trước. Mù rồi, hắn không chỉ huy được phi đội."),
            ["radio.khai.c10m10.s6"] = ("The garrison is making its last push. Hold the base.", "Quân đồn trú đang dốc sức lần cuối. Giữ lấy căn cứ."),
            ["radio.khai.c11m01.1"] = ("The gate first. Then the launch site.", "Cửa ngõ trước. Rồi tới bãi phóng."),
            ["radio.khai.c11m03.1"] = ("Blind it, and his ships land where we want.", "Làm mù nó, tàu của hắn sẽ đáp đúng chỗ ta muốn."),
            ["radio.khai.c11m06.1"] = ("Hold the high ground.", "Giữ điểm cao."),
            ["radio.khai.c11m10.1"] = ("The gate, Brigade. The last door before the launch site.", "Cửa ngõ, Lữ đoàn. Cánh cửa cuối cùng trước bãi phóng."),
            ["radio.khai.c12m09.1"] = ("Hold the refinery. Tomorrow we finish this.", "Giữ nhà máy lọc dầu. Ngày mai ta kết thúc chuyện này."),
            ["radio.khai.c12m10.1"] = ("This is it, Brigade. Everything we have, one more time.", "Là lúc này đây, Lữ đoàn. Tất cả những gì ta có, thêm một lần nữa."),
            ["radio.khai.c12m10.2"] = ("It is over. Brigade, stand down. We go home.", "Kết thúc rồi. Lữ đoàn, nghỉ. Ta về nhà."),
            ["radio.khai.c12m10.s1"] = ("The propellant farm first. Then we choose.", "Khu nhiên liệu đẩy trước. Rồi ta sẽ chọn."),
            ["radio.khai.c1m01.1"] = ("Brigade, this is {@khai}. Off the sand and up the draw. Nobody stops on the beach.", "Lữ đoàn, {@khai} đây. Rời bãi cát, lên dốc. Không ai được dừng lại trên bãi biển."),
            ["radio.khai.c1m01.3"] = ("Beachhead secured. Now we find somewhere to build.", "Đầu cầu đã an toàn. Giờ tìm chỗ dựng căn cứ."),
            ["radio.khai.c1m02.2"] = ("Radar down. Tell the boats they can come in.", "Radar đã sập. Báo các xuồng vào bờ được rồi."),
            ["radio.khai.c1m03.1"] = ("Three objectives, light resistance. Show me what the brigade can do.", "Ba cứ điểm, địch kháng cự yếu. Cho tôi xem lữ đoàn làm được gì."),
            ["radio.khai.c1m05.2"] = ("If that was the prototype, the Bastion will be worse.", "Nếu đó mới là bản nguyên mẫu, Bastion sẽ còn tệ hơn."),
            ["radio.khai.c1m06.1"] = ("The convoy moves when you move. Stay with it.", "Đoàn xe đi khi các anh đi. Bám sát nó."),
            ["radio.khai.c1m07.1"] = ("Silos and water tower. Nothing else matters today.", "Kho lúa và tháp nước. Hôm nay không có gì quan trọng hơn."),
            ["radio.khai.c1m08.1"] = ("The fortress watches this road. Take the town and the depots, and it watches nothing.", "Pháo đài canh con đường này. Chiếm thị trấn và các kho, nó sẽ chẳng còn gì để canh."),
            ["radio.khai.c1m09.1"] = ("No shells, no siege. Keep the trucks moving.", "Không có đạn thì không vây được. Giữ cho đoàn xe chạy."),
            ["radio.khai.c1m10.1"] = ("This is what we landed for. The fortress falls today.", "Ta đổ bộ là vì hôm nay. Pháo đài phải thất thủ."),
            ["radio.khai.c1m10.2"] = ("Ashfield is ours. Chapter one of a long book, Brigade.", "Đồng Tro là của ta. Chương đầu của một cuốn sách dài, Lữ đoàn ạ."),
            ["radio.khai.c1m10.s1"] = ("Fuel depot first. Light it up and their tanks go hungry.", "Kho nhiên liệu trước. Đốt nó đi, xe tăng của chúng sẽ đói."),
            ["radio.khai.c1m10.s4"] = ("The garrison is coming back out of the kilns. Hold where you stand.", "Quân đồn trú đang tràn ra từ các lò nung. Giữ nguyên vị trí."),
            ["radio.khai.c2m01.1"] = ("Five minutes. Dig in round the pumps and let them come.", "Năm phút. Bám quanh các giàn bơm và để chúng tới."),
            ["radio.khai.c2m03.1"] = ("Lights off, engines low. Bring them through.", "Tắt đèn, hạ ga. Đưa họ qua."),
            ["radio.khai.c2m04.1"] = ("Five stations. Every one burns.", "Năm trạm. Trạm nào cũng phải cháy."),
            ["radio.khai.c2m05.p2"] = ("One of Varga's monsters down. The big one is still in the refinery.", "Một con quái vật của Varga đã gục. Con lớn nhất vẫn còn trong nhà máy lọc dầu."),
            ["radio.khai.c2m07.1"] = ("They held for two years. We can hold for them tonight.", "Họ giữ được hai năm. Đêm nay ta giữ cho họ."),
            ["radio.khai.c2m08.1"] = ("Four minutes in the yard. Do not chase them out.", "Bốn phút trong sân. Đừng đuổi theo chúng ra ngoài."),
            ["radio.khai.c2m09.2"] = ("Neither do I.", "Tôi cũng thế."),
            ["radio.khai.c2m10.1"] = ("The refinery burns today, Brigade. Everything inside it too.", "Hôm nay nhà máy lọc dầu phải cháy, Lữ đoàn. Cả những gì bên trong nó."),
            ["radio.khai.c2m10.2"] = ("Varga is running out of fuel, and out of monsters.", "Varga đang cạn dầu, và cạn cả quái vật."),
            ["radio.khai.c2m10.s1"] = ("Oil field and oasis first. Then we choose.", "Mỏ dầu và ốc đảo trước. Rồi ta sẽ chọn."),
            ["radio.khai.c3m01.2"] = ("Keep moving. Coordinates that move are harder to hit.", "Cứ di chuyển. Tọa độ biết chạy thì khó bắn trúng hơn."),
            ["radio.khai.c3m03.1"] = ("We hold the village. They come to us, in the fog.", "Ta giữ ngôi làng. Chúng sẽ tới chỗ ta, trong sương."),
            ["radio.khai.c3m07.1"] = ("Civilians in the cabins. They are the objective.", "Dân thường trong các căn nhà gỗ. Họ chính là mục tiêu."),
            ["radio.khai.c3m10.1"] = ("The line breaks today, or the winter wins. Move.", "Hôm nay tuyến phải vỡ, không thì mùa đông thắng. Tiến lên."),
            ["radio.khai.c3m10.2"] = ("The highlands are open. Act one is done, Brigade.", "Cao nguyên đã mở. Hồi thứ nhất khép lại rồi, Lữ đoàn."),
            ["radio.khai.c3m10.s1"] = ("The hill radar first. Without it, his guns fire blind.", "Radar trên đồi trước. Mất nó, pháo của hắn bắn mù."),
            ["radio.khai.c4m01.2"] = ("Then we will make up the time.", "Vậy thì ta sẽ bù lại số phút đó."),
            ["radio.khai.c4m03.1"] = ("Fog is cover. Use it, and stay with the trucks.", "Sương mù là chỗ ẩn nấp. Tận dụng nó, và bám sát đoàn xe."),
            ["radio.khai.c4m05.2"] = ("Everything on the train. Now.", "Dồn hết vào đoàn tàu. Ngay."),
            ["radio.khai.c4m07.1"] = ("The factories are the objective. Everything else is noise.", "Khu nhà máy là mục tiêu. Mọi thứ khác chỉ là tiếng ồn."),
            ["radio.khai.c4m10.1"] = ("The port, Brigade. All of it, by tonight.", "Bến cảng, Lữ đoàn. Toàn bộ, trước đêm nay."),
            ["radio.khai.c4m10.2"] = ("Ironport is free. Kessler's timetable is ours now.", "Cảng Thép tự do rồi. Thời gian biểu của Kessler giờ thuộc về ta."),
            ["radio.khai.c4m10.s1"] = ("The rail yard first: it is the key to the rest.", "Bãi đường sắt trước: nó là chìa khóa cho phần còn lại."),
            ["radio.khai.c4m11.3"] = ("It is coming in close. Tanks on the pier heads, now.", "Nó đang áp sát. Đưa xe tăng ra đầu cầu tàu, ngay."),
            ["radio.khai.c4m11.4"] = ("Kessler's timetable ends here.", "Thời gian biểu của Kessler kết thúc ở đây."),
            ["radio.khai.c5m03.1"] = ("Eyes up. The fog does not hide you from drones.", "Nhìn lên trời. Sương mù không che được các anh khỏi drone đâu."),
            ["radio.khai.c5m05.2"] = ("Ground guns on it. Keep the aircraft home.", "Pháo mặt đất dồn vào nó. Máy bay ở nhà."),
            ["radio.khai.c5m06.1"] = ("Walls first, then the HQ. The guns do the talking.", "Tường trước, rồi tới sở chỉ huy. Để pháo nói chuyện."),
            ["radio.khai.c5m10.1"] = ("The mothership falls today. Everything else is on the way to it.", "Hôm nay tàu mẹ phải rơi. Mọi thứ khác chỉ là đường tới nó."),
            ["radio.khai.c5m10.2"] = ("Sen is surrendering, Colonel? …Bring her in. Carefully.", "Sen ra hàng à? …Đưa bà ấy về. Cẩn thận."),
            ["radio.khai.c5m10.s1"] = ("The causeways first. They are the only roads over the lava.", "Các đường đắp trước. Đó là những con đường duy nhất vượt qua dung nham."),
            ["radio.khai.c6m01.2"] = ("It was never yours. Hold the walls.", "Nó chưa bao giờ là của ngươi. Giữ tường thành."),
            ["radio.khai.c6m02.1"] = ("Nobody is left behind. Hold the lake.", "Không bỏ lại ai. Giữ hồ băng."),
            ["radio.khai.c6m06.1"] = ("The bridge, four minutes. Nobody crosses.", "Cây cầu, bốn phút. Không ai được qua."),
            ["radio.khai.c6m07.1"] = ("Break the ring. Their HQ first, everything else second.", "Phá vòng vây. Sở chỉ huy của họ trước tiên, mọi thứ khác tính sau."),
            ["radio.khai.c6m08.2"] = ("There it is. Hit it before it reaches the draw.", "Nó đây rồi. Đánh nó trước khi nó lên tới con dốc."),
            ["radio.khai.c6m08.3"] = ("The tide goes out for them tonight.", "Đêm nay thủy triều rút về phía chúng."),
            ["radio.khai.c6m08.p2"] = ("The beach stays ours.", "Bãi biển vẫn là của ta."),
            ["radio.khai.c6m10.1"] = ("The dam, the base, the monster. In that order. Hold.", "Con đập, căn cứ, con quái vật. Theo đúng thứ tự đó. Trụ vững."),
            ["radio.khai.c6m10.2"] = ("The dam holds. Act two is done, Brigade.", "Con đập trụ vững. Hồi thứ hai khép lại rồi, Lữ đoàn."),
            ["radio.khai.c6m10.s1"] = ("The crest first. Whoever holds the dam holds the valley.", "Mặt đập trước. Ai giữ con đập thì giữ cả thung lũng."),
            ["radio.khai.c7m01.2"] = ("It is not your city. Move in.", "Đây không phải thành phố của hắn. Tiến vào."),
            ["radio.khai.c7m03.1"] = ("The city is fighting for itself. We fight with it.", "Thành phố đang tự chiến đấu. Ta chiến đấu cùng nó."),
            ["radio.khai.c7m04.1"] = ("People live in those towers. They stand.", "Có người sống trong những tòa tháp đó. Chúng phải đứng vững."),
            ["radio.khai.c7m05.2"] = ("Everything on the train.", "Dồn hết vào đoàn tàu."),
            ["radio.khai.c7m06.1"] = ("Four minutes on the square. Nobody takes it back.", "Bốn phút trên quảng trường. Không ai được giành lại."),
            ["radio.khai.c7m08.1"] = ("Nobody stays in the palace tonight. Hold the square till the last truck leaves.", "Đêm nay không ai ở lại cung điện. Giữ quảng trường cho tới khi xe cuối cùng rời đi."),
            ["radio.khai.c7m10.1"] = ("The capital, Brigade. Together with the Northern Army.", "Thủ đô, Lữ đoàn. Cùng Tập đoàn quân Phương Bắc."),
            ["radio.khai.c7m10.2"] = ("The capital is free, and the traitor's base is ash. Aurel ran south. We follow.", "Thủ đô đã tự do, căn cứ của kẻ phản bội thành tro. Aurel chạy về phía nam. Ta đuổi theo."),
            ["radio.khai.c7m10.s4"] = ("{@lyhan} has turned! Hold the square, Brigade. Hold.", "{@lyhan} trở mặt rồi! Giữ quảng trường, Lữ đoàn. Trụ vững."),
            ["radio.khai.c7m10.s5"] = ("His base is marked. Now we strike back.", "Căn cứ của hắn đã được đánh dấu. Giờ ta phản đòn."),
            ["radio.khai.c8m01.1"] = ("He ran north. We follow.", "Hắn chạy lên phía bắc. Ta đuổi theo."),
            ["radio.khai.c8m04.1"] = ("They rose for us. We go for them.", "Họ đứng lên vì ta. Ta tới vì họ."),
            ["radio.khai.c8m10.1"] = ("Into the pit, Brigade.", "Xuống hố, Lữ đoàn."),
            ["radio.khai.c9m01.1"] = ("The port again. This time we keep it.", "Lại bến cảng. Lần này ta giữ nó."),
            ["radio.khai.c9m02.1"] = ("We know this beach. Better than he does.", "Ta biết bãi biển này. Rõ hơn hắn."),
            ["radio.khai.c9m07.1"] = ("Keep one standing. That is all we need.", "Giữ một trạm đứng vững. Ta chỉ cần thế."),
            ["radio.khai.c9m10.1"] = ("This ends at sea, Brigade.", "Chuyện này kết thúc trên biển, Lữ đoàn."),
            ["radio.khai.gen.boss.2"] = ("There it is. Everything on it.", "Nó đây rồi. Dồn hết vào nó."),
            ["radio.khai.gen.bossHalf.1"] = ("It is burning. Keep hitting it.", "Nó đang cháy. Tiếp tục nện."),
            ["radio.khai.gen.capture.1"] = ("Objective taken. Dig in.", "Đã chiếm cứ điểm. Bám trụ."),
            ["radio.khai.gen.capture.2"] = ("Good. That one is ours now.", "Tốt. Chỗ đó là của ta rồi."),
            ["radio.khai.gen.capture.3"] = ("Point secured. Keep moving.", "Cứ điểm đã an toàn. Tiếp tục tiến."),
            ["radio.khai.gen.hqHalf.2"] = ("They are on the HQ. Bring the army home.", "Chúng đang đánh vào sở chỉ huy. Kéo quân về."),
            ["radio.khai.gen.lose.1"] = ("Pull back. We regroup and go again.", "Rút về. Tập hợp lại rồi đánh tiếp."),
            ["radio.khai.gen.lost.1"] = ("We have lost a point. Take it back.", "Ta mất một cứ điểm. Chiếm lại ngay."),
            ["radio.khai.gen.stage.1"] = ("Next objective. Move.", "Mục tiêu tiếp theo. Di chuyển."),
            ["radio.khai.gen.win.1"] = ("Well done, Brigade. Rest while you can.", "Làm tốt lắm, Lữ đoàn. Nghỉ được lúc nào thì nghỉ."),
            ["radio.khai.gen.win.2"] = ("That is how it is done.", "Đánh là phải thế."),
            ["radio.linh.c10m02.1"] = ("Look at the hangars. All of them.", "Nhìn các nhà chứa máy bay. Tất cả."),
            ["radio.linh.c10s2.1"] = ("Three places. Look for a parachute.", "Ba nơi. Tìm một chiếc dù."),
            ["radio.linh.c11m02.1"] = ("Every station. I need all of them.", "Mọi trạm. Tôi cần tất cả."),
            ["radio.linh.c11m05.1"] = ("Gungnir is on the east rails. Watch the ground: where it cracks red, a shell lands three seconds later.", "Gungnir nằm trên đường ray phía đông. Để ý mặt đất: chỗ nào nứt đỏ, ba giây sau đạn rơi xuống đó."),
            ["radio.linh.c11s1.1"] = ("Fuel trucks, marked. Every one counts.", "Xe nhiên liệu, đã đánh dấu. Chiếc nào cũng quan trọng."),
            ["radio.linh.c12m07.1"] = ("Three trucks. Every one of them counts.", "Ba xe tải. Chiếc nào cũng quan trọng."),
            ["radio.linh.c12m08.1"] = ("Four radars. The storm hides you as much as them.", "Bốn trạm radar. Bão cát che các anh cũng như che chúng."),
            ["radio.linh.c12m10.s5"] = ("The launch countdown has started. Everything Aurel has left is coming at us. Hold!", "Đếm ngược phóng đã bắt đầu. Mọi thứ Aurel còn lại đang dồn vào ta. Trụ vững!"),
            ["radio.linh.c1m02.1"] = ("The radar is on the bluffs. Its crew changes shift every hour; we will not get a better window.", "Radar nằm trên vách đá. Kíp trực đổi ca mỗi giờ; ta sẽ không có cơ hội nào tốt hơn đâu."),
            ["radio.linh.c1m03.2"] = ("The crossroads is ours. Every road inland runs through here now.", "Ngã tư là của ta. Giờ mọi con đường vào nội địa đều đi qua đây."),
            ["radio.linh.c1m05.1"] = ("Large contact moving on the camp. Brandt's prototype.", "Mục tiêu cỡ lớn đang tiến về trại. Bản nguyên mẫu của Brandt."),
            ["radio.linh.c1m06.2"] = ("Raiders on the north road. They are after the trucks, not you.", "Quân đột kích trên đường phía bắc. Chúng nhắm vào xe tải, không phải các anh."),
            ["radio.linh.c1m08.2"] = ("They have retaken a depot. They want that fuel badly.", "Chúng chiếm lại một kho rồi. Chúng thèm chỗ nhiên liệu đó lắm."),
            ["radio.linh.c1s1.1"] = ("Three farms, three looks. Nobody fights unless they must.", "Ba trang trại, ba lần nhìn. Không ai đánh nhau trừ khi bắt buộc."),
            ["radio.linh.c1s2.1"] = ("Three marked targets. They move between shots; so should we.", "Ba mục tiêu được đánh dấu. Chúng di chuyển giữa các loạt bắn; ta cũng nên thế."),
            ["radio.linh.c2m02.1"] = ("Varga's own tanks at the oasis. He is here, Colonel. In person.", "Xe tăng của chính Varga ở ốc đảo. Hắn ở đây, đại tá. Đích thân."),
            ["radio.linh.c2m06.1"] = ("Three batteries, marked. They move; we move faster.", "Ba khẩu đội, đã đánh dấu. Chúng di chuyển; ta di chuyển nhanh hơn."),
            ["radio.linh.c2m07.2"] = ("The garrison's HQ is taking fire. Hurry.", "Sở chỉ huy của đồn đang trúng đạn. Nhanh lên."),
            ["radio.linh.c2s1.1"] = ("Three looks. Their mines are the target, not their tanks.", "Ba lần nhìn. Mìn của chúng là mục tiêu, không phải xe tăng."),
            ["radio.linh.c3m02.1"] = ("Heavy tank and SAMs round the radar. Orlov guards his eyes.", "Xe tăng hạng nặng và tên lửa phòng không quanh radar. Orlov canh mắt của hắn kỹ lắm."),
            ["radio.linh.c3m06.1"] = ("Three batteries. They shoot, they move, they shoot. Be quicker than the second shot.", "Ba khẩu đội. Chúng bắn, chúng chạy, chúng lại bắn. Phải nhanh hơn loạt thứ hai."),
            ["radio.linh.c3m08.1"] = ("The wounded cannot wait for daylight. Neither can we.", "Thương binh không đợi được tới sáng. Ta cũng thế."),
            ["radio.linh.c3s1.1"] = ("Look and leave. The fog helps both sides.", "Nhìn rồi rút. Sương mù giúp cả hai bên đấy."),
            ["radio.linh.c3s2.1"] = ("Fenrir is in the snow. It sees for Orlov's guns.", "Fenrir ở trong tuyết. Nó là mắt cho pháo của Orlov."),
            ["radio.linh.c4m02.1"] = ("Three objectives, all dug in. Take the factories first and build there.", "Ba cứ điểm, cứ điểm nào cũng cố thủ. Chiếm khu nhà máy trước rồi dựng tiền đồn ở đó."),
            ["radio.linh.c4m04.1"] = ("Three looks. Count the wagons if you can.", "Ba lần quan sát. Đếm được toa tàu thì càng tốt."),
            ["radio.linh.c4m08.1"] = ("Three marked vehicles, moving slowly. Where they have been, drive carefully.", "Ba xe được đánh dấu, đi chậm. Đường chúng đã qua, lái cẩn thận."),
            ["radio.linh.c4m11.1"] = ("Leviathan is on the far lane. We cannot see its fleet from the beach: the lighthouse can.", "Leviathan đang ở tuyến xa. Từ bãi biển ta không thấy hạm đội của nó: ngọn hải đăng thì thấy."),
            ["radio.linh.c4s1.1"] = ("The prisoners are at the scrapyard. Bring them home.", "Tù binh đang ở bãi phế liệu. Đưa họ về nhà."),
            ["radio.linh.c4s2.1"] = ("Two command cars, marked. They talk a lot; that is how I found them.", "Hai xe chỉ huy, đã đánh dấu. Chúng nói nhiều lắm; tôi tìm ra chúng là nhờ thế."),
            ["radio.linh.c5m01.2"] = ("That was Dr Sen, on an open channel. She wanted us to hear.", "Đó là tiến sĩ Sen, trên kênh mở. Bà ấy muốn ta nghe thấy."),
            ["radio.linh.c5m02.1"] = ("Three launch trucks. Kill the trucks and the swarms stop coming.", "Ba xe phóng. Diệt được xe là bầy drone thôi kéo tới."),
            ["radio.linh.c5m08.1"] = ("These drones are not Sen's launch codes. Aurel is running them himself.", "Những drone này không dùng mã phóng của Sen. Aurel đang tự điều khiển chúng."),
            ["radio.linh.c5m08.p1"] = ("Locust: one of Sen's small drone carriers. Shoot it down.", "Locust: một tàu mang drone cỡ nhỏ của Sen. Bắn hạ nó."),
            ["radio.linh.c5s1.1"] = ("Look for anything painted orange.", "Tìm bất cứ thứ gì sơn màu cam."),
            ["radio.linh.c5s2.1"] = ("They held for two years. Their HQ cannot hold much longer.", "Họ giữ được hai năm. Sở chỉ huy của họ không trụ được lâu nữa đâu."),
            ["radio.linh.c6m02.2"] = ("Half the trucks are out. Varga is pushing harder.", "Một nửa số xe đã thoát. Varga đang dồn ép mạnh hơn."),
            ["radio.linh.c6m04.1"] = ("Varga's scouts are at the power station already.", "Trinh sát của Varga đã tới trạm phát điện rồi."),
            ["radio.linh.c6m08.p1"] = ("Charybdis, on the water. It is coming for our beach.", "Charybdis, trên mặt nước. Nó đang nhắm vào bãi biển của ta."),
            ["radio.linh.c6s2.1"] = ("Three looks for the engineers. Quickly, Varga is not far.", "Ba lần quan sát cho công binh. Nhanh lên, Varga không ở xa đâu."),
            ["radio.linh.c7m02.1"] = ("Three looks. And note anyone else who is looking too.", "Ba lần quan sát. Và ghi lại bất cứ ai khác cũng đang quan sát."),
            ["radio.linh.c7m05.1"] = ("The train is on the northern line. Sixty seconds once it stops.", "Đoàn tàu đang trên tuyến phía bắc. Nó dừng là còn sáu mươi giây."),
            ["radio.linh.c7m07.1"] = ("Three command cars. Without them, the garrison breaks.", "Ba xe chỉ huy. Mất chúng, quân đồn trú sẽ vỡ."),
            ["radio.linh.c7s1.1"] = ("This one stays off the record, Colonel.", "Chuyện này không ghi vào hồ sơ, đại tá."),
            ["radio.linh.c8m03.1"] = ("Three batteries, marked. They know our tricks.", "Ba khẩu đội, đã đánh dấu. Chúng biết các mẹo của ta."),
            ["radio.linh.c8m05.1"] = ("Seismic contact under the valley, moving west. That is Tartarus.", "Tín hiệu địa chấn dưới thung lũng, đang di chuyển về phía tây. Đó là Tartarus."),
            ["radio.linh.c8m07.1"] = ("Ixion. Break a wheel and it loses its line.", "Ixion. Phá một bánh là nó mất hướng."),
            ["radio.linh.c8m08.1"] = ("Look, do not linger.", "Nhìn thôi, đừng nán lại."),
            ["radio.linh.c8m10.2"] = ("{@lyhan} has reached the coast. He is heading for Kessler's old ships.", "{@lyhan} đã tới bờ biển. Hắn đang tìm tới những con tàu cũ của Kessler."),
            ["radio.linh.c8s1.1"] = ("Three buildings. Quick in, quick out.", "Ba tòa nhà. Vào nhanh, ra nhanh."),
            ["radio.linh.c9m03.1"] = ("Patrols on the harbour road. Keep moving.", "Lính tuần trên đường bến cảng. Cứ đi tiếp."),
            ["radio.linh.c9m05.1"] = ("Caspian, low over the water. Fast.", "Caspian, bay thấp trên mặt nước. Rất nhanh."),
            ["radio.linh.c9m09.1"] = ("Mortar teams, marked. Move fast.", "Các tổ súng cối, đã đánh dấu. Di chuyển nhanh."),
            ["radio.linh.c9m10.3"] = ("His papers mention one thing again and again: Project Icarus.", "Giấy tờ của hắn cứ nhắc mãi một thứ: Dự án Icarus."),
            ["radio.linh.c9s1.1"] = ("They run on schedule. We will be early.", "Chúng chạy đúng giờ. Ta sẽ tới sớm."),
            ["radio.linh.c9s2.1"] = ("I want their radios intact.", "Tôi cần bộ đàm của chúng còn nguyên."),
            ["radio.linh.gen.boss.1"] = ("Large contact. That is the boss: focus fire.", "Mục tiêu cỡ lớn. Đó là boss: tập trung hỏa lực."),
            ["radio.linh.gen.lost.2"] = ("Enemy flag on one of our objectives.", "Cờ địch đã cắm trên một cứ điểm của ta."),
            ["radio.linh.gen.reinforce.1"] = ("Enemy reinforcements dropping at their camp.", "Viện binh địch đang nhảy dù xuống trại của chúng."),
            ["radio.linh.gen.reinforce.2"] = ("More of them coming in by air.", "Thêm quân địch đang được thả xuống."),
            ["radio.mai.c11m04.1"] = ("Find the pads. I will bring the spanners.", "Tìm các bệ phóng. Tôi sẽ mang cờ lê."),
            ["radio.mai.c11m05.2"] = ("Take out its targeting station and its shells go wide.", "Phá trạm chỉ thị mục tiêu của nó là đạn sẽ rơi lệch."),
            ["radio.mai.c11s2.1"] = ("Get my engineers there in one piece.", "Đưa công binh của tôi tới nơi nguyên vẹn."),
            ["radio.mai.c1m04.1"] = ("Give me that crossroads and a few minutes of quiet, Colonel, and I will give you a base.", "Cho tôi cái ngã tư đó và vài phút yên tĩnh, đại tá, tôi sẽ trả lại ông một căn cứ."),
            ["radio.mai.c1m04.2"] = ("Ground is ours. Towers coming down, keep them off my crews!", "Đất là của ta rồi. Tháp đang thả xuống, đừng để chúng đụng vào người của tôi!"),
            ["radio.mai.c1m04.3"] = ("It holds. Welcome to your new HQ, Colonel. The coffee is terrible.", "Trụ được rồi. Chào mừng tới sở chỉ huy mới, đại tá. Cà phê dở tệ."),
            ["radio.mai.c1m07.2"] = ("Storm is getting worse. So is their aim, lucky for us.", "Bão càng lúc càng to. Bắn của chúng cũng càng tệ, may cho mình."),
            ["radio.mai.c1m10.s3"] = ("That is the Bastion. Early model: thin rear plates. Hit it from behind!", "Đó là Bastion. Mẫu đời đầu: giáp sau mỏng. Đánh từ phía sau!"),
            ["radio.mai.c2m05.2"] = ("Rear plates, Colonel. I know, because I put them there.", "Giáp sau, đại tá. Tôi biết, vì chính tôi lắp chúng."),
            ["radio.mai.c2m05.3"] = ("It is slowing. The engine block is exposed!", "Nó chậm lại rồi. Khối động cơ lộ ra rồi!"),
            ["radio.mai.c3m04.1"] = ("The ice holds towers. I checked. Mostly.", "Băng chịu được tháp. Tôi kiểm tra rồi. Gần như chắc chắn."),
            ["radio.mai.c4m11.2"] = ("Its sides will stop anything we have. Its deck will not: artillery and bombs.", "Hông tàu chặn được mọi thứ ta có. Boong thì không: pháo binh và bom."),
            ["radio.mai.c5m04.1"] = ("Forty megawatts under our feet. Give me the plant.", "Bốn mươi mê-ga-oát ngay dưới chân. Cho tôi nhà máy đó."),
            ["radio.mai.c6m03.1"] = ("She runs, Colonel. Slowly, loudly, but she runs. Keep her in one piece.", "Nó chạy rồi, đại tá. Chậm, ồn, nhưng chạy được. Giữ cho nó nguyên vẹn."),
            ["radio.mai.c6m03.3"] = ("She made it. I may cry. Do not tell anyone.", "Nó tới nơi rồi. Chắc tôi khóc mất. Đừng kể với ai nhé."),
            ["radio.mai.c6m05.1"] = ("They patched it. Badly. The rear plates are still mine.", "Chúng vá lại nó rồi. Vá ẩu. Giáp sau vẫn là của tôi."),
            ["radio.mai.c8m02.1"] = ("No ore, no new tanks for him. Hold it.", "Không có quặng, hắn hết xe tăng mới. Giữ lấy nó."),
            ["radio.mai.c8m05.2"] = ("Hit it when it surfaces. The drill head is armour; the back is not.", "Đánh nó khi nó trồi lên. Đầu khoan là giáp; phía sau thì không."),
            ["radio.mai.c8m05.p2"] = ("Tartarus is stuck in its own tunnel.", "Tartarus kẹt luôn trong đường hầm của nó."),
            ["radio.mai.c9m04.1"] = ("Same guns. Same weak mounts.", "Vẫn những khẩu pháo đó. Vẫn những bệ yếu đó."),
            ["radio.mai.gen.bossHalf.2"] = ("Half its plates are gone. Aim for the seams!", "Nửa lớp giáp của nó bay rồi. Nhắm vào đường hàn!"),
            ["radio.mai.gen.hqHalf.1"] = ("HQ at half strength! I can't patch it that fast!", "Sở chỉ huy còn một nửa! Tôi vá không kịp đâu!"),
            ["radio.orlov.c11m05.p1"] = ("Gungnir has your grid, Colonel. Fire mission.", "Gungnir có tọa độ của ngươi rồi, đại tá. Nhiệm vụ bắn."),
            ["radio.orlov.c11m05.p2"] = ("Recalculating… no. Cease fire. It is over.", "Tính lại… không. Ngừng bắn. Hết rồi."),
            ["radio.orlov.c12m04.1"] = ("Fire mission. The last one. All batteries.", "Nhiệm vụ bắn. Lần cuối. Toàn bộ khẩu đội."),
            ["radio.orlov.c12m04.2"] = ("Cease fire. …Cease fire.", "Ngừng bắn. …Ngừng bắn."),
            ["radio.orlov.c3m01.1"] = ("Welcome to the highlands, Colonel. You are a coordinate now.", "Chào mừng tới cao nguyên, đại tá. Giờ ngươi chỉ là một tọa độ."),
            ["radio.orlov.c3m04.2"] = ("A base on a lake. How poetic. How flammable.", "Căn cứ trên mặt hồ. Thật nên thơ. Thật dễ cháy."),
            ["radio.orlov.c3m05.2"] = ("Look up, Colonel. The coordinate has arrived.", "Nhìn lên đi, đại tá. Tọa độ đã tới."),
            ["radio.orlov.c3m06.2"] = ("You found my guns. Remarkable. Also irrelevant.", "Ngươi tìm ra pháo của ta. Đáng nể. Nhưng cũng chẳng để làm gì."),
            ["radio.orlov.c3m09.1"] = ("Fire mission. Grid one-seven. All batteries.", "Nhiệm vụ bắn. Ô lưới một-bảy. Toàn bộ khẩu đội."),
            ["radio.orlov.c3m09.2"] = ("Recalculating. Withdraw the batteries to the next line.", "Tính lại. Rút các khẩu đội về tuyến sau."),
            ["radio.orlov.c3m10.s4"] = ("Jötunn will hold the gate. It always has.", "Jötunn sẽ giữ cổng. Xưa nay vẫn thế."),
            ["radio.orlov.c3m10.s5"] = ("All batteries, the gate. Bury them in it.", "Toàn bộ khẩu đội, nhắm cổng. Chôn chúng ở đó."),
            ["radio.orlov.defeat"] = ("Recalculating. Withdraw the batteries to the next line.", "Tính lại. Rút các khẩu đội về tuyến sau."),
            ["radio.orlov.taunt.1"] = ("You are a coordinate, nothing more.", "Ngươi chỉ là một tọa độ, không hơn."),
            ["radio.orlov.taunt.2"] = ("Fire mission. Grid one-seven. All batteries.", "Nhiệm vụ bắn. Ô lưới một-bảy. Toàn bộ khẩu đội."),
            ["radio.orlov.taunt.3"] = ("Patience, Colonel. The snow is on my side.", "Kiên nhẫn đi, đại tá. Tuyết đứng về phía ta."),
            ["radio.quaden.c10m01.1"] = ("{@dieuhau}! Still flying that museum piece?", "{@dieuhau}! Vẫn lái cái đồ cổ đó à?"),
            ["radio.quaden.c10m07.1"] = ("Look up, Colonel. That is where you lose.", "Nhìn lên đi, đại tá. Ông sẽ thua ở trên đó."),
            ["radio.quaden.c10m09.1"] = ("The sky is mine. You can keep the mud.", "Bầu trời là của ta. Bùn đất thì cứ giữ lấy."),
            ["radio.quaden.c10m09.2"] = ("Eject, eject! …Not like this.", "Nhảy dù, nhảy dù! …Không phải thế này chứ."),
            ["radio.quaden.c10m10.s3"] = ("The airship sees everything, Colonel. Everything.", "Roc nhìn thấy mọi thứ, đại tá. Mọi thứ."),
            ["radio.quaden.c12m06.1"] = ("One more time, {@dieuhau}. For the old days.", "Thêm một lần nữa, {@dieuhau}. Vì ngày xưa."),
            ["radio.quaden.defeat"] = ("Eject, eject! …Not like this.", "Nhảy dù, nhảy dù! …Không phải thế này chứ."),
            ["radio.quaden.taunt.1"] = ("{@dieuhau}! Still flying that museum piece?", "{@dieuhau}! Vẫn lái cái đồ cổ đó à?"),
            ["radio.quaden.taunt.2"] = ("Look up, Colonel. That is where you lose.", "Nhìn lên đi, đại tá. Ông sẽ thua ở trên đó."),
            ["radio.quaden.taunt.3"] = ("The sky is mine. You can keep the mud.", "Bầu trời là của ta. Bùn đất thì cứ giữ lấy."),
            ["radio.sen.c10m05.1"] = ("It is faster than anything we have. Keep up the fire before it climbs out of range.", "Nó nhanh hơn bất cứ thứ gì ta có. Cứ bắn liên tục trước khi nó bay vượt tầm."),
            ["radio.sen.c10s1.1"] = ("Whatever is in those trucks, Aurel cannot replace it easily. Stop them.", "Bất cứ thứ gì trong những xe đó, Aurel cũng không dễ thay thế. Chặn chúng lại."),
            ["radio.sen.c11m07.1"] = ("Locust. Aurel finished my design.", "Locust. Aurel đã làm nốt thiết kế của tôi."),
            ["radio.sen.c12m05.1"] = ("That is the one from Skyhold Airbase, repaired and stronger. Watch its altitude: it is easiest to hit when it comes down low.", "Chính là chiếc ở Căn Cứ Tầng Mây, đã sửa xong và mạnh hơn. Theo dõi tầng độ cao của nó: nó dễ bắn nhất khi hạ xuống thấp."),
            ["radio.sen.c12m05.p1"] = ("That is my design. Aim for the hangar doors.", "Đó là thiết kế của tôi. Nhắm vào cửa khoang chứa."),
            ["radio.sen.c12m10.s6"] = ("That is 01, complete. It will climb past what most of you can reach. Watch the altitude, and do not let it level out.", "Đó là chiếc 01, hoàn chỉnh. Nó sẽ bay lên qua tầm với của phần lớn vũ khí các anh có. Theo dõi tầng độ cao, đừng để nó bay ổn định."),
            ["radio.sen.c12s1.1"] = ("I built half of what you will see. Look closely.", "Một nửa những gì các anh sắp thấy là do tôi chế tạo. Nhìn cho kỹ."),
            ["radio.sen.c5m01.1"] = ("The swarm does not hate you, Colonel. It does not anything.", "Bầy drone không ghét các anh, đại tá. Nó chẳng có cảm xúc gì cả."),
            ["radio.sen.c5m04.2"] = ("You are sitting on a volcano, Engineer. I would not get comfortable.", "Cô đang ngồi trên núi lửa đấy, kỹ sư. Tôi mà là cô thì không ngồi yên đâu."),
            ["radio.sen.c5m05.1"] = ("Seven hundred drones in the air. Count them if you like.", "Bảy trăm drone đang trên trời. Các anh cứ đếm nếu thích."),
            ["radio.sen.c5m05.3"] = ("Enough. Stand the swarm down.", "Đủ rồi. Cho bầy drone hạ cánh."),
            ["radio.sen.c5m09.1"] = ("I designed this to save people. Remember that when it kills you.", "Tôi thiết kế thứ này để cứu người. Hãy nhớ điều đó khi nó giết các anh."),
            ["radio.sen.c5m09.2"] = ("Enough.", "Đủ rồi."),
            ["radio.sen.c5m10.end"] = ("Colonel. This is Sen. I am coming out. Do not shoot.", "Đại tá. Sen đây. Tôi đang đi ra. Đừng bắn."),
            ["radio.sen.c5m10.s3"] = ("Aurel has taken the swarm from me. I cannot stop it. Survive it.", "Aurel đã lấy bầy drone khỏi tay tôi. Tôi không dừng nó được. Hãy trụ vững."),
            ["radio.sen.defeat"] = ("Enough. Stand the swarm down.", "Đủ rồi. Cho bầy drone hạ cánh."),
            ["radio.sen.taunt.1"] = ("The swarm does not hate you. It does not anything.", "Bầy drone không ghét các anh. Nó chẳng có cảm xúc gì cả."),
            ["radio.sen.taunt.2"] = ("Seven hundred drones in the air. Count them if you like.", "Bảy trăm drone đang trên trời. Các anh cứ đếm nếu thích."),
            ["radio.sen.taunt.3"] = ("I designed this to save people. Remember that when it kills you.", "Tôi thiết kế thứ này để cứu người. Hãy nhớ điều đó khi nó giết các anh."),
            ["radio.varga.c12m01.1"] = ("Colonel. We meet in the sand again. The last time, I think.", "Đại tá. Ta lại gặp nhau trên cát. Lần cuối, ta nghĩ vậy."),
            ["radio.varga.c12m03.1"] = ("Steel does not negotiate. But it can be tired, Colonel.", "Thép không biết thương lượng. Nhưng thép cũng biết mệt, đại tá ạ."),
            ["radio.varga.c12m03.2"] = ("Enough. Let the machines rest.", "Đủ rồi. Để những cỗ máy được nghỉ."),
            ["radio.varga.c12m10.s4"] = ("One more Behemoth, Colonel. The last one.", "Thêm một chiếc Behemoth nữa, đại tá. Chiếc cuối cùng."),
            ["radio.varga.c2m01.2"] = ("Who is burning my oil? Find them. Crush them.", "Kẻ nào đang đốt dầu của ta? Tìm ra. Nghiền nát."),
            ["radio.varga.c2m02.2"] = ("Take the sand if you like. The sand does not care.", "Lấy cát nếu thích. Cát chẳng quan tâm đâu."),
            ["radio.varga.c2m04.2"] = ("My pipeline! You will pay by the barrel.", "Đường ống của ta! Ngươi sẽ trả giá theo từng thùng."),
            ["radio.varga.c2m05.1"] = ("Colonel {@khai}. Meet the Behemoth. It does not negotiate either.", "Đại tá {@khai}. Chào Behemoth đi. Nó cũng không biết thương lượng đâu."),
            ["radio.varga.c2m05.4"] = ("Retreat. Save the machines. The men can walk.", "Rút. Giữ lấy máy móc. Người thì đi bộ cũng được."),
            ["radio.varga.c2m05.p1"] = ("You want fire, Colonel? Here is fire.", "Muốn lửa hả, đại tá? Lửa đây."),
            ["radio.varga.c2m08.2"] = ("Burn them out of my refinery!", "Đốt chúng ra khỏi nhà máy của ta!"),
            ["radio.varga.c2m09.1"] = ("Steel does not negotiate, Colonel.", "Thép không biết thương lượng, đại tá ạ."),
            ["radio.varga.c2m09.3"] = ("Retreat. Save the machines.", "Rút. Giữ lấy máy móc."),
            ["radio.varga.c2m10.s5"] = ("My Behemoth, Colonel. Look at it closely.", "Behemoth của ta đây, đại tá. Nhìn cho kỹ."),
            ["radio.varga.c2m10.s6"] = ("Every tank I have left, to the refinery. Now!", "Toàn bộ xe tăng còn lại, tới nhà máy lọc dầu. Ngay!"),
            ["radio.varga.c6m01.1"] = ("You took my fortress. I have come to collect it.", "Ngươi lấy pháo đài của ta. Ta tới lấy lại đây."),
            ["radio.varga.c6m03.2"] = ("That is MY machine! Burn it!", "Đó là cỗ máy của TA! Đốt nó đi!"),
            ["radio.varga.c6m05.2"] = ("I fixed her, Colonel. I always fix her.", "Ta đã sửa lại nó, đại tá. Ta luôn sửa được nó."),
            ["radio.varga.c6m09.1"] = ("Every tank you burn, I build two.", "Ngươi đốt một chiếc, ta đóng hai chiếc."),
            ["radio.varga.c6m09.2"] = ("Fall back to the dam. Moloch will finish this.", "Rút về con đập. Moloch sẽ kết thúc chuyện này."),
            ["radio.varga.c6m10.s3"] = ("Moloch builds faster than you can burn, Colonel.", "Moloch đóng xe nhanh hơn ngươi đốt, đại tá."),
            ["radio.varga.defeat"] = ("Retreat. Save the machines. The men can walk.", "Rút. Giữ lấy máy móc. Người thì đi bộ cũng được."),
            ["radio.varga.taunt.1"] = ("Steel does not negotiate, Colonel.", "Thép không biết thương lượng, đại tá ạ."),
            ["radio.varga.taunt.2"] = ("Every tank you burn, I build two.", "Ngươi đốt một chiếc, ta đóng hai chiếc."),
            ["radio.varga.taunt.3"] = ("Come closer. My guns are lonely.", "Lại gần đây. Pháo của ta đang buồn lắm."),
