            ["timeline.0"] = ("Two years ago: the Night of Steel. Hegemon seizes the Lam Hai coast; Director Aurel declares the \"Protectorate\".", "Hai năm trước: Đêm Thép. Hegemon chiếm dải duyên hải Lam Hải; giám đốc Aurel tuyên bố thành lập \"Chính quyền Bảo hộ\"."),
            ["timeline.1"] = ("The brigade lands at Landing Beach, sets up its first base in Greenvale and storms the Ashfield fortress, bringing down the Bastion.", "Lữ đoàn đổ bộ ở Bãi Đổ Bộ, dựng căn cứ đầu tiên ở Lũng Xanh rồi đánh chiếm pháo đài Đồng Tro, hạ gục Bastion."),
            ["timeline.10"] = ("Icarus shows itself and runs; Wolff is shot down, and Skyhold Airbase falls with Roc, his command airship.", "Icarus lộ diện rồi bỏ chạy; Wolff bị bắn rơi, Căn Cứ Tầng Mây thất thủ cùng Roc, khí cầu chỉ huy của hắn."),
            ["timeline.11"] = ("Orlov's Gungnir is silenced and Daedalus falls on the gate it guarded. Only the launch site is left.", "Gungnir của Orlov câm họng và Daedalus rơi xuống chính cửa ngõ nó canh giữ. Chỉ còn lại bãi phóng."),
            ["timeline.12"] = ("Icarus turns back from orbit and crashes in the desert. Hegemon is finished, and the Lam Hai coast is free.", "Icarus quay lại từ quỹ đạo và rơi xuống sa mạc. Hegemon sụp đổ, dải duyên hải Lam Hải được tự do."),
            ["timeline.2"] = ("Varga shows himself at Dunebreak; his Behemoth falls in a sandstorm, and the refinery burns with the Inferno inside it.", "Varga lộ mặt ở Đồi Cát; Behemoth của hắn gục trong bão cát, còn nhà máy lọc dầu bốc cháy cùng Inferno bên trong."),
            ["timeline.3"] = ("The brigade blinds Orlov's radar line, brings Harpy down in the snow and breaks through at Frostpeak, past Jötunn.", "Lữ đoàn làm mù tuyến radar của Orlov, bắn rơi Harpy trên tuyết và chọc thủng Đỉnh Sương Giá, vượt qua Jötunn."),
            ["timeline.4"] = ("Kessler's timetable breaks: Juggernaut is derailed, Gungnir silenced, and the port taken from Tempest on its own docks.", "Thời gian biểu của Kessler đổ vỡ: Juggernaut bị lật, Gungnir câm họng, bến cảng bị chiếm từ tay Tempest ngay trên cầu tàu."),
            ["timeline.5"] = ("The Hive and its mothership fall over Ember Ridge. Dr Sen walks out of the burning drone works and gives herself up, with the Icarus files.", "Hive và tàu mẹ của nó rơi trên Sườn Dung Nham. Tiến sĩ Sen bước ra khỏi xưởng drone đang cháy và ra hàng, mang theo hồ sơ Icarus."),
            ["timeline.6"] = ("The counterstrike breaks on the Hydro Dam: Moloch goes into the gorge and General {@lyhan}'s army arrives in time.", "Đợt tổng phản công vỡ tan trước Đập Thủy Điện: Moloch lao xuống hẻm sông, và đạo quân của tướng {@lyhan} tới kịp."),
            ["timeline.7"] = ("The capital is freed, but {@lyhan} turns on the brigade in the middle of the battle. His base falls; he escapes north to the mines.", "Thủ đô được giải phóng, nhưng {@lyhan} trở mặt với lữ đoàn ngay giữa trận. Căn cứ của hắn thất thủ; hắn trốn lên các khu mỏ phía bắc."),
            ["timeline.8"] = ("The brigade follows {@lyhan} into the mines; Tartarus and Ixion fall, and Kronos is buried in its own pit. {@lyhan} escapes again, to the sea.", "Lữ đoàn đuổi theo {@lyhan} vào khu mỏ; Tartarus và Ixion gục ngã, Kronos bị chôn vùi trong chính hố mỏ của nó. {@lyhan} lại trốn thoát, ra biển."),
            ["timeline.9"] = ("Typhon goes down off the coast and {@lyhan} is taken on his own flagship. Act III ends; in his papers {@linh} finds two words: Project Icarus.", "Typhon chìm ngoài khơi và {@lyhan} bị bắt ngay trên soái hạm của hắn. Hồi III khép lại; trong giấy tờ của hắn, {@linh} tìm thấy hai chữ: Dự án Icarus."),
        };

